-- Generated by scripts/export-supabase-seed.ts from content/minecraft/minecraft-question-bank.v1.json.
-- Do not edit by hand: change the master bank, then run `npm run export:content`.

insert into public.quiz_categories (slug, title)
values ('minecraft', 'MineMind Fan Quiz')
on conflict (slug) do nothing;

insert into public.question_packs (category_id, locale, age_band, difficulty, title, slug, is_active)
select id, 'uk', '8-12', 'easy', 'MineMind uk easy', 'minecraft-uk-easy', true
from public.quiz_categories
where slug = 'minecraft'
on conflict (slug) do update set is_active = true, title = excluded.title;

insert into public.questions (pack_id, content_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, sort_order, is_active)
select pack.id, v.content_id, v.prompt, v.option_a, v.option_b, v.option_c, v.option_d, v.correct_option, v.explanation, v.sort_order, v.is_active
from public.question_packs pack
cross join (values
  ('badlands-has-terracotta', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. Класичним знаком якого біома є теракотові пагорби? За цією ситуацією визнач правильну місцевість або споруду.', 'Болото', 'Рівнини', 'Безплідні землі', 'Засніжені рівнини', 2, 'Безплідні землі легко впізнати за шарами теракоти та рельєфом, схожим на месу. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 1, false),
  ('bamboo-jungle-has-bamboo', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. У записнику гравця є така польова підказка: Який біом найімовірніше заповнений бамбуком? За цією ситуацією визнач правильну місцевість або споруду.', 'Бамбукові джунглі', 'Замерзлий океан', 'Темні глибини', 'Рівнини', 0, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 2, false),
  ('beach-is-sandy-shore', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. У записнику гравця є така польова підказка: Який біом зазвичай утворює піщану смугу вздовж океану? За цією ситуацією визнач правильну місцевість або споруду.', 'Меса', 'Пляж', 'Лука', 'Річка', 1, 'Пляжі зазвичай утворюють піщані береги вздовж океанів та інших великих водойм. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 3, false),
  ('cherry-grove-has-pink-trees', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. У записнику гравця є така польова підказка: Який біом виділяється рожевими вишневими деревами? За цією ситуацією визнач правильну місцевість або споруду.', 'Незерська пустка', 'Болото', 'Вишневий гай', 'Скелястий берег', 2, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 4, false),
  ('desert-has-no-rain', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. Після кількох ігрових днів небо лишається ясним, а ферму треба поливати вручну. Який біом найімовірніше під ногами? За цією ситуацією визнач правильну місцевість або споруду.', 'Відкрита трав’яниста місцевість', 'Водний коридор між берегами', 'Ліс із дощем і дубами', 'Сухий біом із кактусами й піском', 3, 'Пустелі залишаються сухими, тому звичайного дощу там не буває. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 5, true),
  ('jungle-has-vines', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. У записнику гравця є така польова підказка: Де гравець знайде високі дерева та багато ліан? За цією ситуацією визнач правильну місцевість або споруду.', 'Пустеля', 'Замерзлий океан', 'Джунглі', 'Грибні поля', 2, 'Джунглі відомі високими деревами, густим листям і великою кількістю ліан. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 6, false),
  ('mushroom-fields-has-giant-mushrooms', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. У записнику гравця є така польова підказка: Який біом відомий гігантськими грибами замість звичайних дерев? За цією ситуацією визнач правильну місцевість або споруду.', 'Засніжені рівнини', 'Грибні поля', 'Савана', 'Бамбукові джунглі', 1, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 7, false),
  ('ocean-mostly-water', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. Якщо біом здебільшого складається з відкритих водойм, яким біомом він, імовірно, буде? За цією ситуацією визнач правильну місцевість або споруду.', 'Савана', 'Океан', 'Тайга', 'Безплідні землі', 1, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 8, false),
  ('plains-open-grassland', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. У записнику гравця є така польова підказка: Який біом варто шукати гравцеві, який хоче широкі відкриті луки? За цією ситуацією визнач правильну місцевість або споруду.', 'Темні глибини', 'Базальтові дельти', 'Вишневий гай', 'Рівнини', 3, 'Рівнини відкриті й порослі травою, тому там зручно будувати й пересуватися. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 9, false),
  ('river-cuts-through-land', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. У записнику гравця є така польова підказка: Який біом часто виглядає як звивиста смуга води, що прорізає суходіл? За цією ситуацією визнач правильну місцевість або споруду.', 'Річка', 'Гай', 'Пустеля', 'Грибні поля', 0, 'Річки тягнуться довгими водними руслами крізь інші ділянки звичайного світу. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 10, false),
  ('savanna-has-acacia-trees', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. У записнику гравця є така польова підказка: Де гравець найчастіше очікує знайти дерева акації? За цією ситуацією визнач правильну місцевість або споруду.', 'Савана', 'Темний ліс', 'Замерзла річка', 'Грибні поля', 0, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 11, false),
  ('snowy-plains-has-snow', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. У записнику гравця є така польова підказка: Який біом зазвичай покритий снігом? За цією ситуацією визнач правильну місцевість або споруду.', 'Засніжені рівнини', 'Мангрове болото', 'Джунглі', 'Пустеля', 0, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 12, false),
  ('swamp-has-lily-pads', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. У записнику гравця є така польова підказка: Який біом славиться мілководдям і багатьма лататтями? За цією ситуацією визнач правильну місцевість або споруду.', 'Безплідні землі', 'Болото', 'Савана', 'Засніжені рівнини', 1, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 13, false),
  ('taiga-has-spruce', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. Які дерева особливо поширені в тайговому біомі? За цією ситуацією визнач правильну місцевість або споруду.', 'Акація', 'Мангровий ліс', 'Ялина', 'Вишня', 2, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 14, false),
  ('village-has-villagers', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. Ти бачиш робочі блоки, грядки, дзвін і мешканців, які вдень ходять між будівлями. Що це за структура? За цією ситуацією визнач правильну місцевість або споруду.', 'Затонулий корабель із скринями', 'Поселення з робочими місцями', 'Пошкоджена рамка порталу', 'Підземні дерев’яні тунелі', 1, 'Села корисно знаходити на початку, бо там часто є укриття, їжа й торгівля. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 15, true),
  ('cobblestone-from-stone', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. Коли камінь видобувають кайлом, який блок зазвичай випадає? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Цегла', 'Гравій', 'Глина', 'Кругляк', 3, 'Зі звичайного каменю зазвичай випадає кругляк, якщо не діють особливі умови на кшталт Шовкового дотику. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 16, false),
  ('glass-is-see-through', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. Треба закрити отвір у стіні так, щоб крізь нього бачити мобів надворі й не лишати прохід відкритим. Який матеріал підходить? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Непрозорий кам’яний блок', 'Кольоровий глиняний блок', 'Прозорий переплавлений матеріал', 'Кольоровий м’який блок', 2, 'Скло пропускає світло й дозволяє бачити назовні, водночас закриваючи базу. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 17, true),
  ('obsidian-from-water-and-lava', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. Вода потекла прямо на джерело лави, і замість рідини з’явився дуже міцний темний блок. Що утворилося? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'М’який річковий матеріал', 'Темний блок для порталів', 'Темний незерський камінь', 'Обпалений будівельний блок', 1, 'Джерело лави стає обсидіаном, коли на нього потрапляє вода. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 18, true),
  ('planks-build-starter-house', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. У записнику гравця є така польова підказка: Який блок багато гравців виготовляють із колод для початкового будинку? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Дерев''яні дошки', 'Вовняний килим', 'Шибка', 'Редстоуновий пил', 0, 'Дошки — один із перших будівельних матеріалів, які гравці роблять із колод. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 19, false),
  ('sand-falls-with-gravity', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. Під блоком прибрали опору, і він не завис у повітрі, а впав униз як сутність. Який це блок? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Дерев’яний будівельний блок', 'Декоративний блок із книжками', 'Оброблений кам’яний блок', 'Сипкий пляжний блок', 3, 'Пісок є гравітаційним блоком, тому падає, коли зникає блок під ним. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 20, true),
  ('coal-fuels-furnace', 'Який предмет найчастіше використовують як паливо для печі?', 'Пісок', 'Вугілля', 'Кругляк', 'Нитка', 1, 'Одне вугілля горить так довго, що встигає переплавити 8 предметів.', 21, true),
  ('crafting-table-basics', 'Який блок дає сітку 3×3 для створення інструментів і предметів?', 'Скриня', 'Верстак', 'Піч', 'Ліжко', 1, 'В інвентарі є лише сітка 2×2, тож більші рецепти, як-от інструменти, потребують верстака.', 22, true),
  ('furnace-smelts-raw-iron', 'Який блок перетворює необроблене залізо на злитки, якщо додати паливо?', 'Діжка', 'Піч', 'Компостер', 'Ковадло', 1, 'Піч спалює паливо й переплавляє руду, тож з необробленого заліза виходять злитки.', 23, true),
  ('planks-from-logs', 'Скільки залізних злитків потрібно, щоб скрафтити блок заліза?', '6', '9', '4', '8', 1, 'Дев''ять злитків заповнюють усю сітку 3×3, а блок можна знову розібрати на дев''ять злитків.', 24, true),
  ('sticks-from-planks', 'Який предмет із дощок служить держаком у більшості рецептів інструментів?', 'Драбина', 'Кнопка', 'Миска', 'Палиця', 3, 'Дві дошки одна над одною дають чотири палиці, а їх потребують інструменти й смолоскипи.', 25, true),
  ('pickaxe-mines-stone', 'Який інструмент потрібен, щоб із видобутого каменю щось випало?', 'Сокира', 'Лопата', 'Кайло', 'Мотика', 2, 'Камінь, добутий рукою чи іншим інструментом, нічого не дає, тож потрібне кайло.', 26, true),
  ('carrots-breed-pigs', 'Яким кормом можна розводити свиней?', 'Пшениця', 'Морква', 'Ламінарія', 'Червоний гриб', 1, 'Свині люблять коренеплоди: морква, картопля й буряк змушують їх розмножуватися, а пшениця ні.', 27, true),
  ('chickens-lay-eggs', 'Що курка сама залишає кожні кілька хвилин?', 'Перо', 'Яйце', 'Шкіра', 'Насіння пшениці', 1, 'Кури несуть яйце раз на 5–10 хвилин, а пір''я випадає лише тоді, коли курку вбивають.', 28, true),
  ('cow-drops-leather', 'Яка тварина може скинути шкіру?', 'Корова', 'Свиня', 'Вівця', 'Курка', 0, 'Корови дають шкіру й сиру яловичину, тож ферма корів дає і їжу, і шкіру для книжок та броні.', 29, true),
  ('sheep-give-wool', 'Яку тварину можна обстригти, щоб отримати вовну?', 'Коза', 'Корова', 'Свиня', 'Вівця', 3, 'Обстрижена вівця знову обростає вовною, коли поїсть траву, тож дає вовну знову й знову.', 30, true),
  ('wheat-grows-from-seeds', 'З трави може випасти насіння. Яка культура з нього виросте?', 'Морква', 'Кактус', 'Цукрова тростина', 'Пшениця', 3, 'З трави випадає насіння пшениці, тому пшениця зазвичай перша культура, яку садить новий гравець.', 31, true),
  ('bone-meal-speeds-growth', 'Який предмет прискорює ріст посівів, якщо використати його на них?', 'Папір', 'Кісткове борошно', 'Порох', 'Цукор', 1, 'Кісткове борошно одразу просуває посів на одну чи кілька стадій росту, тож не треба чекати.', 32, true),
  ('bucket-collects-cow-milk', 'Що треба використати на корові, щоб набрати молока?', 'Скляна пляшка', 'Миска', 'Відро', 'Ножиці', 2, 'Молоко — рідина, як вода, тому його носять у відрі; відро молока ще й знімає ефекти зілля.', 33, true),
  ('hoe-makes-farmland', 'Який інструмент перетворює ґрунт на ріллю?', 'Кайло', 'Мотика', 'Ножиці', 'Лопата', 1, 'Насіння можна садити лише на ріллю, тож обробка ґрунту мотикою — перший крок будь-якої ферми.', 34, true),
  ('creeper-explodes', 'Який ворожий моб шипить перед тим, як вибухнути?', 'Кріпер', 'Зомбі', 'Скелет', 'Павук', 0, 'Кріпер тихо підкрадається, шипить і вибухає, руйнуючи блоки й ранячи гравця.', 35, true),
  ('large-slime-splits', 'Який зелений стрибучий моб після перемоги розпадається на менші копії?', 'Слимак', 'Відьма', 'Кріпер', 'Ендермен', 0, 'Великий слимак розпадається на кілька менших, а середні діляться ще раз.', 36, true),
  ('skeleton-uses-bow', 'Який поширений ворожий моб стріляє в тебе з лука?', 'Кріпер', 'Скелет', 'Зомбі', 'Слимак', 1, 'Скелети атакують здалеку, тому щит або укриття дуже допомагають.', 37, true),
  ('spider-climbs-walls', 'Який ворожий моб уміє лазити прямовисними стінами?', 'Павук', 'Ендермен', 'Кріпер', 'Зомбі', 0, 'Павуки лазять вертикальними поверхнями, тож звичайна стіна їх не зупинить.', 38, true),
  ('zombies-burn-in-day', 'Хто з цих мобів загоряється під прямим сонцем?', 'Павук', 'Зомбі', 'Кріпер', 'Відьма', 1, 'Зомбі горять удень, якщо не стоять у тіні чи воді або не мають шолома.', 39, true),
  ('button-short-redstone-pulse', 'У Незері, Краї та редстоуні помилка швидко коштує ресурсів, тому треба знати базову взаємодію наперед. У записнику гравця є така польова підказка: Який маленький вхідний блок при натисканні зазвичай подає лише короткий редстоун-імпульс? За цією ситуацією обери компонент, ресурс або правило прогресії, яке спрацює.', 'Книжкова шафа', 'Піч', 'Кнопка', 'Скриня', 2, 'Кнопка подає короткий редстоун-сигнал лише на мить після натискання. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 40, false),
  ('flint-and-steel-lights-portal', 'У Незері, Краї та редстоуні помилка швидко коштує ресурсів, тому треба знати базову взаємодію наперед. У записнику гравця є така польова підказка: Який інструмент найчастіше використовують, щоб запалити портал у Незер? За цією ситуацією обери компонент, ресурс або правило прогресії, яке спрацює.', 'Кресало', 'Ножиці', 'Компас', 'Підзорна труба', 0, 'Кресалом найчастіше запалюють рамку порталу в Незер. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 41, false),
  ('nether-portal-needs-obsidian', 'У Незері, Краї та редстоуні помилка швидко коштує ресурсів, тому треба знати базову взаємодію наперед. Для рамки між світами потрібен блок, який витримує вибухи й добувається дуже повільно без діамантового або кращого кайла. Що ставлять? За цією ситуацією обери компонент, ресурс або правило прогресії, яке спрацює.', 'Звичайний кам’яний блок', 'Світлий блок із піску', 'Темний вулканічний блок', 'Окиснюваний металевий блок', 2, 'Більшість порталів у Незер будують з обсидіану, бо він тримає рамку порталу. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 42, true),
  ('redstone-dust-carries-power', 'У Незері, Краї та редстоуні помилка швидко коштує ресурсів, тому треба знати базову взаємодію наперед. Між важелем і дверима треба прокласти лінію, що передасть сигнал по підлозі. Який предмет розсипають? За цією ситуацією обери компонент, ресурс або правило прогресії, яке спрацює.', 'Вибуховий порошок', 'Солодкий крафтовий інгредієнт', 'Провідник сигналу з руди', 'Світний порошок із Незеру', 2, 'Редстоуновий пил зʼєднує перемикачі та механізми, щоб схема працювала. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 43, true),
  ('soul-sand-slows-movement', 'У Незері, Краї та редстоуні помилка швидко коштує ресурсів, тому треба знати базову взаємодію наперед. У записнику гравця є така польова підказка: Який блок сповільнює рух, коли гравець проходить через нього? За цією ситуацією обери компонент, ресурс або правило прогресії, яке спрацює.', 'Гладкий камінь', 'Сухий лід', 'Вугільна руда', 'Пісок душ', 3, 'Пісок душ сповільнює рух і має особливі взаємодії з бульбашковими колонами. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 44, false),
  ('bed-sets-respawn', 'Який предмет дає змогу спати й задати точку відродження?', 'Човен', 'Скриня', 'Ліжко', 'Прапор', 2, 'Сон у ліжку пропускає ніч і ставить точку відродження поруч із ним.', 45, true),
  ('cooked-food-better-hunger', 'Яка з цих страв найкраще втамовує голод?', 'Скибка кавуна', 'Смажена свинина', 'Сира свинина', 'Яблуко', 1, 'Смажена свинина відновлює 8 одиниць голоду, набагато більше за сире м''ясо, яблуко чи кавун.', 46, true),
  ('eating-refills-hunger', 'Яка шкала заповнюється, коли ти їси?', 'Шкала повітря', 'Шкала броні', 'Шкала досвіду', 'Шкала голоду', 3, 'Їжа заповнює шкалу голоду, а повна шкала дає змогу бігати й відновлювати здоров''я.', 47, true),
  ('shelter-before-first-night', 'Що варто збудувати до першої ночі, щоб вижити?', 'Портал Незеру', 'Укриття', 'Маяк', 'Стіл зачарування', 1, 'Ворожі моби з''являються в темряві, тож просте закрите укриття береже тебе першої ночі.', 48, true),
  ('torch-lights-caves', 'Що гравці ставлять, щоб освітити темні печери?', 'Двері', 'Табличка', 'Смолоскип', 'Скриня', 2, 'Смолоскипи дають світло, тож у печері видно більше, а монстрів поруч з''являється менше.', 49, true),
  ('armorer-uses-blast-furnace', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. У записнику гравця є така польова підказка: Який робочий блок використовує селянин-броняр? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Плавильна піч', 'Картографічний стіл', 'Кафедра', 'Варильна стійка', 0, 'Бронярі використовують плавильні печі як свій робочий блок. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 50, false),
  ('barrel-makes-fisherman', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. У записнику гравця є така польова підказка: Яка робоча станція перетворює селянина на рибалку? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Ковадло', 'Каменеріз', 'Компостер', 'Бочка', 3, 'Бочка є робочим блоком рибалки. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 51, false),
  ('bookshelves-boost-enchanting', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. У записнику гравця є така польова підказка: Який сусідній блок допомагає столу зачарувань пропонувати сильніші чари? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Бочка', 'Книжкова шафа', 'Ліхтар', 'Мішень', 1, 'Книжкові шафи навколо столу зачарувань підсилюють доступні варіанти чарів. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 52, false),
  ('cartographer-uses-cartography-table', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. У записнику гравця є така польова підказка: На якому робочому блоці працюють картографи? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Стіл лучника', 'Плавильна піч', 'Компостер', 'Картографічний стіл', 3, 'Картографи працюють із картографічним столом. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 53, false),
  ('cauldron-makes-leatherworker', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. У записнику гравця є така польова підказка: Який блок допомагає селянину стати шкіряником? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Ткацький верстат', 'Коптильня', 'Казан', 'Бочка', 2, 'Казан найкраще відповідає описаній механіці села або зачарувань. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 54, false),
  ('composter-makes-farmer', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. У записнику гравця є така польова підказка: Який блок робочого місця дає селянину професію фермера? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Ткацький верстат', 'Ковадло', 'Коптильня', 'Компостер', 3, 'Компостер є блоком робочого місця, пов’язаним із професією фермера. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 55, false),
  ('emeralds-for-trading', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. У записнику гравця є така польова підказка: Який камінь є звичайною валютою в торгівлі селянинами? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Діамант', 'Аметистовий уламок', 'Кварц', 'Смарагд', 3, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 56, false),
  ('fletcher-uses-fletching-table', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. Селянин із яким робочим блоком стає лучником? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Бочка', 'Коптильня', 'Точило', 'Стіл лучника', 3, 'Стіл лучника є блоком робочого місця селянина-лучника. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 57, false),
  ('lapis-for-enchanting', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. На столі зачарувань досвід є, предмет є, але інтерфейс просить синій ресурс як плату за зачарування. Що потрібно? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Слизький крижаний блок', 'Коштовний матеріал для спорядження', 'Матеріал океанських споруд', 'Синій мінерал для зачарувань', 3, 'Стіл зачарувань використовує лазурит і рівні досвіду для накладання чар. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 58, true),
  ('librarian-sells-books', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. Ти шукаєш зачаровані книги через торгівлю й перевіряєш професію селянина біля кафедри. До кого йти? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Селянин книжкової професії', 'Селянин із рибальськими товарами', 'Селянин із м’ясом', 'Селянин із їжею та врожаєм', 0, 'Бібліотекарі є чудовими торговцями, коли потрібні корисні зачарування. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 59, true),
  ('loom-makes-shepherd', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. Коли селянин береться за ткацький верстат, яка професія з’являється? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Каменяр', 'Мʼясник', 'Вівчар', 'Священник', 2, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 60, false),
  ('nitwit-has-no-profession', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. У записнику гравця є така польова підказка: Який селянин не бере нормальної професії? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Лучник', 'Священник', 'Фермер', 'Нездара', 3, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 61, false),
  ('smoker-makes-butcher', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. У якому районі села створюється професія м’ясника? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Ткацький верстат', 'Коптильня', 'Дзвін', 'Ковальський стіл', 1, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 62, false),
  ('stonecutter-makes-mason', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. У записнику гравця є така польова підказка: Який робочий блок треба поставити, щоб безробітний селянин став майстром каменю? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Каменяр', 'Рибалка', 'Інструментальник', 'Вівчар', 0, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 63, false),
  ('villagers-sleep-in-beds', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. У записнику гравця є така польова підказка: Чим зазвичай користуються селяни вночі, коли село нормально працює? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Ліжка', 'Доменні печі', 'Вогнища', 'Вагонетки', 0, 'Ліжка найкраще відповідає описаній механіці села або зачарувань. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 64, false),
  ('hearts-show-player-health', 'Які значки на екрані показують твоє здоров''я?', 'Значки броні', 'Бульбашки', 'Сердечка', 'Курячі ніжки', 2, 'Кожне повне сердечко дорівнює 2 одиницям здоров''я, а втрата всіх означає смерть.', 65, true),
  ('armor-cuts-incoming-damage', 'Яке спорядження зменшує шкоду від ударів мобів?', 'Сідло', 'Ножиці', 'Компас', 'Обладунки', 3, 'Кожна частина обладунків додає захист, і що його більше, то менша шкода від ударів.', 66, true),
  ('night-more-hostile-spawns', 'Який предмет показує, день зараз чи ніч, навіть глибоко під землею?', 'Годинник', 'Компас', 'Компас відновлення', 'Підзорна труба', 0, 'Циферблат годинника показує сонце й місяць, тож ти знаєш, коли безпечно виходити з укриття.', 67, true),
  ('door-closes-base-entrance', 'Який блок біля входу в укриття не пускає мобів, але пропускає тебе?', 'Квітковий горщик', 'Двері', 'Картина', 'Килим', 1, 'Двері ти відчиняєш і зачиняєш сам, а більшість мобів крізь них не пройде.', 68, true),
  ('wool-used-for-bed', 'Який блок — це вирізаний гарбуз зі смолоскипом усередині?', 'Морський ліхтар', 'Ліхтар Джека', 'Світлокамінь', 'Ліхтар', 1, 'Ліхтар Джека світить, як смолоскип, тож освітлює укриття й навіть світить під водою.', 69, true),
  ('ladder-climbs-vertical-wall', 'Яка рослина ранить тебе, коли ти до неї торкаєшся?', 'Мертвий кущ', 'Бамбук', 'Цукрова тростина', 'Кактус', 3, 'Кактус ранить усіх, хто його торкнеться, тож тримай його подалі від стежок і загонів.', 70, true),
  ('boat-travels-over-water', 'Який предмет дає змогу швидко перетнути річку чи океан?', 'Повідець', 'Вагонетка', 'Човен', 'Сідло', 2, 'Човен тримається на воді й рухається набагато швидше, ніж ти пливеш.', 71, true),
  ('torch-brightens-dark-spaces', 'Що, крім палиці, потрібно для крафту смолоскипа?', 'Кремінь', 'Порох', 'Кістка', 'Вугілля', 3, 'Смолоскип крафтять із вугілля чи деревного вугілля над палицею.', 72, true),
  ('sneaking-prevents-edge-fall', 'Яка дія не дає тобі зійти з краю блоку?', 'Плавання', 'Підкрадання', 'Планерування', 'Біг', 1, 'Коли підкрадаєшся, ти зупиняєшся на краю блоку, тож будувати високо безпечніше.', 73, true),
  ('bucket-picks-up-water-source', 'Який предмет дає змогу набрати блок-джерело води?', 'Відро', 'Миска', 'Казан', 'Квітковий горщик', 0, 'Порожнє відро набирає джерело води чи лави, щоб поставити його деінде.', 74, true),
  ('chest-stores-home-items', 'Який блок зазвичай крафтять, щоб зберігати вдома багато речей?', 'Ліхтар', 'Скриня', 'Ліжко', 'Піч', 1, 'Скриня вміщує 27 стаків, а дві поруч стають великою подвійною скринею.', 75, true),
  ('bed-crafted-from-wool-and-planks', 'Який предмет крафтять із трьох блоків вовни й трьох дощок?', 'Човен', 'Ліжко', 'Щит', 'Драбина', 1, 'Сон у ліжку пропускає ніч і встановлює точку відродження.', 76, true),
  ('furnace-crafted-from-cobblestone', 'Який блок крафтять із восьми кругляків, викладених кільцем?', 'Піч', 'Ковадло', 'Роздавач', 'Діжка', 0, 'Вісім кругляків навколо порожнього центру дають піч для руди та їжі.', 77, true),
  ('four-planks-make-crafting-table', 'Який блок виходить із чотирьох дощок у сітці 2×2 в інвентарі?', 'Діжка', 'Верстак', 'Книжкова полиця', 'Скриня', 1, 'Чотири дошки квадратом дають верстак — перший крок до більших рецептів.', 78, true),
  ('planks-work-as-furnace-fuel', 'Немає вугілля? Що з цього теж можна спалити в печі?', 'Дошки', 'Камінь', 'Скло', 'Гравій', 0, 'Дерев''яні речі горять у печі, і одна дошка переплавляє півтора предмета.', 79, true),
  ('pickaxe-breaks-stone-faster', 'Який інструмент найшвидше рубає колоди?', 'Ножиці', 'Сокира', 'Лопата', 'Кайло', 1, 'Сокира створена для дерева, тож колоди й дошки ламаються нею набагато швидше.', 80, true),
  ('stone-drops-cobblestone', 'Скільки діамантів потрібно, щоб скрафтити діамантове кайло?', '3', '2', '5', '4', 0, 'Кайло потребує трьох одиниць матеріалу зверху й двох палиць під ними.', 81, true),
  ('iron-ingots-craft-bucket', 'Який злиток потрібен, щоб скрафтити відро?', 'Залізний злиток', 'Незеритовий злиток', 'Золотий злиток', 'Мідний злиток', 0, 'Три залізні злитки у формі літери V дають відро для води, лави чи молока.', 82, true),
  ('stone-next-tier-after-wood', 'Який матеріал для інструментів іде одразу після дерева?', 'Діамант', 'Незерит', 'Залізо', 'Камінь', 3, 'Кам''яні інструменти потребують лише кругляка й палиць, а служать довше за дерев''яні.', 83, true),
  ('logs-turn-into-planks', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. У записнику гравця є така польова підказка: Який блок, зрізаний із дерева, зазвичай спершу перетворюють на дошки? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Вовна', 'Колода', 'Пісок', 'Гравій', 1, 'Колода — це той блок, який зазвичай спершу перетворюють на дошки. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 84, false),
  ('dirt-under-many-grass-blocks', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. У записнику гравця є така польова підказка: Який звичайний природний блок знаходиться під багатьма трав’яними блоками? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Скло', 'Мідь', 'Ґрунт', 'Вовна', 2, 'Поведінка блока в світі збігається з описаною будівельною ситуацією. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 85, false),
  ('clay-can-be-smelted-into-bricks', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. Зі ставків і річок який м’який блок можна переплавити на цеглу? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Гравій', 'Лід', 'Вугільна руда', 'Глина', 3, 'Глина — саме той блок чи предмет, що підходить до описаної властивости або будівельної ситуації. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 86, false),
  ('door-swings-open-for-houses', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. Для входу в будинок, який блок відкривається та закривається, як прості ворота? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Плита', 'Двері', 'Смолоскип', 'Килим', 1, 'Двері — саме той блок чи предмет, що підходить до описаної властивости або будівельної ситуації. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 87, false),
  ('fence-gate-opens-between-fences', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. Через який блок між двома огорожами можуть пройти гравці та тварини? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Ліхтар', 'Ворота паркану', 'Драбина', 'Шибка', 1, 'Ворота паркану — саме той блок чи предмет, що підходить до описаної властивости або будівельної ситуації. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 88, false),
  ('stairs-help-players-climb-builds', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. У записнику гравця є така польова підказка: Який фасонний блок найчастіше використовують, щоб простіше ходити по будівлі? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Килим', 'Сходи', 'Натискна плита', 'Вовна', 1, 'Сходи найкраще пасує до описаної поведінки блока або будівельного використання. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 89, false),
  ('glass-pane-makes-thin-window', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. У записнику гравця є така польова підказка: Що можуть розмістити гравці для більш тонкого вікна, ніж повні скляні блоки? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Шибка', 'Ліжко', 'Піч', 'Скриня', 0, 'Поведінка блока в світі збігається з описаною будівельною ситуацією. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 90, false),
  ('gravel-falls-like-sand', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. Як пісок, який пухкий блок падає вниз, якщо його ніщо не підтримує? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Скло', 'Кругляк', 'Гравій', 'Дубові дошки', 2, 'Гравій — саме той блок чи предмет, що підходить до описаної властивости або будівельної ситуації. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 91, false),
  ('flowing-lava-and-water-make-cobblestone', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. У записнику гравця є така польова підказка: Який блок зазвичай утворюється, коли текуча лава стикається з водою? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Кругляк', 'Глина', 'Обсидіан', 'Пісковик', 0, 'Кругляк найкраще пасує до описаної поведінки блока або будівельного використання. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 92, false),
  ('ice-can-melt-into-water', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. У записнику гравця є така польова підказка: Який замерзлий блок може розплавитися у воду під час сильного світла чи тепла? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Камінь', 'Лід', 'Скло', 'Вовна', 1, 'Поведінка блока в світі збігається з описаною будівельною ситуацією. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 93, false),
  ('wheat-breeds-cows-and-sheep', 'Якою культурою можна розводити корів і овець?', 'Морква', 'Картопля', 'Буряк', 'Пшениця', 3, 'Корови, вівці й кози їдять пшеницю, тож одне поле пшениці прогодує більшість тварин на фермі.', 94, true),
  ('carrot-plants-more-carrots', 'Яку культуру садять самим урожаєм, без окремого насіння?', 'Морква', 'Пшениця', 'Гарбуз', 'Буряк', 0, 'У моркви, як і в картоплі, немає насіння: садиш моркву й збираєш кілька нових.', 95, true),
  ('melon-block-grows-from-melon-stem', 'Який блок урожаю при руйнуванні дає скибки?', 'Гарбуз', 'Кактус', 'Кавун', 'Копиця соломи', 2, 'Блок кавуна розпадається на 3–7 скибок, а гарбуз випадає цілим блоком.', 96, true),
  ('three-wheat-craft-bread', 'На що перетворюється сира яловичина, якщо засмажити її в печі?', 'Смажена курятина', 'Стейк', 'Смажена свинина', 'Смажена баранина', 1, 'Засмажена яловичина називається стейком і вгамовує голод так само, як смажена свинина.', 97, true),
  ('bowl-carries-mushroom-stew', 'Що, крім червоного й коричневого грибів, потрібно для тушкованих грибів?', 'Відро', 'Палиця', 'Миска', 'Скляна пляшка', 2, 'Страву подають у мисці, і після їжі порожня миска повертається до тебе.', 98, true),
  ('hay-bale-stores-extra-wheat', 'Який блок крафтять із дев''яти пшениць?', 'Моховий блок', 'Блок висушеної ламінарії', 'Копиця соломи', 'Біла вовна', 2, 'Копиця соломи вміщує дев''ять пшениць в одному блоці, економить місце й годує коней і лам.', 99, true),
  ('pandas-breed-with-bamboo', 'Якою рослиною годують панд, щоб вони розмножилися?', 'Бамбук', 'Цукрова тростина', 'Пшениця', 'Ламінарія', 0, 'Панди живуть у бамбукових джунглях і їдять бамбук, тож саме він змушує їх розмножуватися.', 100, true),
  ('cow-makes-moo-sound', 'Яка морська істота дає чорнильні мішки?', 'Тріска', 'Кальмар', 'Дельфін', 'Черепаха', 1, 'Кальмари дають чорнильні мішки, з яких роблять чорний барвник і книгу й перо.', 101, true),
  ('sheep-can-be-sheared', 'Який маленький літаючий моб спить догори ногами в темних печерах?', 'Папуга', 'Кажан', 'Збирик', 'Бджола', 1, 'Кажани висять догори ногами під стелею печер і пурхають, коли поруч з''являється гравець.', 102, true),
  ('bee-produces-honey', 'Який маленький моб наповнює гнізда й вулики медом?', 'Кажан', 'Бджола', 'Папуга', 'Курка', 1, 'Бджоли збирають пилок із квітів і несуть додому, поступово наповнюючи гніздо медом.', 103, true),
  ('wolf-can-be-tamed-as-pet', 'На якій прирученій тварині можна їздити, якщо вдягти сідло?', 'Папуга', 'Вовк', 'Кінь', 'Кіт', 2, 'Приручений кінь у сідлі везе тебе й слухається керування, і це швидше, ніж пішки.', 104, true),
  ('pig-likes-carrots', 'Яку тварину можна приручити, згодувавши їй насіння?', 'Кіт', 'Курка', 'Вовк', 'Папуга', 3, 'Насіння приручає папугу, і після цього вона може сидіти в тебе на плечі.', 105, true),
  ('shield-blocks-many-hits', 'Що, крім палиць, потрібно для крафту лука?', 'Шкіра', 'Перо', 'Нитка', 'Вовна', 2, 'Три палиці й три нитки дають лук, а нитки найпростіше добути з павуків.', 106, true),
  ('sword-is-basic-melee-weapon', 'Який предмет із верстака створений саме для ближнього бою?', 'Меч', 'Мотика', 'Лопата', 'Відро', 0, 'Меч — основна зброя ближнього бою, він б’є сильніше за мотику чи лопату.', 107, true),
  ('bow-fires-arrows', 'Яку зброю натягують, щоб стріляти стрілами по далеких мобах?', 'Тризубець', 'Лук', 'Меч', 'Сокира', 1, 'Лук дає змогу атакувати з безпечної відстані: що довше натягуєш, то сильніший постріл.', 108, true),
  ('armor-reduces-attack-damage', 'Який повний комплект обладунків захищає найслабше?', 'Діамантові обладунки', 'Шкіряні обладунки', 'Незеритові обладунки', 'Залізні обладунки', 1, 'Шкіра — найслабші обладунки, а діамант і незерит захищають найкраще.', 109, true),
  ('torches-help-stop-spawns', 'Який меч завдає найбільше шкоди?', 'Діамантовий меч', 'Кам''яний меч', 'Незеритовий меч', 'Залізний меч', 2, 'Незерит — найміцніший матеріал, тож незеритовий меч б''є сильніше за діамантовий і служить довше.', 110, true),
  ('ender-pearl-drops-from-enderman', 'У Незері, Краї та редстоуні помилка швидко коштує ресурсів, тому треба знати базову взаємодію наперед. Перемога над ендерменом може викинути предмет, використаний пізніше для завершення прогресу? За цією ситуацією обери компонент, ресурс або правило прогресії, яке спрацює.', 'Призмариновий уламок', 'Перлина Ендера', 'Зірка Незеру', 'Стрижень іфрита', 1, 'Перлина Ендера найкраще відповідає описаній механіці редстоуну або вимірів. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 111, false),
  ('end-portal-opens-path-to-end', 'У Незері, Краї та редстоуні помилка швидко коштує ресурсів, тому треба знати базову взаємодію наперед. У записнику гравця є така польова підказка: Який портал переносить гравців у вимір дракона, коли його активовано? За цією ситуацією обери компонент, ресурс або правило прогресії, яке спрацює.', 'Портал Незеру', 'Зруйнований портал', 'Портал Енду', 'Лавовий басейн', 2, 'Саме портал Енду веде до виміру, де гравця чекає дракон Енду. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 112, false),
  ('ender-dragon-is-end-boss', 'У Незері, Краї та редстоуні помилка швидко коштує ресурсів, тому треба знати базову взаємодію наперед. У записнику гравця є така польова підказка: Який бос чекає на гравця на головному острові Енду? За цією ситуацією обери компонент, ресурс або правило прогресії, яке спрацює.', 'Ґаст', 'Боронитель', 'Дракон Енду', 'Візер', 2, 'У прогресії між вимірами або редстоун-механіці ця умова є вирішальною. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 113, false),
  ('stronghold-contains-end-portal', 'У Незері, Краї та редстоуні помилка швидко коштує ресурсів, тому треба знати базову взаємодію наперед. У записнику гравця є така польова підказка: Яка підземна споруда зазвичай містить кімнату з порталом Енду? За цією ситуацією обери компонент, ресурс або правило прогресії, яке спрацює.', 'Село', 'Фортеця', 'Стародавнє місто', 'Покинута шахта', 1, 'Портал Енду зазвичай знаходять у спеціальній кімнаті фортеці. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 114, false),
  ('end-stone-covers-end-islands', 'У Незері, Краї та редстоуні помилка швидко коштує ресурсів, тому треба знати базову взаємодію наперед. У записнику гравця є така польова підказка: Який блідий блок утворює основу багатьох островів на більшій частині Краю? За цією ситуацією обери компонент, ресурс або правило прогресії, яке спрацює.', 'Пісковик', 'Пісок душ', 'Камінь Енду', 'Обсидіан', 2, 'У прогресії між вимірами або редстоун-механіці ця умова є вирішальною. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 115, false),
  ('redstone-torch-provides-power', 'У Незері, Краї та редстоуні помилка швидко коштує ресурсів, тому треба знати базову взаємодію наперед. У записнику гравця є така польова підказка: Який блок, що світиться червоним на стіні або підлозі, працює як просте постійне джерело живлення? За цією ситуацією обери компонент, ресурс або правило прогресії, яке спрацює.', 'Багаття', 'Редстоуновий смолоскип', 'Ліхтар', 'Смолоскип душ', 1, 'Редстоуновий смолоскип постійно подає сигнал і є одним із базових компонентів редстоуну. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 116, false),
  ('pressure-plate-triggers-on-step', 'У Незері, Краї та редстоуні помилка швидко коштує ресурсів, тому треба знати базову взаємодію наперед. У записнику гравця є така польова підказка: Який плаский блок може активувати схему, коли на нього наступає гравець або моб? За цією ситуацією обери компонент, ресурс або правило прогресії, яке спрацює.', 'Шибка', 'Прапор', 'Квітковий горщик', 'Натискна плита', 3, 'Натискна плита активується, коли на неї стають, і подає редстоун-сигнал. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 117, false),
  ('piston-pushes-block-forward', 'У Незері, Краї та редстоуні помилка швидко коштує ресурсів, тому треба знати базову взаємодію наперед. У записнику гравця є така польова підказка: Який редстоун-блок може штовхнути інший блок уперед? За цією ситуацією обери компонент, ресурс або правило прогресії, яке спрацює.', 'Кафедра', 'Поршень', 'Повторювач', 'Спостерігач', 1, 'Поршень є класичним редстоун-блоком для штовхання інших блоків. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 118, false),
  ('strider-walks-on-lava', 'У Незері, Краї та редстоуні помилка швидко коштує ресурсів, тому треба знати базову взаємодію наперед. У записнику гравця є така польова підказка: Який верховий моб може ходити по поверхні лави в Незері? За цією ситуацією обери компонент, ресурс або правило прогресії, яке спрацює.', 'Кінь', 'Блукач', 'Піґлін', 'Іфрит', 1, 'Блукач може ходити по лаві, і гравець може осідлати його. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 119, false),
  ('warped-fungus-stick-steers-strider', 'У Незері, Краї та редстоуні помилка швидко коштує ресурсів, тому треба знати базову взаємодію наперед. У записнику гравця є така польова підказка: Який спеціальний предмет на палиці використовується для керування мандрівником? За цією ситуацією обери компонент, ресурс або правило прогресії, яке спрацює.', 'Морква на паличці', 'Повідець', 'Вудка', 'Химерний гриб на паличці', 3, 'У прогресії між вимірами або редстоун-механіці ця умова є вирішальною. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 120, false)
) as v(content_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, sort_order, is_active)
where pack.slug = 'minecraft-uk-easy'
on conflict (pack_id, content_id) do update set
  prompt = excluded.prompt,
  option_a = excluded.option_a,
  option_b = excluded.option_b,
  option_c = excluded.option_c,
  option_d = excluded.option_d,
  correct_option = excluded.correct_option,
  explanation = excluded.explanation,
  sort_order = excluded.sort_order,
  is_active = excluded.is_active;

insert into public.question_packs (category_id, locale, age_band, difficulty, title, slug, is_active)
select id, 'uk', '8-12', 'medium', 'MineMind uk medium', 'minecraft-uk-medium', true
from public.quiz_categories
where slug = 'minecraft'
on conflict (slug) do update set is_active = true, title = excluded.title;

insert into public.questions (pack_id, content_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, sort_order, is_active)
select pack.id, v.content_id, v.prompt, v.option_a, v.option_b, v.option_c, v.option_d, v.correct_option, v.explanation, v.sort_order, v.is_active
from public.question_packs pack
cross join (values
  ('amethyst-geode-underground', 'Плануючи маршрут за ресурсами, ти порівнюєш рельєф, рослини й структури, щоб не витратити день марно. Де зазвичай знаходять аметистові жеоди? На основі цього визнач правильну місцевість або споруду.', 'Під землею', 'Всередині болотяної хатини', 'На вершині села', 'У Кінцевому небі', 0, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 1, false),
  ('desert-temple-desert', 'Плануючи маршрут за ресурсами, ти порівнюєш рельєф, рослини й структури, щоб не витратити день марно. Який біом є звичайним домом для пустельного храму? На основі цього визнач правильну місцевість або споруду.', 'Пустеля', 'Вишневий гай', 'Болото', 'Тайга', 0, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 2, false),
  ('dripstone-caves-have-pointed-dripstone', 'Плануючи маршрут за ресурсами, ти порівнюєш рельєф, рослини й структури, щоб не витратити день марно. Загострений сталактит є ознакою якого печерного біома? На основі цього визнач правильну місцевість або споруду.', 'Пляж', 'Грибні поля', 'Сталактитові печери', 'Вишневий гай', 2, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 3, false),
  ('igloo-in-snowy-biomes', 'Плануючи маршрут за ресурсами, ти порівнюєш рельєф, рослини й структури, щоб не витратити день марно. У сніжному біомі трапилась мала біла споруда; інколи під килимом у ній є прихований спуск. Що це? На основі цього визнач правильну місцевість або споруду.', 'Снігова хатина', 'Заросла пастками споруда в джунглях', 'Міст і коридори в Незері', 'Піскова споруда з пасткою', 0, 'Іглу пасують сніжним місцям і навіть можуть ховати маленький сюрприз унизу. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 4, true),
  ('jungle-temple-jungle', 'Плануючи маршрут за ресурсами, ти порівнюєш рельєф, рослини й структури, щоб не витратити день марно. Де генерують храми в джунглях? На основі цього визнач правильну місцевість або споруду.', 'Джунглі', 'Засніжені схили', 'Лука', 'Океан', 0, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 5, false),
  ('lush-caves-have-glow-berries', 'Плануючи маршрут за ресурсами, ти порівнюєш рельєф, рослини й структури, щоб не витратити день марно. Який печерний біом відомий сяйними ягодами та пишними рослинами? На основі цього визнач правильну місцевість або споруду.', 'Базальтові дельти', 'Безплідні землі', 'Засніжені рівнини', 'Зарослі печери', 3, 'Зарослі печери відомі густою рослинністю, мохом і сяйними ягодами. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 6, false),
  ('mangrove-swamp-has-mud', 'Плануючи маршрут за ресурсами, ти порівнюєш рельєф, рослини й структури, щоб не витратити день марно. Береги вкриті корінням, деревина червонувата, а замість звичайної землі часто трапляється багно. Який це біом? На основі цього визнач правильну місцевість або споруду.', 'Холодна водойма з кригою', 'Сухий біом з акаціями', 'Кольорові теракотові пагорби', 'Болотистий біом із мангровими деревами', 3, 'Мангрові болота вирізняються мангровим корінням, жабами та багнистою землею. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 7, true),
  ('mineshaft-underground', 'Плануючи маршрут за ресурсами, ти порівнюєш рельєф, рослини й структури, щоб не витратити день марно. Де найчастіше шукати покинуті шахти з дерев’яними проходами, рейками й павутиною? На основі цього визнач правильну місцевість або споруду.', 'На грибних островах', 'Під землею', 'Всередині океанів', 'В небі', 1, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 8, false),
  ('ocean-monument-guardians', 'Плануючи маршрут за ресурсами, ти порівнюєш рельєф, рослини й структури, щоб не витратити день марно. Під водою стоїть велика призмаринова споруда, де лазерними атаками зустрічають вартові. Куди ти потрапив? На основі цього визнач правильну місцевість або споруду.', 'Мала снігова споруда', 'Підземний шлях до порталу Краю', 'Підводний призмариновий храм', 'Темна лісова резиденція', 2, 'Океанські монументи — це підводні структури, які охороняють вартові та старші вартові. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 9, true),
  ('ocean-ruins-underwater', 'Плануючи маршрут за ресурсами, ти порівнюєш рельєф, рослини й структури, щоб не витратити день марно. Яка споруда зазвичай знаходиться під водою і часто складається з потертих кам’яних блоків? На основі цього визнач правильну місцевість або споруду.', 'Фортеця', 'Розбійницька застава', 'Підводні руїни', 'Лісовий маєток', 2, 'Підводні руїни — це затоплені структури, розкидані по океанах. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 10, false),
  ('pillager-outpost-has-pillagers', 'Плануючи маршрут за ресурсами, ти порівнюєш рельєф, рослини й структури, щоб не витратити день марно. Яка ворожа структура тісно асоціюється з грабіжниками? На основі цього визнач правильну місцевість або споруду.', 'Храм джунглів', 'Судові руїни', 'Океанічний монумент', 'Розбійницька застава', 3, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 11, false),
  ('shipwrecks-near-ocean', 'Плануючи маршрут за ресурсами, ти порівнюєш рельєф, рослини й структури, щоб не витратити день марно. Яка структура зазвичай зустрічається в океанічних районах? На основі цього визнач правильну місцевість або споруду.', 'Хатина відьми', 'Корабельна аварія', 'Лісовий маєток', 'Фортеця Незеру', 1, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 12, false),
  ('strongholds-underground', 'Плануючи маршрут за ресурсами, ти порівнюєш рельєф, рослини й структури, щоб не витратити день марно. Де зазвичай знаходяться опорні пункти, перш ніж гравці проникають у них? На основі цього визнач правильну місцевість або споруду.', 'Над океанами', 'На верхівках дерев', 'Всередині сіл', 'Під землею', 3, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 13, false),
  ('warm-ocean-has-coral', 'Плануючи маршрут за ресурсами, ти порівнюєш рельєф, рослини й структури, щоб не витратити день марно. З яким біомом найбільше пов’язані коралові рифи? На основі цього визнач правильну місцевість або споруду.', 'Замерзла річка', 'Теплий океан', 'Темні глибини', 'Тайга', 1, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 14, false),
  ('witch-hut-swamp', 'Плануючи маршрут за ресурсами, ти порівнюєш рельєф, рослини й структури, щоб не витратити день марно. Який біом асоціюється з хатинами відьом? На основі цього визнач правильну місцевість або споруду.', 'Болото', 'Безплідні землі', 'Савана', 'Пляж', 0, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 15, false),
  ('concrete-powder-hardens-in-water', 'У споруді треба врахувати форму, падіння, прозорість, сигнал або взаємодію блока з водою та інструментами. Що відбувається з бетонним порошком, коли він торкається води? На основі цього обери блок або будівельну поведінку, яка спрацює в грі.', 'Він перетворюється на бетон', 'Воно зникає', 'Він стає піском', 'Він росте вгору', 0, 'Бетонний порошок твердне після контакту з водою й перетворюється на бетон. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 16, false),
  ('fence-stops-animal-escape', 'У споруді треба врахувати форму, падіння, прозорість, сигнал або взаємодію блока з водою та інструментами. Який блок часто використовують для утримання тварин у загоні? На основі цього обери блок або будівельну поведінку, яка спрацює в грі.', 'Прапор', 'Скриня', 'Смолоскип', 'Паркан', 3, 'Паркани зручні для загонів, бо тварини не можуть просто пройти крізь них. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 17, false),
  ('ladder-climbs-wall', 'У споруді треба врахувати форму, падіння, прозорість, сигнал або взаємодію блока з водою та інструментами. У шахті зробили вертикальний прохід на кілька блоків угору, але місця для сходів немає. Що ставлять на стіну? На основі цього обери блок або будівельну поведінку, яка спрацює в грі.', 'Тонкий декоративний настил', 'Вертикальний блок для підйому', 'Відкидний дерев’яний блок', 'Огорожа для краю платформи', 1, 'Драбини кріпляться до блоків і створюють швидкий вертикальний шлях для гравця. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 18, true),
  ('slab-is-half-block', 'У споруді треба врахувати форму, падіння, прозорість, сигнал або взаємодію блока з водою та інструментами. Для плавного рівня підлоги потрібен блок на половину висоти, щоб не ставити повний куб. Що обрати? На основі цього обери блок або будівельну поведінку, яка спрацює в грі.', 'Тонкий скляний розділювач', 'Половинний будівельний блок', 'Вузький вертикальний бар’єр', 'Джерело світла на блоці', 1, 'Плити зручні для підлог, дахів і плавніших форм, бо вони мають половинну висоту. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 19, true),
  ('trapdoor-covers-hole', 'У споруді треба врахувати форму, падіння, прозорість, сигнал або взаємодію блока з водою та інструментами. Який навісний блок стане в нагоді для перекриття невеликого отвору підлоги? На основі цього обери блок або будівельну поведінку, яка спрацює в грі.', 'Натискна плита', 'Драбина', 'Табличка', 'Люк', 3, 'Люк добре перекриває отвір у підлозі або стелі на один блок. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 20, false),
  ('charcoal-works-for-torches', 'Який предмет кладуть над палицею, щоб скрафтити смолоскип?', 'Деревне вугілля', 'Кремінь', 'Порох', 'Світлокам''яний пил', 0, 'Смолоскипу підходить вугілля або деревне вугілля, тож переплавлені колоди виручать без руди.', 21, true),
  ('chest-needs-eight-planks', 'Скільки дощок потрібно, щоб скрафтити скриню?', '9', '6', '7', '8', 3, 'Дошки заповнюють усі клітинки сітки 3×3, крім центральної.', 22, true),
  ('sand-smelts-into-glass', 'Що вийде, якщо переплавити пісок у печі?', 'Скло', 'Незерський кварц', 'Гравій', 'Глина', 0, 'Жар плавить пісок у скло — головний блок для вікон.', 23, true),
  ('stonecutter-shapes-stone-builds', 'Яка робоча станція робить із блока сходи, плиту чи стіну без верстака?', 'Точило', 'Каменеріз', 'Ткацький верстат', 'Ковальський стіл', 1, 'Ти обираєш потрібну форму, а станція бере по одному блоку, тож повний рецепт не потрібен.', 24, true),
  ('bee-pollinates-crops', 'Який моб прискорює ріст посівів після відвідин квітів?', 'Кролик', 'Збирик', 'Папуга', 'Бджола', 3, 'Бджола з пилком допомагає посівам, над якими пролітає, тож вулик біля ферми прискорює її.', 25, true),
  ('water-keeps-farmland-hydrated', 'Який блок підтримує вологість ріллі поруч?', 'Лава', 'Сніговий блок', 'Лід', 'Вода', 3, 'Вода в межах 4 блоків тримає ріллю вологою й темною, а на вологій ріллі посіви ростуть швидше.', 26, true),
  ('dry-farmland-becomes-dirt', 'На що перетворюється суха рілля, на якій нічого не посаджено?', 'Гравій', 'Ґрунт', 'Багно', 'Пісок', 1, 'Без води й посівів рілля висихає і знову стає ґрунтом; стрибки по ній роблять те саме.', 27, true),
  ('kelp-grows-underwater', 'Яка рослина росте вгору, повністю перебуваючи під водою?', 'Цукрова тростина', 'Ламінарія', 'Бамбук', 'Кактус', 1, 'Ламінарія росте вгору крізь блоки води, тому чудово підходить для автоматичної підводної ферми.', 28, true),
  ('bone-tames-wolf', 'Який предмет треба згодувати дикому вовку, щоб приручити його?', 'Шкіра', 'Перо', 'Нитка', 'Кістка', 3, 'Кожна кістка має шанс приручити вовка, після чого він отримує нашийник і йде за тобою.', 29, true),
  ('enderman-hurt-by-water', 'Який моб отримує шкоду від води та дощу?', 'Павук', 'Відьма', 'Зомбі', 'Ендермен', 3, 'Вода ранить ендерменів, тому стати у воду — простий спосіб від них урятуватися.', 30, true),
  ('iron-golem-defends-village', 'Який великий моб з’являється в селах і відбиває зомбі?', 'Мандрівний крамар', 'Сніговий ґолем', 'Залізний ґолем', 'Розбійник', 2, 'Залізні ґолеми охороняють селян і нападають на ворожих мобів у селі.', 31, true),
  ('witch-throws-potions', 'Який ворожий моб атакує, кидаючи вибухові зілля?', 'Пломінь', 'Скелет', 'Потопельник', 'Відьма', 3, 'Відьми кидають шкідливі зілля, а самі п’ють зілля, щоб лікуватися.', 32, true),
  ('zombie-villager-cured', 'Якого моба можна вилікувати слабкістю й золотим яблуком?', 'Висушень', 'Зомбоселянин', 'Зомбі', 'Потопельник', 1, 'Зомбоселянин зі слабкістю після золотого яблука знову стає звичайним селянином.', 33, true),
  ('pillager-fires-crossbow', 'Якою зброєю атакує розбійник?', 'Тризубець', 'Арбалет', 'Сокира', 'Лук', 1, 'Розбійники — це ілагери, що стріляють здалеку з арбалетів.', 34, true),
  ('blaze-drops-rods', 'Ти збираєш портал, сигнал або прогрес до Краю й маєш правильно поєднати ресурс, моба або компонент. Для варильної стійки потрібні стрижні; їх добувають із літаючого ворожого моба у фортецях Незеру. Хто це? На основі цього обери компонент, ресурс або правило прогресії, яке спрацює.', 'Стрибучий лавовий куб', 'Вогняний моб фортець', 'Малий моб Краю', 'Темний скелет Незеру', 1, 'Іфрити дають стрижні іфрита, важливі для варіння зіль і пошуку Краю. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 35, true),
  ('blaze-powder-for-eye-of-ender', 'Ти збираєш портал, сигнал або прогрес до Краю й маєш правильно поєднати ресурс, моба або компонент. Який інгредієнт із Незеру поєднують із перлиною Ендера, щоб створити Око Ендера? На основі цього обери компонент, ресурс або правило прогресії, яке спрацює.', 'Порох', 'Незерська цеглина', 'Вогняний порошок', 'Світяться чорнила', 2, 'У прогресії між вимірами або редстоун-механіці ця умова є вирішальною. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 36, false),
  ('ghast-shoots-fireballs', 'Ти збираєш портал, сигнал або прогрес до Краю й маєш правильно поєднати ресурс, моба або компонент. У відкритому просторі Незеру чути крик, а великий літаючий моб запускає вибухові вогняні кулі. Хто атакує? На основі цього обери компонент, ресурс або правило прогресії, яке спрацює.', 'Моб для лавової їзди', 'Ворожий звір бастіонів', 'Білий літаючий моб', 'Моб, що торгує золотом', 2, 'Ґасти літають у великих просторах Незеру й атакують вогняними кулями. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 37, true),
  ('lever-toggles-circuit', 'Ти збираєш портал, сигнал або прогрес до Краю й маєш правильно поєднати ресурс, моба або компонент. Потрібен стабільний ручний перемикач: один клік вмикає схему, наступний вимикає. Що поставити? На основі цього обери компонент, ресурс або правило прогресії, яке спрацює.', 'Постійний ручний перемикач', 'Ємність для рідини', 'Декор для предмета', 'Блок для вертикального підйому', 0, 'Важіль лишається в обраному положенні після перемикання, тому він зручний для простого керування схемами. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 38, true),
  ('repeater-refreshes-signal', 'Ти збираєш портал, сигнал або прогрес до Краю й маєш правильно поєднати ресурс, моба або компонент. Який редстоун-компонент зазвичай використовують, щоб відновити ослаблений сигнал? На основі цього обери компонент, ресурс або правило прогресії, яке спрацює.', 'Драбина', 'Ліжко', 'Човен', 'Повторювач', 3, 'У прогресії між вимірами або редстоун-механіці ця умова є вирішальною. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 39, false),
  ('compass-points-to-world-spawn', 'Куди показує звичайний компас у звичайному світі?', 'Портал Незеру', 'Твоє ліжко', 'Найближче село', 'Точка появи світу', 3, 'Звичайний компас завжди вказує на точку появи світу, а не на ліжко чи базу.', 40, true),
  ('shield-blocks-attacks', 'Який предмет можна підняти, щоб блокувати стріли й удари?', 'Залізний шолом', 'Щит', 'Панцир черепахи', 'Залізний нагрудник', 1, 'Броня лише зменшує шкоду, а піднятий щит повністю блокує більшість ударів спереду.', 41, true),
  ('sleep-skips-thunderstorm', 'Коли, крім ночі, можна спати в ліжку?', 'Під час грози', 'Опівдні', 'Під час снігопаду', 'На світанку', 0, 'Під час грози досить темно для монстрів, тому ліжко працює навіть удень.', 42, true),
  ('water-bucket-softens-falls', 'Який предмет скасує шкоду від падіння, якщо поставити його перед приземленням?', 'Відро лави', 'Вудка', 'Відро молока', 'Відро води', 3, 'Приземлення у воду скасовує шкоду від падіння, тож вода перед ударом рятує.', 43, true),
  ('phantom-comes-after-no-sleep', 'Який літаючий моб нападає на гравців, що кілька ночей не спали?', 'Кажан', 'Бджола', 'Фантом', 'Папуга', 2, 'Фантоми з''являються в нічному небі над гравцями, які давно не спали.', 44, true),
  ('anvil-can-rename-items', 'Ти прокачуєш спорядження через торги й чари, тому маєш обрати станцію, ресурс або дію без зайвого рандому. Що корисного може зробити ковадло, крім ремонту й поєднання зачарувань? На основі цього обери професію, станцію, ресурс або зачарування без плутанини.', 'Змінювати біоми', 'Перейменовувати предмети', 'Переплавляти руди', 'Копіювати блоки', 1, 'Ковадло дає змогу не лише ремонтувати предмети, а й перейменовувати їх. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 45, false),
  ('anvil-combines-enchantments', 'Ти прокачуєш спорядження через торги й чари, тому маєш обрати станцію, ресурс або дію без зайвого рандому. Є зачарована книга й інструмент; потрібно перенести чари, витративши досвід, а не випадково зачаровувати заново. Який блок потрібен? На основі цього обери професію, станцію, ресурс або зачарування без плутанини.', 'Станція для їжі', 'Контейнер у селах', 'Блок ремонту й поєднання', 'Предмет для сну', 2, 'Ковадла використовують, щоб поєднувати предмети, перейменовувати їх і переносити чари з книг. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 46, true),
  ('bookshelves-need-air-gap', 'Ти прокачуєш спорядження через торги й чари, тому маєш обрати станцію, ресурс або дію без зайвого рандому. Щоб книжкова полиця живила стіл зачарування, що має залишатися між ними? На основі цього обери професію, станцію, ресурс або зачарування без плутанини.', 'Порожній блок повітря', 'Факел', 'Килим', 'Знак', 0, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 47, false),
  ('brewing-stand-makes-cleric', 'Ти прокачуєш спорядження через торги й чари, тому маєш обрати станцію, ресурс або дію без зайвого рандому. Селянин із якою робочою станцією стає священнослужителем? На основі цього обери професію, станцію, ресурс або зачарування без плутанини.', 'Каменеріз', 'Стіл лучника', 'Картографічний стіл', 'Варильна стійка', 3, 'Варильна стійка є блоком робочого місця священнослужителя. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 48, false),
  ('cartographer-sells-mansion-map', 'Ти прокачуєш спорядження через торги й чари, тому маєш обрати станцію, ресурс або дію без зайвого рандому. Хто може продати карту, яка допомагає гравцям знайти лісовий палац? На основі цього обери професію, станцію, ресурс або зачарування без плутанини.', 'Священник', 'Бібліотекар', 'Каменяр', 'Картограф', 3, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 49, false),
  ('cartographer-sells-ocean-map', 'Ти прокачуєш спорядження через торги й чари, тому маєш обрати станцію, ресурс або дію без зайвого рандому. Який селянин може продати карту, що веде до океанічного монумента? На основі цього обери професію, станцію, ресурс або зачарування без плутанини.', 'Мʼясник', 'Вівчар', 'Фермер', 'Картограф', 3, 'Картографи продають карти дослідника, які можуть вести до великих структур, зокрема океанічних монументів. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 50, false),
  ('curing-zombie-villager-lowers-prices', 'Ти прокачуєш спорядження через торги й чари, тому маєш обрати станцію, ресурс або дію без зайвого рандому. Після того як зомбі-селянин виліковується, що часто відбувається з його торговими цінами? На основі цього обери професію, станцію, ресурс або зачарування без плутанини.', 'Вони зникають назавжди', 'Вони стають випадковими біомами', 'Вони стають дешевшими', 'Вони перетворюються на ціни на ліжко', 2, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 51, false),
  ('enchanted-books-applied-with-anvil', 'Ти прокачуєш спорядження через торги й чари, тому маєш обрати станцію, ресурс або дію без зайвого рандому. Який блок використовують гравці, щоб застосувати зачаровану книгу на спорядження? На основі цього обери професію, станцію, ресурс або зачарування без плутанини.', 'Компостер', 'Дзвін', 'Ткацький верстат', 'Ковадло', 3, 'Ковадло найкраще відповідає описаній механіці села або зачарувань. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 52, false),
  ('enchanting-table-needs-xp-levels', 'Ти прокачуєш спорядження через торги й чари, тому маєш обрати станцію, ресурс або дію без зайвого рандому. Окрім лазуриту, на що ще витрачається стіл зачарування? На основі цього обери професію, станцію, ресурс або зачарування без плутанини.', 'Репутація села', 'Серця', 'Очки голоду', 'Рівні досвіду', 3, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 53, false),
  ('lectern-makes-librarian', 'Ти прокачуєш спорядження через торги й чари, тому маєш обрати станцію, ресурс або дію без зайвого рандому. Безробітному селянину треба дати професію, пов’язану з книгами й зачарованими книгами. Який робочий блок поставити? На основі цього обери професію, станцію, ресурс або зачарування без плутанини.', 'Підставка для книги', 'Блок фермера', 'Блок для шкіряника', 'Станція броняра', 0, 'Селяни отримують професії від робочих блоків поруч, і кафедра робить їх бібліотекарями. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 54, true),
  ('smithing-table-makes-toolsmith', 'Ти прокачуєш спорядження через торги й чари, тому маєш обрати станцію, ресурс або дію без зайвого рандому. Який блок робочого місця пов’язаний із професією коваля інструментів? На основі цього обери професію, станцію, ресурс або зачарування без плутанини.', 'Дзвін', 'Нотний блок', 'Ткацький верстат', 'Ковальський стіл', 3, 'Ковальський стіл є блоком робочого місця коваля інструментів. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 55, false),
  ('three-enchanting-choices', 'Ти прокачуєш спорядження через торги й чари, тому маєш обрати станцію, ресурс або дію без зайвого рандому. Скільки варіантів зачарування зазвичай показує стіл зачарування? На основі цього обери професію, станцію, ресурс або зачарування без плутанини.', '4', '1', '2', '3', 3, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 56, false),
  ('unemployed-villager-claims-job-block', 'Ти прокачуєш спорядження через торги й чари, тому маєш обрати станцію, ресурс або дію без зайвого рандому. Що може перетворити безробітного селянина на робітника? На основі цього обери професію, станцію, ресурс або зачарування без плутанини.', 'Тримає смарагд', 'Заявка на сусідній блок роботи', 'Боротьба з натовпом', 'Спить у Пустоті', 1, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 57, false),
  ('villager-needs-bed-to-breed', 'Ти прокачуєш спорядження через торги й чари, тому маєш обрати станцію, ресурс або дію без зайвого рандому. Що має бути в селі, щоб селяни успішно розмножувалися? На основі цього обери професію, станцію, ресурс або зачарування без плутанини.', 'Запасні ліжка', 'Басейни лави', 'Підставки для броні', 'Алмазні блоки', 0, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 58, false),
  ('villagers-restock-at-workstation', 'Ти прокачуєш спорядження через торги й чари, тому маєш обрати станцію, ресурс або дію без зайвого рандому. Куди зазвичай потрібен доступ селянину, щоб поповнити запаси торгів? На основі цього обери професію, станцію, ресурс або зачарування без плутанини.', 'Рецепт приготування', 'Маяк', 'Портал у Незер', 'Його робоча станція', 3, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 59, false),
  ('bread-easy-hunger-refill', 'Яку їжу можна скрафтити лише з трьох пшениць?', 'Торт', 'Гарбузовий пиріг', 'Печиво', 'Хліб', 3, 'Три пшениці в ряд дають хліб, а для печива треба какао, для торта й пирога яйця та цукор.', 60, true),
  ('milk-clears-most-effects', 'Який напій знімає всі ефекти одразу?', 'Відро молока', 'Пляшка води', 'Зілля зцілення', 'Пляшка меду', 0, 'Молоко знімає всі ефекти, і добрі, і погані, а мед прибирає лише отруєння.', 61, true),
  ('rotten-flesh-emergency-food', 'Який дроп зомбі їстівний, але часто викликає голод?', 'Картопля', 'Гнила плоть', 'Морква', 'Залізний злиток', 1, 'Гнила плоть із шансом 80% накладає голод, тож їж її лише в крайньому разі.', 62, true),
  ('air-bubbles-show-drowning', 'Які значки під водою зникають, перш ніж ти почнеш тонути?', 'Значки броні', 'Шкала досвіду', 'Курячі ніжки', 'Бульбашки повітря', 3, 'Бульбашки показують запас повітря; коли їх немає, ти щосекунди втрачаєш здоров''я.', 63, true),
  ('spider-eye-causes-poison', 'Яка їжа завжди отруює, коли її з''їси?', 'Солодкі ягоди', 'Павуче око', 'Гнила плоть', 'Сира курятина', 1, 'Павуче око завжди дає отруєння, а гнила плоть і сира курятина лише можуть дати голод.', 64, true),
  ('torches-help-stop-indoor-spawns', 'Що не дає ворожим мобам з''являтися у твоєму домі?', 'Смолоскипи', 'Квіткові горщики', 'Картини', 'Рамки', 0, 'Ворожим мобам для появи потрібна повна темрява, а смолоскипи її прибирають.', 65, true),
  ('sleep-turns-world-to-morning', 'Що може завадити тобі спати в ліжку вночі?', 'Монстри поруч', 'Надіта броня', 'Повний інвентар', 'Мало ситості', 0, 'Ти не зможеш спати, поки ворожі моби ближче ніж приблизно 8 блоків до ліжка.', 66, true),
  ('roof-completes-first-shelter', 'Скільки хвилин реального часу триває повна ігрова доба?', '60', '30', '20', '10', 2, 'Повна доба триває 20 хвилин, і приблизно 7 із них — ніч, коли блукають ворожі моби.', 67, true),
  ('water-puts-out-fire', 'Що швидко гасить вогонь, коли ти гориш?', 'Пісок', 'Вовна', 'Вода', 'Гравій', 2, 'Вода одразу гасить вогонь, тож тримай відро води біля лави.', 68, true),
  ('minecart-rides-on-rails', 'Який транспорт створено для їзди по рейках?', 'Елітри', 'Човен', 'Вагонетка', 'Повідець', 2, 'Вагонетка їде по рейках і може везти гравців, мобів чи речі.', 69, true),
  ('wooden-sword-basic-weapon', 'Який предмет крафтять із двох дощок і однієї палиці?', 'Дерев''яний меч', 'Дерев''яна сокира', 'Дерев''яне кайло', 'Дерев''яна лопата', 0, 'Дві дошки на палиці дають меч, а кайлу чи сокирі потрібно три дошки й дві палиці.', 70, true),
  ('log-smelts-into-charcoal', 'Що вийде, якщо переплавити колоду в печі?', 'Палиця', 'Вугілля', 'Дошки', 'Деревне вугілля', 3, 'Переплавлена колода стає деревним вугіллям, яке горить так само довго, як звичайне.', 71, true),
  ('cobblestone-smelts-into-stone', 'Що вийде, якщо переплавити кактус у печі?', 'Слизова кулька', 'Лаймовий барвник', 'Зелений барвник', 'Висушена ламінарія', 2, 'Переплавлений кактус дає зелений барвник, а з білим барвником він стає лаймовим.', 72, true),
  ('dried-kelp-block-is-fuel', 'Який із цих блоків можна спалити в печі як паливо?', 'Блок висушеної ламінарії', 'Медовий блок', 'Слизовий блок', 'Копиця соломи', 0, 'Блок висушеної ламінарії переплавляє 20 предметів, тож ферма ламінарії дає безкінечне паливо.', 73, true),
  ('anvil-renames-and-repairs', 'Яка робоча станція дає перейменовувати предмети й поєднувати зачарування?', 'Ковальський стіл', 'Ковадло', 'Картографічний стіл', 'Ткацький верстат', 1, 'Ковадло витрачає рівні досвіду, щоб перейменувати, полагодити чи поєднати зачаровані речі.', 74, true),
  ('loom-adds-banner-patterns-crafting', 'Яка робоча станція додає візерунки на прапори?', 'Точило', 'Коптильня', 'Ткацький верстат', 'Домна', 2, 'Станція поєднує прапор і барвник, щоб додавати візерунки шар за шаром.', 75, true),
  ('grindstone-clears-enchantments', 'Який блок крафтять, оточивши піч чотирма колодами?', 'Багаття', 'Діжка', 'Коптильня', 'Домна', 2, 'Чотири колоди навколо печі дають коптильню, яка ще й є робочим блоком м''ясника.', 76, true),
  ('stone-pickaxe-mines-iron-ore', 'Яке найслабше кайло вже може добути залізну руду?', 'Золоте кайло', 'Залізне кайло', 'Кам''яне кайло', 'Дерев''яне кайло', 2, 'Дерев''яне й золоте кайла ламають залізну руду без здобичі, тож мінімум — кам''яне.', 77, true),
  ('shears-need-iron-ingots', 'Який предмет крафтять лише з двох залізних злитків?', 'Казан', 'Відро', 'Вагонетка', 'Ножиці', 3, 'Два залізні злитки по діагоналі дають ножиці, а для відра їх потрібно три.', 78, true),
  ('paper-from-sugar-cane', 'На що крафтять цукрову тростину для книг і мап?', 'Глина', 'Папір', 'Нитка', 'Шкіра', 1, 'Три цукрові тростини в ряд дають три аркуші паперу для книг, мап і феєрверків.', 79, true),
  ('flint-and-steel-lights-portals', 'Яке паливо для печі переплавляє найбільше предметів?', 'Блок висушеної ламінарії', 'Відро лави', 'Блок вугілля', 'Стрижень пломеня', 1, 'Відро лави переплавляє 100 предметів — більше, ніж блок вугілля (80), тож лава — чудове паливо.', 80, true),
  ('sandstone-crafted-from-sand', 'У споруді треба врахувати форму, падіння, прозорість, сигнал або взаємодію блока з водою та інструментами. Чотири піщані блоки створюють будівельний блок пустелі в сітці крафта? На основі цього обери блок або будівельну поведінку, яка спрацює в грі.', 'Лимпач', 'Камʼяна цегла', 'Кварцовий блок', 'Пісковик', 3, 'Пісковик — саме той блок чи предмет, що підходить до описаної властивости або будівельної ситуації. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 81, false),
  ('stone-bricks-crafted-from-stone', 'У споруді треба врахувати форму, падіння, прозорість, сигнал або взаємодію блока з водою та інструментами. Який класичний сірий будівельний блок складається з чотирьох кам’яних блоків? На основі цього обери блок або будівельну поведінку, яка спрацює в грі.', 'Гладкий кварц', 'Сходи з кругляку', 'Камʼяна цегла', 'Шибка', 2, 'Камʼяна цегла найкраще пасує до описаної поведінки блока або будівельного використання. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 82, false),
  ('axe-creates-stripped-log', 'У споруді треба врахувати форму, падіння, прозорість, сигнал або взаємодію блока з водою та інструментами. Який чистіший варіант деревини створює сокира, яка використовується на колоді? На основі цього обери блок або будівельну поведінку, яка спрацює в грі.', 'Тесана мідь', 'Обдираний журнал', 'Моховий блок', 'Точений камінь', 1, 'Обдираний журнал найкраще пасує до описаної поведінки блока або будівельного використання. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 83, false),
  ('smooth-stone-comes-from-second-smelt', 'У споруді треба врахувати форму, падіння, прозорість, сигнал або взаємодію блока з водою та інструментами. Якщо звичайний камінь знову виплавити, який більш гладкий блок вийде? На основі цього обери блок або будівельну поведінку, яка спрацює в грі.', 'Полірований андезит', 'Глибосланець', 'Тріснута кам''яна цегла', 'Гладкий камінь', 3, 'Поведінка блока в світі збігається з описаною будівельною ситуацією. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 84, false),
  ('terracotta-smelts-from-clay-block', 'У споруді треба врахувати форму, падіння, прозорість, сигнал або взаємодію блока з водою та інструментами. Коли глиняний блок плавлять, яким твердим будівельним блоком він стає? На основі цього обери блок або будівельну поведінку, яка спрацює в грі.', 'Теракота', 'Сніговий блок', 'Бетонні', 'Пісковик', 0, 'Теракота — саме той блок чи предмет, що підходить до описаної властивости або будівельної ситуації. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 85, false),
  ('pressure-plate-sends-signal-when-stepped-on', 'У споруді треба врахувати форму, падіння, прозорість, сигнал або взаємодію блока з водою та інструментами. Який плаский блок подає редстоун-сигнал, коли на нього наступає гравець або моб? На основі цього обери блок або будівельну поведінку, яка спрацює в грі.', 'Натискна плита', 'Квітковий горщик', 'Люк', 'Килим', 0, 'Поведінка блока в світі збігається з описаною будівельною ситуацією. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 86, false),
  ('glass-drops-nothing-without-silk-touch', 'У споруді треба врахувати форму, падіння, прозорість, сигнал або взаємодію блока з водою та інструментами. Який віконний блок, зламаний звичайним інструментом, зазвичай нічого не падає? На основі цього обери блок або будівельну поведінку, яка спрацює в грі.', 'Скло', 'Кругляк', 'Ґрунт', 'Драбина', 0, 'Поведінка блока в світі збігається з описаною будівельною ситуацією. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 87, false),
  ('leaves-decay-without-nearby-log', 'У споруді треба врахувати форму, падіння, прозорість, сигнал або взаємодію блока з водою та інструментами. Якщо їх немає біля колод, що часто відбувається з природним листям після зрізу дерева? На основі цього обери блок або будівельну поведінку, яка спрацює в грі.', 'Вони стають вовною', 'Вони перетворюються на камінь', 'Вони розкладаються', 'Вони загоряються автоматично', 2, 'Вони розкладаються найкраще пасує до описаної поведінки блока або будівельного використання. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 88, false),
  ('sponge-soaks-up-water', 'У споруді треба врахувати форму, падіння, прозорість, сигнал або взаємодію блока з водою та інструментами. Який блок, поміщений у воду, вбирає сусідні блоки джерела води? На основі цього обери блок або будівельну поведінку, яка спрацює в грі.', 'Теракота', 'Вовна', 'Губка', 'Корінна порода', 2, 'Губка найкраще пасує до описаної поведінки блока або будівельного використання. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 89, false),
  ('unsupported-scaffolding-breaks', 'У споруді треба врахувати форму, падіння, прозорість, сигнал або взаємодію блока з водою та інструментами. Якщо знизу немає опори в межах діапазону, який високий будівельний блок зрештою зламається? На основі цього обери блок або будівельну поведінку, яка спрацює в грі.', 'Скло', 'Бочка', 'Підмостки', 'Паркан', 2, 'Підмостки — саме той блок чи предмет, що підходить до описаної властивости або будівельної ситуації. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 90, false),
  ('potatoes-grow-from-potatoes', 'Яка культура під час збору іноді дає отруйну версію себе?', 'Буряк', 'Морква', 'Солодкі ягоди', 'Картопля', 3, 'Дозріла картопля має невеликий шанс дати ще й отруйну картоплю, яку їсти небезпечно.', 91, true),
  ('sugar-cane-needs-water-nearby', 'Яку рослину можна посадити лише на блок, що торкається води?', 'Бамбук', 'Цукрова тростина', 'Кактус', 'Солодкі ягоди', 1, 'Цукровій тростині потрібна вода біля блока, на якому вона стоїть, тому вона росте вздовж річок.', 92, true),
  ('egg-is-needed-for-cake', 'Що, крім молока, цукру й пшениці, входить у рецепт торта?', 'Шкіра', 'Перо', 'Яйце', 'Пляшка меду', 2, 'Торт — це 3 відра молока, 2 цукру, 3 пшениці та 1 яйце, тож потрібні і кури, і корови.', 93, true),
  ('sugar-completes-pumpkin-pie', 'Гарбузовий пиріг крафтять із гарбуза, яйця і чого ще?', 'Цукор', 'Какао-боби', 'Пшениця', 'Відро молока', 0, 'Гарбузовий пиріг — це лише гарбуз, яйце й цукор із тростини, без молока та пшениці.', 94, true),
  ('seeds-breed-chickens', 'Яким предметом розводять курей?', 'Яблуко', 'Пшениця', 'Хліб', 'Насіння пшениці', 3, 'Кури їдять насіння, а не пшеницю; підійде будь-яке насіння, зокрема гарбузове, кавунове й бурякове.', 95, true),
  ('golden-carrot-breeds-rabbits', 'Якою квіткою можна розводити кроликів?', 'Мак', 'Кульбаба', 'Волошка', 'Королиця', 1, 'Кролики розмножуються від моркви, золотої моркви або кульбаби — жовтої квітки, яку вони їдять.', 96, true),
  ('golden-apple-breeds-horses', 'Яка їжа змушує двох приручених коней розмножитися?', 'Золоте яблуко', 'Цукор', 'Яблуко', 'Пшениця', 0, 'Коні розмножуються лише від золотих яблук або золотої моркви; яблука, цукор і пшениця їх лише лікують.', 97, true),
  ('cocoa-beans-grow-on-jungle-logs', 'На яку колоду можна посадити какао-боби?', 'Березова колода', 'Дубова колода', 'Тропічна колода', 'Мангрова колода', 2, 'Плоди какао ростуть збоку на тропічних колодах — тих самих деревах, на яких висять у джунглях.', 98, true),
  ('glass-bottle-collects-honey', 'Яким предметом набирають мед із повного вулика?', 'Казан', 'Скляна пляшка', 'Відро', 'Миска', 1, 'Мед набирають у порожню скляну пляшку, і пляшка меду ще й лікує отруєння.', 99, true),
  ('shears-collect-honeycomb', 'Яким інструментом збирають медові стільники з повного вулика?', 'Ножиці', 'Лопата', 'Сокира', 'Мотика', 0, 'Ножиці зрізають 3 медові стільники з повного вулика чи гнізда, а з них роблять свічки й вощать мідь.', 100, true),
  ('cocoa-beans-craft-cookies', 'Який інгредієнт кладуть між двома пшеницями, щоб скрафтити печиво?', 'Какао-боби', 'Цукор', 'Буряк', 'Яйце', 0, 'Дві пшениці з какао-бобами посередині дають 8 печив, тож ферма какао варта уваги.', 101, true),
  ('goat-can-ram-players', 'Який гірський моб може раптово протаранити тебе й скинути зі скелі?', 'Кролик', 'Вівця', 'Коза', 'Лама', 2, 'Кози живуть у горах і часом розганяються на гравця, штовхаючи його з урвища.', 102, true),
  ('llama-spits-when-angry', 'Яка тварина плюється в мобів і гравців, що на неї нападають?', 'Кінь', 'Панда', 'Коза', 'Лама', 3, 'Лами захищаються плювками, а вовків обпльовують, щойно побачать.', 103, true),
  ('bee-dies-after-stinging', 'Який моб гине незабаром після того, як когось ужалить?', 'Ендермайт', 'Фантом', 'Бджола', 'Печерний павук', 2, 'Ужаливши, бджола втрачає жало й гине приблизно за хвилину.', 104, true),
  ('polar-bear-protects-cub', 'Яка тварина сніжних біомів нападає, якщо підійти до її малюка?', 'Білий ведмідь', 'Лисиця', 'Коза', 'Кролик', 0, 'Дорослі білі ведмеді нейтральні, але нападають на гравця біля своїх малюків.', 105, true),
  ('drowned-can-throw-trident', 'Який підводний моб-нежить може кинути в тебе тризубець?', 'Скелет', 'Потопельник', 'Зомбі', 'Висушень', 1, 'Деякі потопельники мають тризубець і кидають його; лише з них він може випасти.', 106, true),
  ('ghast-launches-fireballs', 'Який моб засніжених біомів стріляє стрілами, що дають Повільність?', 'Скелет', 'Примара', 'Висушень', 'Розбійник', 1, 'Примари — крижані скелети засніжених біомів, а їхні стріли сповільнюють тебе.', 107, true),
  ('arrows-needed-for-bow', 'Який предмет стає наконечником у рецепті стріли?', 'Гравій', 'Кістка', 'Кремінь', 'Залізний самородок', 2, 'Стріли крафтять із кременю, палиці й пера; кремінь випадає з гравію.', 108, true),
  ('golden-apple-gives-extra-hearts', 'Який предмет крафтять із шести дощок і одного залізного злитка?', 'Арбалет', 'Діжка', 'Щит', 'Відро', 2, 'Шість дощок і залізний злиток зверху дають щит, який блокує більшість атак спереду.', 109, true),
  ('potion-of-healing-restores-health', 'Яке зілля миттєво повертає втрачені серця?', 'Зілля вогнестійкости', 'Зілля зцілення', 'Зілля швидкости', 'Зілля нічного бачення', 1, 'Зцілення діє одразу, на відміну від регенерації, що відновлює серця поступово.', 110, true),
  ('end-crystal-heals-dragon', 'Ти збираєш портал, сигнал або прогрес до Краю й маєш правильно поєднати ресурс, моба або компонент. Який предмет, що стоїть на обсидіанових стовпах, відновлює здоров''я дракона? На основі цього обери компонент, ресурс або правило прогресії, яке спрацює.', 'Маяк', 'Кристал Енду', 'Морський ліхтар', 'Якір відродження', 1, 'У прогресії між вимірами або редстоун-механіці ця умова є вирішальною. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 111, false),
  ('dragon-egg-appears-after-fight', 'Ти збираєш портал, сигнал або прогрес до Краю й маєш правильно поєднати ресурс, моба або компонент. Який рідкісний трофейний блок з’явиться на порталі виходу після перемоги над драконом? На основі цього обери компонент, ресурс або правило прогресії, яке спрацює.', 'Маяк', 'Яйце дракона', 'Провідник', 'Зірка Незеру', 1, 'Яйце дракона найкраще відповідає описаній механіці редстоуну або вимірів. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 112, false),
  ('shulker-causes-levitation', 'Ти збираєш портал, сигнал або прогрес до Краю й маєш правильно поєднати ресурс, моба або компонент. Який ворожий моб у містах Енду накладає левітацію своїми снарядами? На основі цього обери компонент, ресурс або правило прогресії, яке спрацює.', 'Піглін', 'Шалкер', 'Слизень', 'Іфрит', 1, 'Шалкери стріляють снарядами, які накладають ефект левітації. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 113, false),
  ('fire-resistance-helps-in-lava', 'Ти збираєш портал, сигнал або прогрес до Краю й маєш правильно поєднати ресурс, моба або компонент. Ефект якого зілля особливо корисний для перетину небезпечних лавових ділянок? На основі цього обери компонент, ресурс або правило прогресії, яке спрацює.', 'Нічне бачення', 'Повільне падіння', 'Вогнестійкість', 'Везіння', 2, 'У прогресії між вимірами або редстоун-механіці ця умова є вирішальною. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 114, false),
  ('lodestone-guides-special-compass', 'Ти збираєш портал, сигнал або прогрес до Краю й маєш правильно поєднати ресурс, моба або компонент. На який блок може вказувати намагнічений компас у вимірах, де звичайний компас не працює? На основі цього обери компонент, ресурс або правило прогресії, яке спрацює.', 'Ковальський стіл', 'Магнетит', 'Маяк', 'Дзвін', 1, 'Магнетит прив’язує до себе компас і дає йому напрямок у вимірах, де звичайний компас не працює. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 115, false),
  ('respawn-anchor-sets-spawn-in-nether', 'Ти збираєш портал, сигнал або прогрес до Краю й маєш правильно поєднати ресурс, моба або компонент. Який блок після заряджання дозволяє встановити точку відродження в Незері? На основі цього обери компонент, ресурс або правило прогресії, яке спрацює.', 'Верстак', 'Програвач', 'Багаття', 'Якір відродження', 3, 'Якір відродження після заряджання світлокаменем дозволяє відроджуватися в Незері. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 116, false),
  ('soul-speed-helps-on-soul-sand', 'Ти збираєш портал, сигнал або прогрес до Краю й маєш правильно поєднати ресурс, моба або компонент. Яке зачарування прискорює рух по піску душ і ґрунту душ? На основі цього обери компонент, ресурс або правило прогресії, яке спрацює.', 'Швидкість душ', 'Грабунок', 'Невагомість', 'Дихання', 0, 'У прогресії між вимірами або редстоун-механіці ця умова є вирішальною. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 117, false),
  ('comparator-reads-container-fullness', 'Ти збираєш портал, сигнал або прогрес до Краю й маєш правильно поєднати ресурс, моба або компонент. Який редстоун-компонент зчитує, наскільки заповнений контейнер? На основі цього обери компонент, ресурс або правило прогресії, яке спрацює.', 'Компаратор', 'Люк', 'Кнопка', 'Поршень', 0, 'Компаратор найкраще відповідає описаній механіці редстоуну або вимірів. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 118, false),
  ('sticky-piston-pulls-block-back', 'Ти збираєш портал, сигнал або прогрес до Краю й маєш правильно поєднати ресурс, моба або компонент. Який тип поршня після втягування може потягнути блок назад? На основі цього обери компонент, ресурс або правило прогресії, яке спрацює.', 'Липкий поршень', 'Спостерігач', 'Редстоунова лампа', 'Датчик денного світла', 0, 'Липкий поршень найкраще відповідає описаній механіці редстоуну або вимірів. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 119, false),
  ('note-block-plays-musical-tone', 'Ти збираєш портал, сигнал або прогрес до Краю й маєш правильно поєднати ресурс, моба або компонент. Який декоративний блок відтворює музичну ноту після імпульсу? На основі цього обери компонент, ресурс або правило прогресії, яке спрацює.', 'Точило', 'Бочка', 'Нотний блок', 'Скриня', 2, 'Нотний блок найкраще відповідає описаній механіці редстоуну або вимірів. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 120, false)
) as v(content_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, sort_order, is_active)
where pack.slug = 'minecraft-uk-medium'
on conflict (pack_id, content_id) do update set
  prompt = excluded.prompt,
  option_a = excluded.option_a,
  option_b = excluded.option_b,
  option_c = excluded.option_c,
  option_d = excluded.option_d,
  correct_option = excluded.correct_option,
  explanation = excluded.explanation,
  sort_order = excluded.sort_order,
  is_active = excluded.is_active;

insert into public.question_packs (category_id, locale, age_band, difficulty, title, slug, is_active)
select id, 'uk', '8-12', 'hard', 'MineMind uk hard', 'minecraft-uk-hard', true
from public.quiz_categories
where slug = 'minecraft'
on conflict (slug) do update set is_active = true, title = excluded.title;

insert into public.questions (pack_id, content_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, sort_order, is_active)
select pack.id, v.content_id, v.prompt, v.option_a, v.option_b, v.option_c, v.option_d, v.correct_option, v.explanation, v.sort_order, v.is_active
from public.question_packs pack
cross join (values
  ('ancient-city-deep-dark', 'Про-режим: ти ведеш довгу експедицію без зовнішньої мапи й маєш відрізнити біом або структуру за практичними наслідками для маршруту; для рейду по скалк-лут і уникнення вардена треба заздалегідь знати, в якому біомі шукати стародавні міста. Який це біом? На основі механіки Minecraft визнач правильну місцевість або споруду.', 'Темні глибини', 'Сталактитові печери', 'Зарослі печери', 'Базальтові дельти', 0, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 1, false),
  ('badlands-above-ground-mineshafts', 'Про-режим: ти ведеш довгу експедицію без зовнішньої мапи й маєш відрізнити біом або структуру за практичними наслідками для маршруту; ти шукаєш відкриті покинуті шахти без довгого копання під землею. Який біом найчастіше дає таку перевагу? На основі механіки Minecraft визнач правильну місцевість або споруду.', 'Безплідні землі', 'Грибні поля', 'Теплий океан', 'Вишневий гай', 0, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 2, false),
  ('bastion-remnant-nether', 'Про-режим: ти ведеш довгу експедицію без зовнішньої мапи й маєш відрізнити біом або структуру за практичними наслідками для маршруту; маршрут за золотом, піглінами й небезпечними залишками бастіонів планують у конкретному вимірі. Де вони генеруються? На основі механіки Minecraft визнач правильну місцевість або споруду.', 'Звичайний світ', 'Незер', 'Всі розміри', 'Край', 1, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 3, false),
  ('buried-treasure-found-from-map', 'Про-режим: ти ведеш довгу експедицію без зовнішньої мапи й маєш відрізнити біом або структуру за практичними наслідками для маршруту; після корабельної аварії ти не копаєш навмання, а йдеш за предметом, що веде до X на узбережжі. Що це? На основі механіки Minecraft визнач правильну місцевість або споруду.', 'Карта скарбів', 'Зачарована книга', 'Дзвіночок', 'Козячий ріг', 0, 'Закопані скарби зазвичай шукають за картою скарбів. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 4, false),
  ('deep-dark-has-sculk', 'Про-режим: ти ведеш довгу експедицію без зовнішньої мапи й маєш відрізнити біом або структуру за практичними наслідками для маршруту; якщо навколо скалк, сенсори й ризик викликати вардена, який біом ти фактично знайшов? На основі механіки Minecraft визнач правильну місцевість або споруду.', 'Пляж', 'Савана', 'Темні глибини', 'Річка', 2, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 5, false),
  ('desert-well-desert', 'Про-режим: ти ведеш довгу експедицію без зовнішньої мапи й маєш відрізнити біом або структуру за практичними наслідками для маршруту; під час спідран-маршруту ти бачиш малу криницю без луту; вона прив’язана до сухого біома. Якого? На основі механіки Minecraft визнач правильну місцевість або споруду.', 'Лука', 'Мангрове болото', 'Крижані вершини', 'Пустеля', 3, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 6, false),
  ('end-city-has-shulkers', 'Про-режим: ти ведеш довгу експедицію без зовнішньої мапи й маєш відрізнити біом або структуру за практичними наслідками для маршруту; тобі потрібні шалкерові панцирі для коробок, тож ціль — структура, де шалкери спавняться природно. Яка? На основі механіки Minecraft визнач правильну місцевість або споруду.', 'Іглу', 'Храм джунглів', 'Місто Енду', 'Пустельний колодязь', 2, 'Шалкери мешкають у містах Енду, де також можна знайти цінну здобич. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 7, false),
  ('end-city-outer-end', 'Про-режим: ти ведеш довгу експедицію без зовнішньої мапи й маєш відрізнити біом або структуру за практичними наслідками для маршруту; після дракона ти йдеш через портал-шлюз і шукаєш елітри. У якому регіоні з’являються міста Енду? На основі механіки Minecraft визнач правильну місцевість або споруду.', 'Надсвітове дно океану', 'Зовнішні острови Енду', 'Будь-який сільський біом', 'Дах Незеру', 1, 'Міста Енду генеруються на зовнішніх островах Енду, а не біля центрального острова дракона. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 8, false),
  ('frozen-ocean-has-icebergs', 'Про-режим: ти ведеш довгу експедицію без зовнішньої мапи й маєш відрізнити біом або структуру за практичними наслідками для маршруту; для льодових ресурсів і айсбергів ти обираєш океанічний біом із холодною генерацією. Який саме? На основі механіки Minecraft визнач правильну місцевість або споруду.', 'Болото', 'Теплий океан', 'Замерзлий океан', 'Безплідні землі', 2, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 9, false),
  ('mushroom-fields-safe-from-many-mobs', 'Про-режим: ти ведеш довгу експедицію без зовнішньої мапи й маєш відрізнити біом або структуру за практичними наслідками для маршруту; потрібна база з мінімальним природним спавном звичайних ворожих мобів і муухоморами поруч. Який біом шукаєш? На основі механіки Minecraft визнач правильну місцевість або споруду.', 'Грибний острівний біом', 'Сухий біом з акаціями', 'Хвойний біом', 'Високогірний кам’яний біом', 0, 'Грибні поля незвичайні й спокійні, тому там особливо безпечно досліджувати світ. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 10, true),
  ('nether-fortress-has-blazes', 'Про-режим: ти ведеш довгу експедицію без зовнішньої мапи й маєш відрізнити біом або структуру за практичними наслідками для маршруту; для стрижнів іфрита й прогресу до Краю треба знайти структуру з природними спавнерами іфритів. Яку? На основі механіки Minecraft визнач правильну місцевість або споруду.', 'Підводні руїни', 'Фортеця Незеру', 'Розбійницька застава', 'Лісовий маєток', 1, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 11, false),
  ('ruined-portal-two-dimensions', 'Про-режим: ти ведеш довгу експедицію без зовнішньої мапи й маєш відрізнити біом або структуру за практичними наслідками для маршруту; ти фармиш скрині зруйнованих порталів і враховуєш, у яких вимірах вони можуть згенеруватися. Яка пара правильна? На основі механіки Minecraft визнач правильну місцевість або споруду.', 'Незер і Край', 'Звичайний світ і Край', 'Звичайний світ і Незер', 'Лише звичайний світ', 2, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 12, false),
  ('stronghold-holds-end-portal', 'Про-режим: ти ведеш довгу експедицію без зовнішньої мапи й маєш відрізнити біом або структуру за практичними наслідками для маршруту; око Ендера веде до кам’яно-цегляного комплексу з бібліотеками й кімнатою порталу. Яка це структура? На основі механіки Minecraft визнач правильну місцевість або споруду.', 'Підземне місто в глибинній темряві', 'Підземна твердиня з порталом', 'Вежа розбійників', 'Поселення мешканців', 1, 'Фортеці особливі тим, що їхня портал-кімната веде до виміру Край. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 13, true),
  ('trial-chamber-underground', 'Про-режим: ти ведеш довгу експедицію без зовнішньої мапи й маєш відрізнити біом або структуру за практичними наслідками для маршруту; для пробних спавнерів і ключів треба планувати підземний рейд, а не пошук на поверхні. Де шукати пробні палаци? На основі механіки Minecraft визнач правильну місцевість або споруду.', 'Над річками', 'Всередині сіл', 'Під землею', 'У точці появи світу', 2, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 14, false),
  ('woodland-mansion-dark-forest', 'Про-режим: ти ведеш довгу експедицію без зовнішньої мапи й маєш відрізнити біом або структуру за практичними наслідками для маршруту; щоб знайти заклиначів і тотеми без рейду, ти йдеш за маєтком у правильний біом. Який? На основі механіки Minecraft визнач правильну місцевість або споруду.', 'Савана', 'Пустеля', 'Темний ліс', 'Березовий ліс', 2, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 15, false),
  ('honey-block-slows-slide', 'Про-режим: ти проектуєш механізм або складну базу й маєш вибрати блок за точною фізикою, дропом або редстоун-поведінкою; у паркурі або механізмі треба блок, що липко сповільнює ковзання сутностей по боковій грані. Який? На основі механіки Minecraft обери блок або будівельну поведінку, яка спрацює в грі.', 'Вугільний блок', 'Морський ліхтар', 'Склоблок', 'Медовий блок', 3, 'Поведінка блока в світі збігається з описаною будівельною ситуацією. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 16, false),
  ('piston-pushes-blocks', 'Про-режим: ти проектуєш механізм або складну базу й маєш вибрати блок за точною фізикою, дропом або редстоун-поведінкою; у редстоун-модулі сигнал має фізично пересунути блок на одну клітинку. Який компонент виконує штовхання? На основі механіки Minecraft обери блок або будівельну поведінку, яка спрацює в грі.', 'Блок, що зчитує зміну перед собою', 'Блок, що викидає предмети', 'Блок для порівняння сили сигналу', 'Механізм зі штовхальною головкою', 3, 'Поршні є класичними редстоун-блоками для штовхання й пересування інших блоків. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 17, true),
  ('scaffolding-climbs-fast', 'Про-режим: ти проектуєш механізм або складну базу й маєш вибрати блок за точною фізикою, дропом або редстоун-поведінкою; будуєш висоту без постійних драбин і хочеш швидко розбирати тимчасову опору зверху донизу. Що ставиш? На основі механіки Minecraft обери блок або будівельну поведінку, яка спрацює в грі.', 'Блок для тренування стрільби', 'Декор для зачарувального столу', 'Тимчасова бамбукова конструкція', 'Блок для зняття зачарувань', 2, 'Підмостки чудово підходять для високих будівель, бо на них легко лазити й прибирати їх. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 18, true),
  ('slime-block-bounces-fall', 'Про-режим: ти проектуєш механізм або складну базу й маєш вибрати блок за точною фізикою, дропом або редстоун-поведінкою; для трюкового спуску або лаунчера потрібен блок, що гасить падіння відскоком угору. Який? На основі механіки Minecraft обери блок або будівельну поведінку, яка спрацює в грі.', 'Моховий блок', 'Гравій', 'Книжкова шафа', 'Слизовий блок', 3, 'Поведінка блока в світі збігається з описаною будівельною ситуацією. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 19, false),
  ('stairs-make-corners', 'Про-режим: ти проектуєш механізм або складну базу й маєш вибрати блок за точною фізикою, дропом або редстоун-поведінкою; у даху чи декоративному контурі блок має автоматично міняти форму на внутрішніх і зовнішніх кутах. Що використовують? На основі механіки Minecraft обери блок або будівельну поведінку, яка спрацює в грі.', 'Пласкі редстоун-перемикачі', 'Ступінчасті будівельні блоки', 'Вузькі прозорі перегородки', 'Рухомі елементи паркану', 1, 'Сходи зʼєднуються в кутові форми, тому дахи й доріжки виглядають плавніше. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 20, true),
  ('blast-furnace-smelts-ore-fast', 'Який блок перетворює сире золото на злитки вдвічі швидше, ніж зазвичай?', 'Картографічний стіл', 'Коптильня', 'Каменеріз', 'Домна', 3, 'Цей блок працює лише з рудою та металевим спорядженням, зате вдвічі швидше.', 21, true),
  ('compass-needs-redstone', 'Який предмет лежить у центрі рецепта компаса, оточений залізом?', 'Цукор', 'Світлокам''яний пил', 'Порох пломеня', 'Редстоуновий пил', 3, 'Чотири залізні злитки навколо редстоунового пилу дають компас, що вказує на точку появи світу.', 22, true),
  ('hopper-moves-items-between-containers', 'Який блок витягує предмети зі скрині, що стоїть над ним?', 'Спостерігач', 'Лійка', 'Діжка', 'Викидач', 1, 'Лійка забирає предмети з контейнера над собою й передає туди, куди дивиться її носик.', 23, true),
  ('smithing-table-upgrades-netherite', 'Де покращують діамантове спорядження до незеритового?', 'Ковадло', 'Домна', 'Стіл зачарування', 'Ковальський стіл', 3, 'Він поєднує діамантове спорядження, незеритовий злиток і шаблон незеритового покращення.', 24, true),
  ('smoker-cooks-food-faster', 'Який блок готує їжу вдвічі швидше за піч?', 'Багаття', 'Коптильня', 'Каменеріз', 'Домна', 1, 'Коптильня працює лише з їжею, зате готує її вдвічі швидше.', 25, true),
  ('campfire-calms-bees', 'Що поставити під вулик, щоб бджоли не злилися, коли ти береш мед?', 'Смолоскип', 'Дзвін', 'Багаття', 'Ліхтар', 2, 'Дим від багаття під вуликом заспокоює бджіл, тож вони не нападають, коли ти збираєш мед.', 26, true),
  ('composter-makes-bone-meal', 'Який блок перетворює зайве насіння й рослини на кісткове борошно?', 'Точило', 'Коптильня', 'Казан', 'Компостер', 3, 'Кожна рослина може підняти рівень, а заповнений компостер дає одне кісткове борошно.', 27, true),
  ('silk-touch-moves-bee-nest', 'Яке зачарування дає забрати бджолине гніздо разом із бджолами?', 'Удача', 'Ефективність', 'Незламність', 'Шовковий дотик', 3, 'Шовковий дотик дає гніздо як предмет разом із бджолами, а без нього бджолине гніздо нічого не дає.', 28, true),
  ('cat-scares-creepers', 'Якого вихованця бояться й уникають кріпери?', 'Вовк', 'Кіт', 'Аксолотль', 'Кінь', 1, 'Кріпери бояться котів та оцелотів, тому кіт біля бази відлякує їх.', 29, true),
  ('charged-creeper-lightning', 'Що перетворює звичайного кріпера на зарядженого?', 'Повний місяць', 'Удар блискавки', 'Вибухове зілля', 'Редстоун-сигнал', 1, 'Блискавка поруч із кріпером заряджає його, і вибух стає набагато сильнішим.', 30, true),
  ('smite-hurts-undead', 'Яке зачарування меча додає шкоди лише нежиті?', 'Відкидання', 'Грабунок', 'Небесна кара', 'Гострота', 2, 'Небесна кара посилює удари по нежиті, а Гострота — по всіх мобах.', 31, true),
  ('wither-skeleton-drops-skull', 'Скільки черепів візер-скелета треба, щоб викликати Візера?', '5', '4', '1', '3', 3, 'Візера будують із 4 блоків піску душ чи ґрунту душ і 3 черепів зверху.', 32, true),
  ('eye-of-ender-finds-stronghold', 'Про-режим: ти проходиш прогресію між вимірами або збираєш механізм, де важить точна умова сигналу, предмета чи структури; перед входом у Край треба не вгадувати координати, а вести маршрут предметом, що летить до твердині. Що кидають? На основі механіки Minecraft обери компонент, ресурс або правило прогресії, яке спрацює.', 'Предмет для телепортації без наведення', 'Пристрій для часу доби', 'Снаряд для підпалювання', 'Навігаційний предмет до порталу Краю', 3, 'Око Ендера летить у бік фортеці й допомагає знайти шлях до портал-кімнати. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 33, true),
  ('magma-block-pulls-down-bubbles', 'Про-режим: ти проходиш прогресію між вимірами або збираєш механізм, де важить точна умова сигналу, предмета чи структури; у водяному ліфті напрямок колони неправильний — бульбашки тягнуть униз. Який блок стоїть внизу? На основі механіки Minecraft обери компонент, ресурс або правило прогресії, яке спрацює.', 'Матеріал океанських споруд', 'Підводне джерело світла', 'Гарячий блок із Незеру', 'Пористий блок для підйому', 2, 'Магмовий блок створює низхідний бульбашковий стовп, а пісок душ штовхає вгору. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 34, true),
  ('observer-detects-updates', 'Про-режим: ти проходиш прогресію між вимірами або збираєш механізм, де важить точна умова сигналу, предмета чи структури; фермі потрібен короткий імпульс, коли перед компонентом змінюється блок або стан блока. Що ставлять? На основі механіки Minecraft обери компонент, ресурс або правило прогресії, яке спрацює.', 'Спостерігач', 'Компостер', 'Датчик денного світла', 'Дзвін', 0, 'Спостерігач найкраще відповідає описаній механіці редстоуну або вимірів. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 35, false),
  ('respawn-anchor-charged-glowstone', 'Про-режим: ти проходиш прогресію між вимірами або збираєш механізм, де важить точна умова сигналу, предмета чи структури; точку відродження в Незері треба зарядити витратним світним ресурсом перед використанням. Чим заряджають якір? На основі механіки Minecraft обери компонент, ресурс або правило прогресії, яке спрацює.', 'Редстоуновий пил', 'Світлокамінь', 'Кварц', 'Стрижень іфрита', 1, 'У прогресії між вимірами або редстоун-механіці ця умова є вирішальною. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 36, false),
  ('warped-forest-many-endermen', 'Про-режим: ти проходиш прогресію між вимірами або збираєш механізм, де важить точна умова сигналу, предмета чи структури; для перлин Краю в Незері обирають біом із великою кількістю ендерменів і відносно керованими ризиками. Який? На основі механіки Minecraft обери компонент, ресурс або правило прогресії, яке спрацює.', 'Біом із піском душ і скелетами', 'Синьо-зелений ліс Незеру', 'Червоний ліс із хоглінами', 'Вулканічний біом із базальтом', 1, 'У викривлених лісах багато ендерменів і менше небезпечних піглінів та хоглінів, ніж у деяких інших біомах Незеру. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 37, true),
  ('campfire-cooks-without-fuel', 'Який блок готує їжу без жодного палива?', 'Багаття', 'Піч', 'Верстак', 'Коптильня', 0, 'Запалене багаття безкоштовно готує до чотирьох страв, а печі й коптильні палять паливо.', 38, true),
  ('honey-bottle-clears-poison', 'Який предмет знімає отруєння без молока?', 'Печиво', 'Яблуко', 'Пляшка меду', 'Павуче око', 2, 'Мед знімає лише отруєння, тож корисні ефекти зілль залишаються.', 39, true),
  ('powder-snow-needs-leather-boots', 'Які чоботи дають змогу ходити по сипкому снігу, не провалюючись?', 'Діамантові чоботи', 'Кольчужні чоботи', 'Шкіряні чоботи', 'Залізні чоботи', 2, 'Лише шкіряні чоботи тримають тебе на сипкому снігу, в інших ти провалишся й замерзнеш.', 40, true),
  ('pumpkin-stops-enderman-stare', 'Що можна вдягнути на голову, щоб безпечно дивитися на ендерменів?', 'Вирізаний гарбуз', 'Панцир черепахи', 'Кольчужний шолом', 'Шкіряна шапка', 0, 'Вирізаний гарбуз ховає твій погляд від ендерменів, хоча закриває частину огляду.', 41, true),
  ('totem-of-undying-saves-once', 'Який рідкісний предмет може один раз урятувати від смерті?', 'Серце моря', 'Зірка Незеру', 'Золоте яблуко', 'Тотем безсмертя', 3, 'Тотем у руці витрачається, залишає тебе живим з половиною серця й дає ефекти лікування.', 42, true),
  ('aqua-affinity-speeds-underwater-mining', 'Про-режим: ти оптимізуєш торговий зал або фінальне спорядження й маєш врахувати професію, ресток, книгу, досвід або сумісність чарів; підводний видобуток повільний, тож шолому потрібне зачарування саме на швидкість копання у воді. Яке? На основі механіки Minecraft обери професію, станцію, ресурс або зачарування без плутанини.', 'Нескінченність', 'Невагомість', 'Рідність води', 'Гострота', 2, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 43, false),
  ('channeling-needs-thunderstorm', 'Про-режим: ти оптимізуєш торговий зал або фінальне спорядження й маєш врахувати професію, ресток, книгу, досвід або сумісність чарів; тризуб із Ченнелінгом не викликає блискавку будь-коли; потрібна конкретна погода. Яка? На основі механіки Minecraft обери професію, станцію, ресурс або зачарування без плутанини.', 'Будь-яка печера', 'Снігова буря', 'Гроза', 'Ясний схід сонця', 2, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 44, false),
  ('efficiency-speeds-mining', 'Про-режим: ти оптимізуєш торговий зал або фінальне спорядження й маєш врахувати професію, ресток, книгу, досвід або сумісність чарів; для маяка, шахти або масового копання інструмент має ламати блоки швидше без зміни дропу. Яке зачарування? На основі механіки Minecraft обери професію, станцію, ресурс або зачарування без плутанини.', 'Грабунок', 'Прокляття прив''язування', 'Ефективність', 'Шипи', 2, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 45, false),
  ('fortune-increases-ore-drops', 'Про-режим: ти оптимізуєш торговий зал або фінальне спорядження й маєш врахувати професію, ресток, книгу, досвід або сумісність чарів; при видобутку руд важливо збільшити кількість дропу, а не зберегти сам блок. Яке зачарування потрібне? На основі механіки Minecraft обери професію, станцію, ресурс або зачарування без плутанини.', 'Дихання', 'Поштовх', 'Удача', 'Відкидання', 2, 'Удача найкраще відповідає описаній механіці села або зачарувань. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 46, false),
  ('frost-walker-freezes-water', 'Про-режим: ти оптимізуєш торговий зал або фінальне спорядження й маєш врахувати професію, ресток, книгу, досвід або сумісність чарів; маршрут через воду треба проходити без човна, тимчасово створюючи лід під ногами. Яке зачарування чобіт це робить? На основі механіки Minecraft обери професію, станцію, ресурс або зачарування без плутанини.', 'Швидкість душ', 'Біг крадькома', 'Швидке заряджання', 'Льодохід', 3, 'Льодохід найкраще відповідає описаній механіці села або зачарувань. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 47, false),
  ('golden-apple-cures-zombie-villager', 'Про-режим: ти оптимізуєш торговий зал або фінальне спорядження й маєш врахувати професію, ресток, книгу, досвід або сумісність чарів; після накладання Слабкості зомбі-селянина треба завершити лікування спеціальною їжею. Якою? На основі механіки Minecraft обери професію, станцію, ресурс або зачарування без плутанини.', 'Золоте яблуко', 'Сяйні ягоди', 'Зачарована книга', 'Тотем безсмертя', 0, 'Золоте яблуко найкраще відповідає описаній механіці села або зачарувань. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 48, false),
  ('grindstone-removes-enchantments', 'Про-режим: ти оптимізуєш торговий зал або фінальне спорядження й маєш врахувати професію, ресток, книгу, досвід або сумісність чарів; треба зняти більшість чар із предмета й повернути трохи досвіду, не використовуючи ковадло. Яка станція? На основі механіки Minecraft обери професію, станцію, ресурс або зачарування без плутанини.', 'Станція для різання каменю', 'Потужне джерело ефектів', 'Станція для зняття чар', 'Станція для зілля', 2, 'Точило може прибрати більшість чар і повернути гравцеві трохи досвіду. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 49, true),
  ('infinity-still-needs-one-arrow', 'Про-режим: ти оптимізуєш торговий зал або фінальне спорядження й маєш врахувати професію, ресток, книгу, досвід або сумісність чарів; лук із Нескінченністю не стріляє з порожнього інвентаря. Що мінімально має залишатися? На основі механіки Minecraft обери професію, станцію, ресурс або зачарування без плутанини.', 'Вудка', 'Пляшка чарів', 'Щит', 'Хоча б одну стрілу', 3, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 50, false),
  ('looting-helps-mob-drops', 'Про-режим: ти оптимізуєш торговий зал або фінальне спорядження й маєш врахувати професію, ресток, книгу, досвід або сумісність чарів; меч налаштовують під фарм рідкісного дропу з мобів, а не під шкоду по блоках. Яке зачарування? На основі механіки Minecraft обери професію, станцію, ресурс або зачарування без плутанини.', 'Тягун', 'Грабунок', 'Полум''я', 'Протикання', 1, 'Грабунок найкраще відповідає описаній механіці села або зачарувань. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 51, false),
  ('mending-repairs-with-xp', 'Про-режим: ти оптимізуєш торговий зал або фінальне спорядження й маєш врахувати професію, ресток, книгу, досвід або сумісність чарів; спорядження має ремонтуватися від отриманого досвіду, забираючи XP до шкали рівня. Яке зачарування це робить? На основі механіки Minecraft обери професію, станцію, ресурс або зачарування без плутанини.', 'Ремонт через досвід', 'Шкода нападникам', 'Відкидання стрілою', 'Швидша робота під водою', 0, 'Лагодження цінне тим, що досвід автоматично ремонтує спорядження з цим зачаруванням. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 52, true),
  ('protection-reduces-damage', 'Про-режим: ти оптимізуєш торговий зал або фінальне спорядження й маєш врахувати професію, ресток, книгу, досвід або сумісність чарів; для універсального сету броні потрібне загальне зменшення вхідної шкоди, а не вузька протидія лише вогню чи вибухам. Яке зачарування? На основі механіки Minecraft обери професію, станцію, ресурс або зачарування без плутанини.', 'Приманка', 'Шовковий дотик', 'Рідність води', 'Захист', 3, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 53, false),
  ('silk-touch-drops-glass', 'Про-режим: ти оптимізуєш торговий зал або фінальне спорядження й маєш врахувати професію, ресток, книгу, досвід або сумісність чарів; треба забрати скло як блок і не втратити його при ламанні. Яке зачарування інструмента потрібне? На основі механіки Minecraft обери професію, станцію, ресурс або зачарування без плутанини.', 'Гострота', 'Шовковий дотик', 'Дихання', 'Грабунок', 1, 'Шовковий дотик найкраще відповідає описаній механіці села або зачарувань. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 54, false),
  ('thorns-damages-attacker', 'Про-режим: ти оптимізуєш торговий зал або фінальне спорядження й маєш врахувати професію, ресток, книгу, досвід або сумісність чарів; броня з Шипами має побічний ефект для того, хто б’є власника. Що може статися з нападником? На основі механіки Minecraft обери професію, станцію, ресурс або зачарування без плутанини.', 'З нього випадає смарагд', 'Це може повернути шкоду', 'Змінює професію', 'Заживає миттєво', 1, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 55, false),
  ('unbreaking-reduces-durability-loss', 'Про-режим: ти оптимізуєш торговий зал або фінальне спорядження й маєш врахувати професію, ресток, книгу, досвід або сумісність чарів; для довгої експедиції важливо, щоб інструмент рідше витрачав міцність при використанні. Яке зачарування? На основі механіки Minecraft обери професію, станцію, ресурс або зачарування без плутанини.', 'Глибинний бігун', 'Сила вогню', 'Незламність', 'Нищівне лезо', 2, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 56, false),
  ('weaponsmith-uses-grindstone', 'Про-режим: ти оптимізуєш торговий зал або фінальне спорядження й маєш врахувати професію, ресток, книгу, досвід або сумісність чарів; для потрібних торгів у селі ти ставиш точило, щоб отримати професію, пов’язану зі зброєю. Хто це? На основі механіки Minecraft обери професію, станцію, ресурс або зачарування без плутанини.', 'Селянин зілля', 'Селянин зброї', 'Селянин інструментів', 'Селянин броні', 1, 'Точило належить зброяру, який спеціалізується на мечах і сокирах. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 57, true),
  ('golden-apple-gives-absorption', 'Яка їжа дає додаткові сердечка поглинання?', 'Висушена ламінарія', 'Гарбузовий пиріг', 'Борщ', 'Золоте яблуко', 3, 'Золоте яблуко дає поглинання й регенерацію, корисно перед важким боєм.', 58, true),
  ('totem-must-be-held-in-hand', 'Де має бути тотем безсмертя, щоб урятувати тебе?', 'У слоті броні', 'В інвентарі', 'У скрині', 'У руці', 3, 'Тотем працює лише в основній чи другій руці, а не в рюкзаку.', 59, true),
  ('milk-removes-bad-omen', 'Який предмет знімає Погану прикмету до приходу в село?', 'Підозріла юшка', 'Пляшка меду', 'Золоте яблуко', 'Відро молока', 3, 'Молоко знімає Погану прикмету, тож ти зайдеш у село без набігу.', 60, true),
  ('bed-explodes-in-nether-survival', 'Що станеться, якщо спробувати спати в ліжку в Незері?', 'Ніч минає', 'Вибухає', 'Нічого не стається', 'Зберігається точка появи', 1, 'Ліжка вибухають у Незері та Енді, тож там використовуй якір відродження.', 61, true),
  ('zombie-breaks-door-on-hard', 'Який моб на складному рівні може виламати дерев''яні двері?', 'Ендермен', 'Кріпер', 'Зомбі', 'Скелет', 2, 'На складному рівні зомбі ламають дерев''яні двері, тож став залізні або закладай вхід.', 62, true),
  ('sleep-prevents-phantom-spawns', 'Після скількох ночей без сну можуть з''явитися фантоми?', '10', '1', '3', '5', 2, 'Фантоми можуть з''явитися, якщо ти три ігрові доби не спав і не помирав.', 63, true),
  ('respawn-anchor-sets-nether-spawn', 'Який блок дає змогу знову з''явитися в Незері після смерті?', 'Маяк', 'Якір відродження', 'Піч', 'Магнетит', 1, 'Кожен світлокамінь додає заряд, а кожне відродження біля якоря витрачає один.', 64, true),
  ('ender-pearl-teleports-player', 'Який кинутий предмет переносить тебе туди, де він упав?', 'Яйце', 'Перлина Енду', 'Сніжка', 'Тризубець', 1, 'Перлина Енду переносить тебе на місце падіння, але забирає трохи здоров''я.', 65, true),
  ('magma-block-pulls-downward', 'З якої найбільшої висоти в блоках можна впасти без шкоди?', '3', '2', '5', '8', 0, 'Падіння з 3 блоків безпечне, а з 4 і вище ти вже втрачаєш здоров''я.', 66, true),
  ('soul-sand-pushes-upward', 'Який блок під водою створює стовп бульбашок, що піднімає вгору?', 'Магматичний блок', 'Гравій', 'Пісок душ', 'Обсидіан', 2, 'Пісок душ створює стовп бульбашок угору, зручний для швидких водяних ліфтів.', 67, true),
  ('glass-pane-from-glass-blocks', 'Скільки шибок дають шість блоків скла?', '6', '8', '16', '12', 2, 'Шість блоків скла стають шістнадцятьма шибками, тож шибками вигідно засклювати великі вікна.', 68, true),
  ('blast-furnace-not-for-food', 'Який із цих блоків не може приготувати сиру їжу?', 'Коптильня', 'Піч', 'Домна', 'Багаття', 2, 'Домна переплавляє лише руду, сирий метал і металеве спорядження, тож їжу там не приготуєш.', 69, true),
  ('smoker-not-for-ores', 'Що з цього коптильня не зможе обробити?', 'Картопля', 'Сира тріска', 'Необроблене залізо', 'Сира яловичина', 2, 'Коптильня працює лише з їжею, тож необроблене залізо треба нести в піч або домну.', 70, true),
  ('cartography-table-expands-maps-crafting', 'Що додають до мапи в картографічному столі, щоб віддалити її?', 'Компас', 'Шибка', 'Чорнильний мішок', 'Папір', 3, 'Один аркуш паперу віддаляє мапу на рівень, і вона показує більшу територію з меншою деталізацією.', 71, true),
  ('brewing-stand-makes-potions-crafting', 'Який предмет разом із трьома кругляками дає варильну стійку?', 'Стрижень пломеня', 'Залізний злиток', 'Порох пломеня', 'Палиця', 0, 'Стрижень пломеня стає опорою стійки, тож перед зіллєваренням треба перемогти пломеня.', 72, true),
  ('stonecutter-chooses-stone-shapes', 'Скільки кам''яних плит дає каменеріз з одного блока каменю?', '2', '1', '8', '3', 0, 'Один блок ділиться на дві плити — як і на верстаку, але без потреби класти три блоки одразу.', 73, true),
  ('anvil-can-break-from-use', 'Яка робоча станція пошкоджується від використання й зрештою ламається?', 'Точило', 'Ковадло', 'Картографічний стіл', 'Ковальський стіл', 1, 'Кожне використання має 12% шансу пошкодити ковадло, а після третьої стадії воно ламається.', 74, true),
  ('loom-simplifies-banner-patterns', 'Що, крім дощок, потрібно, щоб скрафтити ткацький верстат?', 'Вовна', 'Залізний злиток', 'Нитка', 'Шкіра', 2, 'Дві нитки над двома дошками дають ткацький верстат.', 75, true),
  ('obsidian-needed-for-enchanting-table', 'Який блок, крім діамантів і книги, потрібен для столу зачарування?', 'Базальт', 'Обсидіан', 'Блок вугілля', 'Глибосланець', 1, 'Чотири обсидіани, два діаманти й книга дають стіл, тож спершу потрібне діамантове кайло.', 76, true),
  ('redstone-needed-for-clock', 'Який предмет оточує редстоуновий пил у рецепті годинника?', 'Залізний злиток', 'Смарагд', 'Золотий злиток', 'Мідний злиток', 2, 'Чотири золоті злитки навколо редстоуну дають годинник, а залізні в такій самій формі — компас.', 77, true),
  ('obsidian-needs-diamond-pickaxe', 'Про-режим: ти проектуєш механізм або складну базу й маєш вибрати блок за точною фізикою, дропом або редстоун-поведінкою; портал будується з міцного блоку, але щоб забрати його як дроп, потрібен правильний рівень інструмента. Який мінімум? На основі механіки Minecraft обери блок або будівельну поведінку, яка спрацює в грі.', 'Ножиці', 'Дерев''яне кайло', 'Діамантове кайло', 'Кам''яне кайло', 2, 'Поведінка блока в світі збігається з описаною будівельною ситуацією. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 78, false),
  ('deepslate-mines-slower-than-stone', 'Про-режим: ти проектуєш механізм або складну базу й маєш вибрати блок за точною фізикою, дропом або редстоун-поведінкою; у глибоких шарах темп шахти падає, бо один кам’яний варіант ламається повільніше за звичайний камінь. Який? На основі механіки Minecraft обери блок або будівельну поведінку, яка спрацює в грі.', 'Пісок', 'Вовна', 'Глибосланець', 'Ґрунт', 2, 'Глибосланець — саме той блок чи предмет, що підходить до описаної властивости або будівельної ситуації. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 79, false),
  ('glowstone-drops-dust-when-broken', 'Про-режим: ти проектуєш механізм або складну базу й маєш вибрати блок за точною фізикою, дропом або редстоун-поведінкою; у Незері світний блок без Шовкового дотику зазвичай дає пил, а не сам блок. Який? На основі механіки Minecraft обери блок або будівельну поведінку, яка спрацює в грі.', 'Світлокамінь', 'Базальт', 'Пісок душ', 'Незерак', 0, 'Світлокамінь — саме той блок чи предмет, що підходить до описаної властивости або будівельної ситуації. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 80, false),
  ('nether-quartz-ore-drops-quartz', 'Про-режим: ти проектуєш механізм або складну базу й маєш вибрати блок за точною фізикою, дропом або редстоун-поведінкою; для компараторів і білого декору потрібен ресурс із руди з білими вкрапленнями у Незері. Яка руда? На основі механіки Minecraft обери блок або будівельну поведінку, яка спрацює в грі.', 'Незерська кварцова руда', 'Залізна руда', 'Вугільна руда', 'Смарагдова руда', 0, 'Незерська кварцова руда найкраще пасує до описаної поведінки блока або будівельного використання. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 81, false),
  ('copper-oxidizes-green-over-time', 'Про-режим: ти проектуєш механізм або складну базу й маєш вибрати блок за точною фізикою, дропом або редстоун-поведінкою; для декоративних білдів треба врахувати метал, який із часом зеленіє на повітрі. Який матеріал? На основі механіки Minecraft обери блок або будівельну поведінку, яка спрацює в грі.', 'Мідь', 'Залізо', 'Кварц', 'Золото', 0, 'Мідні блоки з часом окиснюються й поступово зеленіють. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 82, false),
  ('scaffolding-extends-outward-with-support', 'Про-режим: ти проектуєш механізм або складну базу й маєш вибрати блок за точною фізикою, дропом або редстоун-поведінкою; тимчасова платформа може виступати вбік лише до певної межі без нижньої опори. Який блок має це правило? На основі механіки Minecraft обери блок або будівельну поведінку, яка спрацює в грі.', 'Шибка', 'Паркан', 'Підмостки', 'Драбина', 2, 'Поведінка блока в світі збігається з описаною будівельною ситуацією. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 83, false),
  ('trapdoor-makes-ladder-hatch', 'Про-режим: ти проектуєш механізм або складну базу й маєш вибрати блок за точною фізикою, дропом або редстоун-поведінкою; вертикальний лаз над драбиною треба закривати тонким шарнірним блоком у стелі. Що ставлять? На основі механіки Minecraft обери блок або будівельну поведінку, яка спрацює в грі.', 'Люк', 'Килим', 'Рейки', 'Дзвін', 0, 'Люк — саме той блок чи предмет, що підходить до описаної властивости або будівельної ситуації. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 84, false),
  ('fence-connects-into-lines', 'Про-режим: ти проектуєш механізм або складну базу й маєш вибрати блок за точною фізикою, дропом або редстоун-поведінкою; для загонів потрібен блок, що сам з’єднується з сусідніми такими ж блоками в довгу лінію. Що це? На основі механіки Minecraft обери блок або будівельну поведінку, яка спрацює в грі.', 'Паркан', 'Ліхтар', 'Скло', 'Смолоскип', 0, 'Поведінка блока в світі збігається з описаною будівельною ситуацією. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 85, false),
  ('piston-cannot-push-obsidian', 'Про-режим: ти проектуєш механізм або складну базу й маєш вибрати блок за точною фізикою, дропом або редстоун-поведінкою; у поршневій схемі є блок, який звичайний поршень не зрушить навіть із сигналом. Який? На основі механіки Minecraft обери блок або будівельну поведінку, яка спрацює в грі.', 'Вовна', 'Обсидіан', 'Пісок', 'Ґрунт', 1, 'Поведінка блока в світі збігається з описаною будівельною ситуацією. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 86, false),
  ('slime-block-drags-neighboring-blocks', 'Про-режим: ти проектуєш механізм або складну базу й маєш вибрати блок за точною фізикою, дропом або редстоун-поведінкою; літаючий механізм має тягнути сусідні блоки разом із рухом поршня. Який липкий блок це робить? На основі механіки Minecraft обери блок або будівельну поведінку, яка спрацює в грі.', 'Лід', 'Вугільний блок', 'Скло', 'Слизовий блок', 3, 'Слизовий блок найкраще пасує до описаної поведінки блока або будівельного використання. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 87, false),
  ('tropical-fish-breeds-axolotls', 'Чим годують аксолотлів, щоб вони розмножилися?', 'Відро з тріскою', 'Відро зі скелезубом', 'Відро з тропічною рибою', 'Відро з лососем', 2, 'Аксолотлі беруть лише живу тропічну рибу у відрі, а відро з водою повертається тобі.', 88, true),
  ('slimeball-breeds-frogs', 'Яким предметом розводять жаб?', 'Павуче око', 'Слизова кулька', 'Ламінарія', 'Магматичний крем', 1, 'У природі жаби їдять малих слизнів, тож слизові кульки змушують їх розмножуватися й класти ікру.', 89, true),
  ('beetroot-crafts-into-soup', 'Скільки буряків потрібно, щоб скрафтити один борщ?', '8', '6', '3', '4', 1, 'Для борщу потрібно 6 буряків і миска — чимало врожаю на одну страву.', 90, true),
  ('striders-breed-with-warped-fungus', 'Яким предметом розводять блукачів?', 'Багряний гриб', 'Червоний гриб', 'Незерський наріст', 'Химерний гриб', 3, 'Блукачі люблять химерні гриби: вони їх розводять, а на вудці дають керувати блукачем на лаві.', 91, true),
  ('turtles-breed-with-seagrass', 'Якою рослиною годують черепах, щоб вони розмножилися?', 'Латаття', 'Цукрова тростина', 'Ламінарія', 'Морська трава', 3, 'Черепахи їдять морську траву; нагодована черепаха пливе до рідного пляжу й відкладає яйця в пісок.', 92, true),
  ('foxes-breed-with-sweet-berries', 'Якою їжею розводять лисиць?', 'Солодкі ягоди', 'Скибка кавуна', 'Буряк', 'Яблуко', 0, 'Лисиці люблять ягоди: і солодкі, і світні ягоди змушують їх розмножуватися.', 93, true),
  ('potato-smelts-into-baked-potato', 'Яка з цих культур стає ситнішою їжею після приготування в печі?', 'Морква', 'Картопля', 'Гарбуз', 'Буряк', 1, 'Переплавлена картопля стає запеченою картоплею, яка вгамовує голод набагато краще за сиру.', 94, true),
  ('flower-turns-stew-suspicious', 'Що, крім миски й двох грибів, потрібно для підозрілої юшки?', 'Павуче око', 'Квітка', 'Цукор', 'Пшениця', 1, 'Квітка визначає прихований ефект юшки: наприклад, кульбаба відновлює ситість.', 95, true),
  ('cake-uses-three-milk-buckets', 'Скільки відер молока потрібно для одного торта?', '1', '4', '2', '3', 3, 'Торт займає весь верхній ряд відрами молока, а порожні відра повертаються в інвентар.', 96, true),
  ('nether-wart-grows-on-soul-sand', 'На який блок обов''язково садять незерський наріст?', 'Рілля', 'Незерак', 'Ґрунт душ', 'Пісок душ', 3, 'Незерський наріст росте лише на піску душ, тож зіллявари несуть пісок душ додому для ферми.', 97, true),
  ('pumpkin-needs-empty-space-beside-stem', 'Який мінімальний рівень світла потрібен посівам, щоб рости?', '9', '15', '4', '12', 0, 'Посівам потрібне світло рівня 9 або більше, тож підземна ферма потребує смолоскипів чи ламп.', 98, true),
  ('cactus-breaks-when-side-touches-block', 'Яка рослина ламається, якщо поруч із нею поставити твердий блок?', 'Пшениця', 'Бамбук', 'Цукрова тростина', 'Кактус', 3, 'Кактус випадає предметом, коли збоку стоїть твердий блок, — на цьому працюють кактусові ферми.', 99, true),
  ('tamed-wolf-attacks-hostiles', 'Якого ворожого моба приручений вовк ніколи не атакує?', 'Відьма', 'Скелет', 'Кріпер', 'Зомбі', 2, 'Приручені вовки б’ються з більшістю мобів, але кріперів не чіпають.', 100, true),
  ('piglin-barters-with-gold', 'Який моб Незеру обмінює золоті злитки на випадкові предмети?', 'Піґлін', 'Візер-скелет', 'Зомбований піґлін', 'Гоґлін', 0, 'Піґлін бере кинутий золотий злиток, розглядає його й кидає у відповідь випадковий предмет.', 101, true),
  ('zombified-piglin-angers-group', 'Який нейтральний моб Незеру кидає в атаку всю групу, якщо вдарити одного?', 'Ендермен', 'Магмокуб', 'Зомбований піґлін', 'Блукач', 2, 'Удар по одному зомбованому піґліну злить усіх поруч, і починається великий бій.', 102, true),
  ('bees-swarm-after-nest-broken', 'Який моб, танцюючи біля програвача, розмножується, якщо дати йому аметистовий уламок?', 'Бджола', 'Збирик', 'Бісик', 'Папуга', 1, 'Збирик, що танцює під музику, від аметистового уламка створює свою копію, а потім 5 хвилин відпочиває.', 103, true),
  ('iron-golem-hits-hard-if-provoked', 'Скільки залізних блоків треба, щоб збудувати залізного ґолема?', '6', '3', '5', '4', 3, 'Постав 4 залізні блоки літерою Т і вирізаний гарбуз зверху — з’явиться ґолем.', 104, true),
  ('evoker-summons-vexes', 'Який ілагер чаклує й викликає летючих бісиків?', 'Відьма', 'Заклинач', 'Розбійник', 'Поборник', 1, 'Заклиначі викликають бісиків і ікла з землі, а після перемоги лишають тотем безсмертя.', 105, true),
  ('guardian-fires-laser-beam', 'Який моб океанічного монумента атакує лазерним променем?', 'Потопельник', 'Вартовий', 'Кальмар', 'Скелезуб', 1, 'Вартові наводять промінь, який заряджається, а тоді завдає шкоди навіть під водою.', 106, true),
  ('endermite-can-spawn-from-pearl', 'Який крихітний ворожий моб може з’явитися, коли падає кинута перлина Енду?', 'Лусківниця', 'Печерний павук', 'Бісик', 'Ендермайт', 3, 'Кожна кинута перлина Енду має 5% шанс створити ендермайта.', 107, true),
  ('bane-of-arthropods-vs-spiders', 'Яке зачарування завдає більше шкоди павукам, бджолам і лусківницям?', 'Загибель членистоногих', 'Сила вогню', 'Гострота', 'Небесна кара', 0, 'Загибель членистоногих сильніше б’є комахоподібних мобів і ще й сповільнює їх.', 108, true),
  ('totem-works-from-hand-slot', 'Яка зброя б''є сильніше, що з більшої висоти ти падаєш перед ударом?', 'Сокира', 'Тризубець', 'Булава', 'Арбалет', 2, 'Булава додає шкоди залежно від висоти падіння, тому нею б''ють після великого стрибка.', 109, true),
  ('strength-potion-boosts-melee', 'Яке зілля робить твої удари в ближньому бою сильнішими?', 'Зілля невидимості', 'Зілля стрибучости', 'Зілля повільного падіння', 'Зілля сили', 3, 'Сила додає шкоди кожному удару зблизька, що дуже допомагає в боях із босами.', 110, true),
  ('twelve-eyes-activate-portal', 'Про-режим: ти проходиш прогресію між вимірами або збираєш механізм, де важить точна умова сигналу, предмета чи структури; якщо в кімнаті порталу всі рамки порожні, треба мати повний комплект очей для активації. Скільки? На основі механіки Minecraft обери компонент, ресурс або правило прогресії, яке спрацює.', 'Вісім', 'Дванадцять', 'Шістнадцять', 'Десять', 1, 'Щоб активувати портал Енду, потрібно заповнити дванадцять рамок очима Ендера. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 111, false),
  ('chorus-fruit-teleports-randomly', 'Про-режим: ти проходиш прогресію між вимірами або збираєш механізм, де важить точна умова сигналу, предмета чи структури; у Краї є їжа, що може врятувати або зіпсувати позицію випадковою телепортацією. Що це? На основі механіки Minecraft обери компонент, ресурс або правило прогресії, яке спрацює.', 'Фрукт хорусу', 'Золота морква', 'Сяйні ягоди', 'Печиво', 0, 'У прогресії між вимірами або редстоун-механіці ця умова є вирішальною. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 112, false),
  ('dragon-breath-caught-in-bottle', 'Про-режим: ти проходиш прогресію між вимірами або збираєш механізм, де важить точна умова сигналу, предмета чи структури; для осідаючих зіль треба зібрати ресурс прямо з хмари атаки дракона скляною пляшкою. Що збирають? На основі механіки Minecraft обери компонент, ресурс або правило прогресії, яке спрацює.', 'Зілля зцілення', 'Пляшка меду', 'Дихання дракона', 'Пляшка чарів', 2, 'Дихання дракона збирають у скляну пляшку з його фіолетової хмари атаки. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 113, false),
  ('elytra-found-in-end-ship', 'Про-режим: ти проходиш прогресію між вимірами або збираєш механізм, де важить точна умова сигналу, предмета чи структури; після пошуку міст Енду головна нагорода лежить на кораблі й відкриває планерування. Що це? На основі механіки Minecraft обери компонент, ресурс або правило прогресії, яке спрацює.', 'Щит', 'Тризубець', 'Тотем безсмертя', 'Елітри', 3, 'Елітри найкраще відповідає описаній механіці редстоуну або вимірів. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 114, false),
  ('crying-obsidian-crafts-anchor', 'Про-режим: ти проходиш прогресію між вимірами або збираєш механізм, де важить точна умова сигналу, предмета чи структури; для якоря відродження потрібен фіолетовий варіант міцного портального блока. Який? На основі механіки Minecraft обери компонент, ресурс або правило прогресії, яке спрацює.', 'Плакучий обсидіан', 'Незерак', 'Гладкий камінь', 'Камінь Енду', 0, 'Плакучий обсидіан найкраще відповідає описаній механіці редстоуну або вимірів. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 115, false),
  ('warped-fungus-scares-hoglins', 'Про-режим: ти проходиш прогресію між вимірами або збираєш механізм, де важить точна умова сигналу, предмета чи структури; щоб зробити табір у Незері безпечнішим від гоглінів, використовують гриб, якого вони уникають. Який? На основі механіки Minecraft обери компонент, ресурс або правило прогресії, яке спрацює.', 'Багряний гриб', 'Світлолишайник', 'Червоний гриб', 'Химерний гриб', 3, 'У прогресії між вимірами або редстоун-механіці ця умова є вирішальною. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 116, false),
  ('blue-ice-makes-fast-boat-road', 'Про-режим: ти проходиш прогресію між вимірами або збираєш механізм, де важить точна умова сигналу, предмета чи структури; для швидкісних човнових тунелів у Незері використовують найслизькіший льодовий блок. Який? На основі механіки Minecraft обери компонент, ресурс або правило прогресії, яке спрацює.', 'Кругляк', 'Пісок', 'Синій лід', 'Вовна', 2, 'У прогресії між вимірами або редстоун-механіці ця умова є вирішальною. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 117, false),
  ('repeater-adds-redstone-delay', 'Про-режим: ти проходиш прогресію між вимірами або збираєш механізм, де важить точна умова сигналу, предмета чи структури; у схемі треба не просто провести сигнал, а додати контрольовану затримку імпульсу. Який компонент? На основі механіки Minecraft обери компонент, ресурс або правило прогресії, яке спрацює.', 'Дзвін', 'Повторювач', 'Кафедра', 'Компаратор', 1, 'Редстоуновий повторювач може не лише підсилювати сигнал, а й додавати затримку. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 118, false),
  ('target-block-rewards-accurate-hit', 'Про-режим: ти проходиш прогресію між вимірами або збираєш механізм, де важить точна умова сигналу, предмета чи структури; стрілецький механізм має видавати сильніший редстоун-сигнал за точніше влучання в центр. Який блок? На основі механіки Minecraft обери компонент, ресурс або правило прогресії, яке спрацює.', 'Поршень', 'Мішень', 'Кнопка', 'Натискна плита', 1, 'Мішень найкраще відповідає описаній механіці редстоуну або вимірів. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 119, false),
  ('daylight-sensor-reads-sky-light', 'Про-режим: ти проходиш прогресію між вимірами або збираєш механізм, де важить точна умова сигналу, предмета чи структури; автоматичне освітлення має реагувати на небо й час доби без ручного перемикача. Який сенсор? На основі механіки Minecraft обери компонент, ресурс або правило прогресії, яке спрацює.', 'Гак для розтяжки', 'Каменеріз', 'Спостерігач', 'Датчик денного світла', 3, 'Датчик денного світла зчитує рівень світла неба й може керувати денними або нічними схемами. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 120, false)
) as v(content_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, sort_order, is_active)
where pack.slug = 'minecraft-uk-hard'
on conflict (pack_id, content_id) do update set
  prompt = excluded.prompt,
  option_a = excluded.option_a,
  option_b = excluded.option_b,
  option_c = excluded.option_c,
  option_d = excluded.option_d,
  correct_option = excluded.correct_option,
  explanation = excluded.explanation,
  sort_order = excluded.sort_order,
  is_active = excluded.is_active;

insert into public.question_packs (category_id, locale, age_band, difficulty, title, slug, is_active)
select id, 'en', '8-12', 'easy', 'MineMind en easy', 'minecraft-en-easy', true
from public.quiz_categories
where slug = 'minecraft'
on conflict (slug) do update set is_active = true, title = excluded.title;

insert into public.questions (pack_id, content_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, sort_order, is_active)
select pack.id, v.content_id, v.prompt, v.option_a, v.option_b, v.option_c, v.option_d, v.correct_option, v.explanation, v.sort_order, v.is_active
from public.question_packs pack
cross join (values
  ('badlands-has-terracotta', 'Terracotta hills are a classic sign of which biome?', 'Swamp', 'Plains', 'Badlands', 'Snowy Plains', 2, 'Badlands are well known for layered terracotta and mesa-like terrain.', 1, false),
  ('bamboo-jungle-has-bamboo', 'A biome filled with bamboo is most likely which one?', 'Bamboo Jungle', 'Frozen Ocean', 'Deep Dark', 'Plains', 0, 'Bamboo jungles are a jungle variant packed with bamboo.', 2, false),
  ('beach-is-sandy-shore', 'What biome usually forms a sandy border beside an ocean?', 'Mesa', 'Beach', 'Meadow', 'River', 1, 'Beaches commonly appear as sandy shores next to oceans and other large water edges.', 3, false),
  ('cherry-grove-has-pink-trees', 'Which biome stands out because of pink cherry trees?', 'Nether Wastes', 'Swamp', 'Cherry Grove', 'Stony Shore', 2, 'Cherry groves are known for their pink blossom trees.', 4, false),
  ('desert-has-no-rain', 'In which hot biome does rain not fall?', 'Plains', 'River', 'Forest', 'Desert', 3, 'Deserts stay dry, so players do not see normal rain there.', 5, true),
  ('jungle-has-vines', 'Where would a player find tall trees and lots of vines?', 'Desert', 'Frozen Ocean', 'Jungle', 'Mushroom Fields', 2, 'Jungles are packed with tall trees, dense leaves, and many vines.', 6, false),
  ('mushroom-fields-has-giant-mushrooms', 'Which biome is known for giant mushrooms instead of ordinary trees?', 'Snowy Plains', 'Mushroom Fields', 'Savanna', 'Bamboo Jungle', 1, 'Mushroom fields are rare biomes filled with giant mushrooms and mycelium.', 7, false),
  ('ocean-mostly-water', 'If a biome is mostly open water, which biome is it likely to be?', 'Savanna', 'Ocean', 'Taiga', 'Badlands', 1, 'Oceans are large water biomes that dominate the surrounding area with water.', 8, false),
  ('plains-open-grassland', 'A player wanting broad open grassland should look in which biome?', 'Deep Dark', 'Basalt Deltas', 'Cherry Grove', 'Plains', 3, 'Plains biomes are open and grassy, making them easy to build in.', 9, false),
  ('river-cuts-through-land', 'Which biome often appears as a winding water path through the land?', 'River', 'Grove', 'Desert', 'Mushroom Fields', 0, 'Rivers form long water channels that pass through many other overworld areas.', 10, false),
  ('savanna-has-acacia-trees', 'Where would a player expect to find acacia trees most often?', 'Savanna', 'Dark Forest', 'Frozen River', 'Mushroom Fields', 0, 'Acacia trees are closely associated with savanna biomes.', 11, false),
  ('snowy-plains-has-snow', 'Which biome would usually be covered in snow?', 'Snowy Plains', 'Mangrove Swamp', 'Jungle', 'Desert', 0, 'Snowy plains are cold overworld biomes with snow cover.', 12, false),
  ('swamp-has-lily-pads', 'Which biome is famous for shallow water and many lily pads?', 'Badlands', 'Swamp', 'Savanna', 'Snowy Plains', 1, 'Swamps are known for murky water, lily pads, and wet terrain.', 13, false),
  ('taiga-has-spruce', 'What kind of tree is especially common in a taiga biome?', 'Acacia', 'Mangrove', 'Spruce', 'Cherry', 2, 'Taiga biomes are closely associated with spruce trees.', 14, false),
  ('village-has-villagers', 'Which structure often has villagers, beds, and crop fields?', 'Shipwreck', 'Village', 'Ruined Portal', 'Mineshaft', 1, 'Villages are helpful early finds because they usually bring shelter, food, and trading.', 15, true),
  ('cobblestone-from-stone', 'When stone is mined with a pickaxe, what block does it usually drop?', 'Bricks', 'Gravel', 'Clay', 'Cobblestone', 3, 'Regular stone usually drops cobblestone unless special conditions like Silk Touch are involved.', 16, false),
  ('glass-is-see-through', 'Which block is easy to see through and great for windows?', 'Cobblestone', 'Terracotta', 'Glass', 'Wool', 2, 'Glass lets light in and helps you see outside while keeping your base closed off.', 17, true),
  ('obsidian-from-water-and-lava', 'What block forms when water touches a lava source block?', 'Clay', 'Obsidian', 'Basalt', 'Bricks', 1, 'A lava source block becomes obsidian when water flows onto it.', 18, true),
  ('planks-build-starter-house', 'What block do many players craft from logs for a starter house?', 'Wooden Planks', 'Wool Carpet', 'Glass Pane', 'Redstone Dust', 0, 'Wooden planks are a common early building material because they come from logs and work in many recipes.', 19, false),
  ('sand-falls-with-gravity', 'Which block falls down if there is no block under it?', 'Oak Planks', 'Bookshelf', 'Stone Bricks', 'Sand', 3, 'Sand is a gravity block, so it drops when the block below it disappears.', 20, true),
  ('coal-fuels-furnace', 'Which item is the most common fuel for a furnace?', 'Sand', 'Coal', 'Cobblestone', 'String', 1, 'One piece of coal burns long enough to smelt 8 items, so it is the go-to furnace fuel.', 21, true),
  ('crafting-table-basics', 'Which block gives you a 3×3 grid for making tools and items?', 'Chest', 'Crafting Table', 'Furnace', 'Bed', 1, 'Your inventory only has a 2×2 grid, so bigger recipes like tools need a crafting table.', 22, true),
  ('furnace-smelts-raw-iron', 'Which block turns raw iron into iron ingots when you add fuel?', 'Barrel', 'Furnace', 'Composter', 'Anvil', 1, 'A furnace burns fuel to smelt ores, so raw iron comes out as ingots.', 23, true),
  ('planks-from-logs', 'How many iron ingots does it take to craft a block of iron?', '6', '9', '4', '8', 1, 'Nine ingots fill the whole 3×3 grid, and the block can be turned back into nine ingots.', 24, true),
  ('sticks-from-planks', 'Which item made from planks is the handle in most tool recipes?', 'Ladder', 'Button', 'Bowl', 'Stick', 3, 'Two planks stacked make four sticks, and tools, torches and signs all need them.', 25, true),
  ('pickaxe-mines-stone', 'Which tool do you need for mined stone to drop anything?', 'Axe', 'Shovel', 'Pickaxe', 'Hoe', 2, 'Stone mined by hand or with any other tool drops nothing, so a pickaxe is required.', 26, true),
  ('carrots-breed-pigs', 'Which food can you use to breed pigs?', 'Wheat', 'Carrot', 'Kelp', 'Red Mushroom', 1, 'Pigs love root crops: carrots, potatoes and beetroots all make them breed, but wheat does not.', 27, true),
  ('chickens-lay-eggs', 'What does a chicken drop by itself every few minutes?', 'Feather', 'Egg', 'Leather', 'Wheat Seeds', 1, 'Chickens lay an egg every 5–10 minutes; feathers only drop when a chicken is killed.', 28, true),
  ('cow-drops-leather', 'Which animal can drop leather?', 'Cow', 'Pig', 'Sheep', 'Chicken', 0, 'Cows drop leather and raw beef, so a cow farm gives you both food and leather for books and armor.', 29, true),
  ('sheep-give-wool', 'Which animal can you shear to get wool?', 'Goat', 'Cow', 'Pig', 'Sheep', 3, 'Sheared sheep regrow their wool after eating grass, so they give wool again and again.', 30, true),
  ('wheat-grows-from-seeds', 'Breaking grass can drop seeds. Which crop do they grow into?', 'Carrot', 'Cactus', 'Sugar Cane', 'Wheat', 3, 'Grass drops wheat seeds, which is why wheat is usually the very first crop a new player plants.', 31, true),
  ('bone-meal-speeds-growth', 'Which item makes crops grow faster when you use it on them?', 'Paper', 'Bone Meal', 'Gunpowder', 'Sugar', 1, 'Bone meal pushes a crop forward one or more growth stages at once, so you don''t have to wait.', 32, true),
  ('bucket-collects-cow-milk', 'What do you use on a cow to collect milk?', 'Glass Bottle', 'Bowl', 'Bucket', 'Shears', 2, 'Milk is a liquid like water, so it is carried in a bucket; a milk bucket also removes potion effects.', 33, true),
  ('hoe-makes-farmland', 'Which tool turns dirt into farmland?', 'Pickaxe', 'Hoe', 'Shears', 'Shovel', 1, 'Seeds can only be planted on farmland, so tilling dirt with a hoe is the first step of any farm.', 34, true),
  ('creeper-explodes', 'Which hostile mob hisses right before it explodes?', 'Creeper', 'Zombie', 'Skeleton', 'Spider', 0, 'Creepers sneak up silently, hiss for a moment and then blow up, damaging players and blocks.', 35, true),
  ('large-slime-splits', 'Which green bouncing mob splits into smaller copies when defeated?', 'Slime', 'Witch', 'Creeper', 'Enderman', 0, 'A big slime breaks into several smaller slimes, and the medium ones split again.', 36, true),
  ('skeleton-uses-bow', 'Which common hostile mob shoots arrows at you with a bow?', 'Creeper', 'Skeleton', 'Zombie', 'Slime', 1, 'Skeletons attack from range, so a shield or cover helps a lot against them.', 37, true),
  ('spider-climbs-walls', 'Which hostile mob can climb straight up walls?', 'Spider', 'Enderman', 'Creeper', 'Zombie', 0, 'Spiders climb vertical surfaces, so a plain wall won''t keep them out of your base.', 38, true),
  ('zombies-burn-in-day', 'Which of these mobs catches fire in direct sunlight?', 'Spider', 'Zombie', 'Creeper', 'Witch', 1, 'Zombies burn in daylight unless they stand in shade or water or wear a helmet.', 39, true),
  ('button-short-redstone-pulse', 'What small input block usually sends only a short redstone pulse when pressed?', 'Bookshelf', 'Furnace', 'Button', 'Chest', 2, 'Buttons are temporary redstone inputs that produce a short signal.', 40, false),
  ('flint-and-steel-lights-portal', 'What tool is most commonly used to light a Nether portal?', 'Flint and Steel', 'Shears', 'Compass', 'Spyglass', 0, 'Flint and steel is the standard tool for igniting a Nether portal frame.', 41, false),
  ('nether-portal-needs-obsidian', 'Which block is commonly used to build a Nether portal frame?', 'Stone', 'Sandstone', 'Obsidian', 'Copper Block', 2, 'Most Nether portals are built from obsidian because it can hold the portal frame.', 42, true),
  ('redstone-dust-carries-power', 'What dust carries redstone power between components?', 'Gunpowder', 'Sugar', 'Redstone Dust', 'Glowstone Dust', 2, 'Redstone dust links switches and machines together so a circuit can work.', 43, true),
  ('soul-sand-slows-movement', 'Which block slows movement when a player walks across it?', 'Smooth Stone', 'Packed Ice', 'Coal Ore', 'Soul Sand', 3, 'Soul sand slows movement and has special interactions with bubble columns.', 44, false),
  ('bed-sets-respawn', 'Which item lets you sleep and set your respawn point?', 'Boat', 'Chest', 'Bed', 'Banner', 2, 'Sleeping in a bed skips the night and sets your respawn point next to it.', 45, true),
  ('cooked-food-better-hunger', 'Which of these foods restores the most hunger?', 'Melon Slice', 'Cooked Porkchop', 'Raw Porkchop', 'Apple', 1, 'Cooked porkchop restores 8 hunger points, far more than raw meat, an apple or melon.', 46, true),
  ('eating-refills-hunger', 'Which bar fills up when you eat food?', 'Air Bar', 'Armor Bar', 'Experience Bar', 'Hunger Bar', 3, 'Food refills the hunger bar, and a full bar lets you sprint and regenerate health.', 47, true),
  ('shelter-before-first-night', 'What should you build before your first night to stay safe?', 'Nether Portal', 'Shelter', 'Beacon', 'Enchanting Table', 1, 'Hostile mobs spawn in the dark, so a simple closed shelter keeps you safe on night one.', 48, true),
  ('torch-lights-caves', 'What do players place to light up dark caves?', 'Door', 'Sign', 'Torch', 'Chest', 2, 'Torches give off light, so you can see in caves and fewer monsters spawn nearby.', 49, true),
  ('armorer-uses-blast-furnace', 'Which job block is used by an armorer villager?', 'Blast Furnace', 'Cartography Table', 'Lectern', 'Brewing Stand', 0, 'Armorers use blast furnaces as their profession block.', 50, false),
  ('barrel-makes-fisherman', 'Which workstation turns a villager into a fisherman?', 'Anvil', 'Stonecutter', 'Composter', 'Barrel', 3, 'Fishermen use barrels as their profession block.', 51, false),
  ('bookshelves-boost-enchanting', 'What nearby block helps an enchanting table offer stronger enchantments?', 'Barrel', 'Bookshelf', 'Lantern', 'Target Block', 1, 'Bookshelves around an enchanting table increase the strength of enchantment options.', 52, false),
  ('cartographer-uses-cartography-table', 'Cartographers work at which job block?', 'Fletching Table', 'Blast Furnace', 'Composter', 'Cartography Table', 3, 'Cartography tables belong to cartographers.', 53, false),
  ('cauldron-makes-leatherworker', 'Which block helps a villager become a leatherworker?', 'Loom', 'Smoker', 'Cauldron', 'Barrel', 2, 'Leatherworkers use cauldrons as their workstation.', 54, false),
  ('composter-makes-farmer', 'Which workstation block gives a villager the farmer profession?', 'Loom', 'Anvil', 'Smoker', 'Composter', 3, 'A composter is the workstation tied to the farmer villager profession.', 55, false),
  ('emeralds-for-trading', 'What gem is the usual currency in villager trading?', 'Diamond', 'Amethyst Shard', 'Quartz', 'Emerald', 3, 'Emeralds are the standard trading currency used by villagers.', 56, false),
  ('fletcher-uses-fletching-table', 'A villager linked to which job block becomes a fletcher?', 'Barrel', 'Smoker', 'Grindstone', 'Fletching Table', 3, 'The fletching table is the workstation for fletchers.', 57, false),
  ('lapis-for-enchanting', 'Which blue item is needed with experience to enchant gear on a table?', 'Blue Ice', 'Diamond', 'Prismarine', 'Lapis Lazuli', 3, 'Enchanting tables use lapis lazuli plus experience levels to power enchantments.', 58, true),
  ('librarian-sells-books', 'Which villager job often sells enchanted books?', 'Librarian', 'Fisherman', 'Butcher', 'Farmer', 0, 'Librarians are great trading partners when you want useful enchantments.', 59, true),
  ('loom-makes-shepherd', 'When a villager claims a loom, which profession appears?', 'Mason', 'Butcher', 'Shepherd', 'Cleric', 2, 'A loom is the workstation that creates a shepherd.', 60, false),
  ('nitwit-has-no-profession', 'Which villager type does not take a normal profession?', 'Fletcher', 'Cleric', 'Farmer', 'Nitwit', 3, 'Nitwits do not claim a standard profession like other villagers.', 61, false),
  ('smoker-makes-butcher', 'Which village block creates a butcher profession?', 'Loom', 'Smoker', 'Bell', 'Smithing Table', 1, 'Butchers use smokers as their workstation.', 62, false),
  ('stonecutter-makes-mason', 'Stonecutters give villagers which profession?', 'Mason', 'Fisherman', 'Toolsmith', 'Shepherd', 0, 'The stonecutter is the workstation for masons.', 63, false),
  ('villagers-sleep-in-beds', 'What do villagers usually use at night when a village is working normally?', 'Beds', 'Blast Furnaces', 'Campfires', 'Minecarts', 0, 'Villagers use beds as part of normal village life.', 64, false),
  ('hearts-show-player-health', 'Which icons on the screen show your health?', 'Armor Icons', 'Bubbles', 'Hearts', 'Drumsticks', 2, 'Each full heart is 2 health points, and losing them all means you die.', 65, true),
  ('armor-cuts-incoming-damage', 'Which equipment reduces the damage mobs deal to you?', 'Saddle', 'Shears', 'Compass', 'Armor', 3, 'Each armor piece adds armor points, and more points mean less damage from hits.', 66, true),
  ('night-more-hostile-spawns', 'Which item shows whether it is day or night, even deep underground?', 'Clock', 'Compass', 'Recovery Compass', 'Spyglass', 0, 'A clock''s dial shows the sun and moon, so you know when it''s safe to leave your shelter.', 67, true),
  ('door-closes-base-entrance', 'Which block at a shelter entrance keeps mobs out but lets you pass?', 'Flower Pot', 'Door', 'Painting', 'Carpet', 1, 'You can open and close a door yourself, while most mobs cannot get through it.', 68, true),
  ('wool-used-for-bed', 'Which block is a carved pumpkin with a torch inside?', 'Sea Lantern', 'Jack o''Lantern', 'Glowstone', 'Lantern', 1, 'A jack o''lantern glows like a torch, so it lights up your shelter and even shines underwater.', 69, true),
  ('ladder-climbs-vertical-wall', 'Which plant hurts you when you touch it?', 'Dead Bush', 'Bamboo', 'Sugar Cane', 'Cactus', 3, 'A cactus damages anyone who touches it, so keep it away from paths and animal pens.', 70, true),
  ('boat-travels-over-water', 'Which item lets you travel quickly across a river or ocean?', 'Lead', 'Minecart', 'Boat', 'Saddle', 2, 'A boat floats on water and moves much faster than swimming.', 71, true),
  ('torch-brightens-dark-spaces', 'Besides a stick, what do you need to craft a torch?', 'Flint', 'Gunpowder', 'Bone', 'Coal', 3, 'A torch is coal or charcoal placed on top of a stick.', 72, true),
  ('sneaking-prevents-edge-fall', 'Which action stops you from walking off a block edge?', 'Swimming', 'Sneaking', 'Gliding', 'Sprinting', 1, 'While sneaking you stop at the edge of a block, which makes building high up safer.', 73, true),
  ('bucket-picks-up-water-source', 'Which item lets you pick up a water source block?', 'Bucket', 'Bowl', 'Cauldron', 'Flower Pot', 0, 'An empty bucket scoops up a water or lava source block so you can place it elsewhere.', 74, true),
  ('chest-stores-home-items', 'Which block do players usually craft to store lots of items at home?', 'Lantern', 'Chest', 'Bed', 'Furnace', 1, 'A chest holds 27 stacks, and two side by side become a large double chest.', 75, true),
  ('bed-crafted-from-wool-and-planks', 'Which item is crafted from three wool and three planks?', 'Boat', 'Bed', 'Shield', 'Ladder', 1, 'Sleeping in a bed skips the night and sets your respawn point.', 76, true),
  ('furnace-crafted-from-cobblestone', 'Which block is crafted from eight cobblestone placed in a ring?', 'Furnace', 'Anvil', 'Dispenser', 'Barrel', 0, 'Eight cobblestone around an empty center make a furnace for smelting ores and cooking food.', 77, true),
  ('four-planks-make-crafting-table', 'Which block do four planks make in the 2×2 inventory grid?', 'Barrel', 'Crafting Table', 'Bookshelf', 'Chest', 1, 'Four planks in a square make a crafting table, your first step toward bigger recipes.', 78, true),
  ('planks-work-as-furnace-fuel', 'Out of coal? Which of these can also fuel a furnace?', 'Planks', 'Stone', 'Glass', 'Gravel', 0, 'Wooden things burn in a furnace, and one plank smelts one and a half items.', 79, true),
  ('pickaxe-breaks-stone-faster', 'Which tool chops logs the fastest?', 'Shears', 'Axe', 'Shovel', 'Pickaxe', 1, 'Axes are made for wood, so logs and planks break much faster with one.', 80, true),
  ('stone-drops-cobblestone', 'How many diamonds does it take to craft a diamond pickaxe?', '3', '2', '5', '4', 0, 'A pickaxe needs three pieces of its material across the top and two sticks below.', 81, true),
  ('iron-ingots-craft-bucket', 'Which ingot is used to craft a bucket?', 'Iron Ingot', 'Netherite Ingot', 'Gold Ingot', 'Copper Ingot', 0, 'Three iron ingots in a V shape make a bucket for water, lava or milk.', 82, true),
  ('stone-next-tier-after-wood', 'Which tool material comes right after wood in the usual upgrade path?', 'Diamond', 'Netherite', 'Iron', 'Stone', 3, 'Stone tools need only cobblestone and sticks, yet last longer and dig faster than wooden ones.', 83, true),
  ('logs-turn-into-planks', 'Cut from a tree, which block is usually turned into planks first?', 'Wool', 'Log', 'Sand', 'Gravel', 1, 'Logs are the basic wood blocks players turn into planks for early building.', 84, false),
  ('dirt-under-many-grass-blocks', 'Beneath many grass blocks, which common natural block is found?', 'Glass', 'Copper', 'Dirt', 'Wool', 2, 'Grass blocks usually sit on top of dirt in the Overworld.', 85, false),
  ('clay-can-be-smelted-into-bricks', 'From ponds and rivers, which soft block can be smelted into bricks?', 'Gravel', 'Ice', 'Coal Ore', 'Clay', 3, 'Clay can be collected near water and turned into bricks by smelting.', 86, false),
  ('door-swings-open-for-houses', 'For a house entrance, which block swings open and shut like a simple gate?', 'Slab', 'Door', 'Torch', 'Carpet', 1, 'Doors are standard entrance blocks for houses and shelters.', 87, false),
  ('fence-gate-opens-between-fences', 'Between two fences, which block lets players and animals pass through?', 'Lantern', 'Fence Gate', 'Ladder', 'Glass Pane', 1, 'Fence gates connect to fences and create an opening in a pen or path.', 88, false),
  ('stairs-help-players-climb-builds', 'To walk up a building more smoothly, which shaped block is often used?', 'Carpet', 'Stairs', 'Pressure Plate', 'Wool', 1, 'Stairs are a common building block for smooth movement between heights.', 89, false),
  ('glass-pane-makes-thin-window', 'For a thinner window than full glass blocks, what can players place?', 'Glass Pane', 'Bed', 'Furnace', 'Chest', 0, 'Glass panes create thinner windows and use glass more efficiently.', 90, false),
  ('gravel-falls-like-sand', 'Like sand, which loose block drops down if nothing supports it?', 'Glass', 'Cobblestone', 'Gravel', 'Oak Planks', 2, 'Gravel is affected by gravity and falls when unsupported.', 91, false),
  ('flowing-lava-and-water-make-cobblestone', 'When flowing lava meets water, what block commonly forms?', 'Cobblestone', 'Clay', 'Obsidian', 'Sandstone', 0, 'Cobblestone often forms when flowing lava touches water.', 92, false),
  ('ice-can-melt-into-water', 'Near strong light or heat, what frozen block can melt into water?', 'Stone', 'Ice', 'Glass', 'Wool', 1, 'Ice can melt into water when conditions are warm enough.', 93, false),
  ('wheat-breeds-cows-and-sheep', 'Which crop can you use to breed cows and sheep?', 'Carrot', 'Potato', 'Beetroot', 'Wheat', 3, 'Cows, sheep and goats all eat wheat, so one wheat field can feed most of your farm animals.', 94, true),
  ('carrot-plants-more-carrots', 'Which crop is planted from the crop itself, with no seeds item?', 'Carrot', 'Wheat', 'Pumpkin', 'Beetroot', 0, 'Carrots, like potatoes, have no seeds: you plant a carrot and harvest several more carrots.', 95, true),
  ('melon-block-grows-from-melon-stem', 'Which crop block drops slices when you break it?', 'Pumpkin', 'Cactus', 'Melon', 'Hay Bale', 2, 'A melon block breaks into 3–7 slices, while a pumpkin drops itself as a whole block.', 96, true),
  ('three-wheat-craft-bread', 'What does raw beef turn into when you cook it in a furnace?', 'Cooked Chicken', 'Steak', 'Cooked Porkchop', 'Cooked Mutton', 1, 'Cooked beef is called steak, and it fills as much hunger as a cooked porkchop.', 97, true),
  ('bowl-carries-mushroom-stew', 'Besides a red and a brown mushroom, what do you need to craft mushroom stew?', 'Bucket', 'Stick', 'Bowl', 'Glass Bottle', 2, 'Stew is served in a bowl, and you get the empty bowl back after eating it.', 98, true),
  ('hay-bale-stores-extra-wheat', 'Which block is crafted from nine wheat?', 'Moss Block', 'Dried Kelp Block', 'Hay Bale', 'White Wool', 2, 'A hay bale packs nine wheat into one block, saving chest space and feeding horses and llamas.', 99, true),
  ('pandas-breed-with-bamboo', 'Which plant do you feed pandas to breed them?', 'Bamboo', 'Sugar Cane', 'Wheat', 'Kelp', 0, 'Pandas live in bamboo jungles and eat bamboo, so it is the food that makes them breed.', 100, true),
  ('cow-makes-moo-sound', 'Which sea creature drops ink sacs?', 'Cod', 'Squid', 'Dolphin', 'Turtle', 1, 'Squids drop ink sacs, which you use to make black dye and a book and quill.', 101, true),
  ('sheep-can-be-sheared', 'Which small flying mob sleeps hanging upside down in dark caves?', 'Parrot', 'Bat', 'Allay', 'Bee', 1, 'Bats hang upside down from cave ceilings and flutter around when a player comes near.', 102, true),
  ('bee-produces-honey', 'Which small mob fills nests and hives with honey?', 'Bat', 'Bee', 'Parrot', 'Chicken', 1, 'Bees collect pollen from flowers and bring it home, slowly filling the nest with honey.', 103, true),
  ('wolf-can-be-tamed-as-pet', 'Which tamed animal can you ride after putting a saddle on it?', 'Parrot', 'Wolf', 'Horse', 'Cat', 2, 'Once a horse is tamed and saddled, you can ride and steer it much faster than walking.', 104, true),
  ('pig-likes-carrots', 'Which animal can you tame by feeding it seeds?', 'Cat', 'Chicken', 'Wolf', 'Parrot', 3, 'Feeding seeds tames a parrot, and after that it can ride on your shoulder.', 105, true),
  ('shield-blocks-many-hits', 'Besides sticks, which item do you need to craft a bow?', 'Leather', 'Feather', 'String', 'Wool', 2, 'Three sticks and three string make a bow, and spiders are the easiest source of string.', 106, true),
  ('sword-is-basic-melee-weapon', 'Which crafted item is made mainly for close-range fighting?', 'Sword', 'Hoe', 'Shovel', 'Bucket', 0, 'A sword is the basic melee weapon and deals more damage than tools like a hoe or shovel.', 107, true),
  ('bow-fires-arrows', 'Which weapon do you pull back to shoot arrows at faraway mobs?', 'Trident', 'Bow', 'Sword', 'Axe', 1, 'A bow lets you attack from a safe distance; the longer you pull it back, the harder it hits.', 108, true),
  ('armor-reduces-attack-damage', 'Which full armor set protects you the least?', 'Diamond Armor', 'Leather Armor', 'Netherite Armor', 'Iron Armor', 1, 'Leather is the weakest armor, while diamond and netherite give the most protection.', 109, true),
  ('torches-help-stop-spawns', 'Which sword deals the most damage?', 'Diamond Sword', 'Stone Sword', 'Netherite Sword', 'Iron Sword', 2, 'Netherite is the strongest material, so its sword hits harder than a diamond one and lasts longer.', 110, true),
  ('ender-pearl-drops-from-enderman', 'Defeating an enderman can drop which item used later for End progression?', 'Prismarine Shard', 'Ender Pearl', 'Nether Star', 'Blaze Rod', 1, 'Ender pearls from endermen are important for crafting Eyes of Ender.', 111, false),
  ('end-portal-opens-path-to-end', 'Filled with the right item, which portal takes players to the dragon dimension?', 'Nether Portal', 'Ruined Portal', 'End Portal', 'Lava Pool', 2, 'An End portal is the structure players use to enter the End.', 112, false),
  ('ender-dragon-is-end-boss', 'On the main island of the End, which boss mob waits for the player?', 'Ghast', 'Warden', 'Ender Dragon', 'Wither', 2, 'The Ender Dragon is the main boss of the End dimension.', 113, false),
  ('stronghold-contains-end-portal', 'Hidden underground, which structure usually contains the End portal room?', 'Village', 'Stronghold', 'Ancient City', 'Mineshaft', 1, 'Players locate a stronghold to reach the End portal room.', 114, false),
  ('end-stone-covers-end-islands', 'Across much of the End, which pale block forms the ground of many islands?', 'Sandstone', 'Soul Sand', 'End Stone', 'Obsidian', 2, 'End Stone is the characteristic block found across many End islands.', 115, false),
  ('redstone-torch-provides-power', 'Glowing red on a wall or floor, which block acts as a simple constant power source?', 'Campfire', 'Redstone Torch', 'Lantern', 'Soul Torch', 1, 'A redstone torch provides redstone power and is one of the most basic circuit components.', 116, false),
  ('pressure-plate-triggers-on-step', 'Stepped on by a mob or player, which flat piece can activate a circuit?', 'Glass Pane', 'Banner', 'Flower Pot', 'Pressure Plate', 3, 'Pressure plates send a redstone signal when something stands on them.', 117, false),
  ('piston-pushes-block-forward', 'Powered by redstone, which block can shove another block forward?', 'Lectern', 'Piston', 'Repeater', 'Observer', 1, 'Pistons move blocks when powered and are core parts of many contraptions.', 118, false),
  ('strider-walks-on-lava', 'Across the lava lakes of the Nether, which rideable mob can walk on the surface?', 'Horse', 'Strider', 'Piglin', 'Blaze', 1, 'Striders can safely walk across lava, making them useful for Nether travel.', 119, false),
  ('warped-fungus-stick-steers-strider', 'To steer a ridden strider, what special item on a stick is used?', 'Carrot on a Stick', 'Lead', 'Fishing Rod', 'Warped Fungus on a Stick', 3, 'A warped fungus on a stick is used to guide a strider across lava.', 120, false)
) as v(content_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, sort_order, is_active)
where pack.slug = 'minecraft-en-easy'
on conflict (pack_id, content_id) do update set
  prompt = excluded.prompt,
  option_a = excluded.option_a,
  option_b = excluded.option_b,
  option_c = excluded.option_c,
  option_d = excluded.option_d,
  correct_option = excluded.correct_option,
  explanation = excluded.explanation,
  sort_order = excluded.sort_order,
  is_active = excluded.is_active;

insert into public.question_packs (category_id, locale, age_band, difficulty, title, slug, is_active)
select id, 'en', '8-12', 'medium', 'MineMind en medium', 'minecraft-en-medium', true
from public.quiz_categories
where slug = 'minecraft'
on conflict (slug) do update set is_active = true, title = excluded.title;

insert into public.questions (pack_id, content_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, sort_order, is_active)
select pack.id, v.content_id, v.prompt, v.option_a, v.option_b, v.option_c, v.option_d, v.correct_option, v.explanation, v.sort_order, v.is_active
from public.question_packs pack
cross join (values
  ('amethyst-geode-underground', 'Amethyst geodes are usually discovered in what kind of place?', 'Underground', 'Inside a swamp hut', 'On top of a village', 'In the End sky', 0, 'Amethyst geodes generate underground and must be found while exploring below the surface.', 1, false),
  ('desert-temple-desert', 'Which biome is the usual home of a desert temple?', 'Desert', 'Cherry Grove', 'Swamp', 'Taiga', 0, 'Desert temples generate in deserts, matching their name and material palette.', 2, false),
  ('dripstone-caves-have-pointed-dripstone', 'Pointed dripstone is a signature feature of which cave biome?', 'Beach', 'Mushroom Fields', 'Dripstone Caves', 'Cherry Grove', 2, 'Dripstone caves are defined by large amounts of pointed dripstone and stalactite-like formations.', 3, false),
  ('igloo-in-snowy-biomes', 'Which chilly structure may appear in snowy biomes?', 'Igloo', 'Jungle Temple', 'Nether Fortress', 'Desert Pyramid', 0, 'Igloos fit snowy areas and can even hide a little surprise underneath.', 4, true),
  ('jungle-temple-jungle', 'Where do jungle temples generate?', 'Jungle', 'Snowy Slopes', 'Meadow', 'Ocean', 0, 'Jungle temples are generated structures found in jungle biomes.', 5, false),
  ('lush-caves-have-glow-berries', 'Which cave biome is known for glow berries and lush plants?', 'Basalt Deltas', 'Badlands', 'Snowy Plains', 'Lush Caves', 3, 'Lush caves are rich with vegetation and glow berries.', 6, false),
  ('mangrove-swamp-has-mud', 'Which biome is known for mangrove trees and lots of mud?', 'Frozen Ocean', 'Savanna', 'Badlands', 'Mangrove Swamp', 3, 'Mangrove swamps stand out with mangrove roots, frogs, and muddy ground.', 7, true),
  ('mineshaft-underground', 'Abandoned mineshafts are usually found in which kind of place?', 'On mushroom islands', 'Underground', 'Inside oceans', 'In the sky', 1, 'Mineshafts generate below the surface as underground structures.', 8, false),
  ('ocean-monument-guardians', 'Which ocean structure is home to guardians?', 'Igloo', 'Stronghold', 'Ocean Monument', 'Woodland Mansion', 2, 'Ocean monuments are underwater structures guarded by guardians and elder guardians.', 9, true),
  ('ocean-ruins-underwater', 'What structure is usually found underwater and often made of worn stone blocks?', 'Stronghold', 'Pillager Outpost', 'Ocean Ruins', 'Woodland Mansion', 2, 'Ocean ruins are underwater structures scattered through ocean regions.', 10, false),
  ('pillager-outpost-has-pillagers', 'What hostile structure is strongly associated with pillagers?', 'Jungle Temple', 'Trial Ruins', 'Ocean Monument', 'Pillager Outpost', 3, 'Pillager outposts are structures where pillagers commonly appear.', 11, false),
  ('shipwrecks-near-ocean', 'Which structure is commonly found in ocean areas?', 'Witch Hut', 'Shipwreck', 'Woodland Mansion', 'Nether Fortress', 1, 'Shipwrecks commonly generate in ocean-related areas.', 12, false),
  ('strongholds-underground', 'Where are strongholds usually found before players break into them?', 'Floating over oceans', 'On treetops', 'Inside villages', 'Underground', 3, 'Strongholds generate underground and are usually found by digging down after tracking them.', 13, false),
  ('warm-ocean-has-coral', 'Coral reefs are most strongly associated with which biome?', 'Frozen River', 'Warm Ocean', 'Deep Dark', 'Taiga', 1, 'Warm oceans are known for colorful coral reefs.', 14, false),
  ('witch-hut-swamp', 'Which biome is associated with witch huts?', 'Swamp', 'Badlands', 'Savanna', 'Beach', 0, 'Witch huts are swamp structures.', 15, false),
  ('concrete-powder-hardens-in-water', 'What happens to concrete powder when it touches water?', 'It turns into concrete', 'It disappears', 'It becomes sand', 'It grows upward', 0, 'Concrete powder hardens into solid concrete after touching water.', 16, false),
  ('fence-stops-animal-escape', 'Which block is often used to keep animals inside a pen?', 'Banner', 'Chest', 'Torch', 'Fence', 3, 'Fences are a common pen block because animals do not simply walk through them.', 17, false),
  ('ladder-climbs-wall', 'Which block helps you climb straight up a wall?', 'Carpet', 'Ladder', 'Trapdoor', 'Fence', 1, 'Ladders attach to blocks and make a quick vertical path for players.', 18, true),
  ('slab-is-half-block', 'Which building piece is half as tall as a full block?', 'Pane', 'Slab', 'Wall', 'Torch', 1, 'Slabs are great for floors, roofs, and smoother shapes because they are half-height blocks.', 19, true),
  ('trapdoor-covers-hole', 'What hinged block is useful for covering a small floor opening?', 'Pressure Plate', 'Ladder', 'Sign', 'Trapdoor', 3, 'Trapdoors open and close over one-block spaces, making them useful for floors and ceilings.', 20, false),
  ('charcoal-works-for-torches', 'Which item goes on top of a stick to craft a torch?', 'Charcoal', 'Flint', 'Gunpowder', 'Glowstone Dust', 0, 'Torches take coal or charcoal, so smelted logs light your base even before you find coal.', 21, true),
  ('chest-needs-eight-planks', 'How many planks does it take to craft a chest?', '9', '6', '7', '8', 3, 'The planks fill every slot of the 3×3 grid except the center.', 22, true),
  ('sand-smelts-into-glass', 'What do you get when you smelt sand in a furnace?', 'Glass', 'Nether Quartz', 'Gravel', 'Clay', 0, 'Heat melts sand into glass, the go-to block for windows.', 23, true),
  ('stonecutter-shapes-stone-builds', 'Which workstation turns one block into stairs, slabs or walls without a crafting table?', 'Grindstone', 'Stonecutter', 'Loom', 'Smithing Table', 1, 'You pick the shape you want and it uses one block at a time, so no full recipe is needed.', 24, true),
  ('bee-pollinates-crops', 'Which mob makes crops grow faster after visiting flowers?', 'Rabbit', 'Allay', 'Parrot', 'Bee', 3, 'A bee carrying pollen helps crops it flies over grow a stage, so a hive near a farm speeds it up.', 25, true),
  ('water-keeps-farmland-hydrated', 'Which block keeps nearby farmland moist?', 'Lava', 'Snow Block', 'Ice', 'Water', 3, 'Water within 4 blocks keeps farmland moist and dark, and crops on moist farmland grow faster.', 26, true),
  ('dry-farmland-becomes-dirt', 'What does farmland turn into if it stays dry with nothing planted on it?', 'Gravel', 'Dirt', 'Mud', 'Sand', 1, 'Without water or crops farmland slowly dries out and turns back into dirt; jumping on it does the same.', 27, true),
  ('kelp-grows-underwater', 'Which plant keeps growing taller while fully underwater?', 'Sugar Cane', 'Kelp', 'Bamboo', 'Cactus', 1, 'Kelp grows upward through water blocks, which makes it great for an automatic underwater farm.', 28, true),
  ('bone-tames-wolf', 'Which item do you feed a wild wolf to tame it?', 'Leather', 'Feather', 'String', 'Bone', 3, 'Each bone has a chance to tame the wolf, and then it gets a collar and follows you.', 29, true),
  ('enderman-hurt-by-water', 'Which mob takes damage from water and rain?', 'Spider', 'Witch', 'Zombie', 'Enderman', 3, 'Water hurts endermen, so standing in water or under a roof of water helps you escape them.', 30, true),
  ('iron-golem-defends-village', 'Which big mob spawns in villages and fights off zombies?', 'Wandering Trader', 'Snow Golem', 'Iron Golem', 'Pillager', 2, 'Iron golems guard villagers and attack hostile mobs that come into the village.', 31, true),
  ('witch-throws-potions', 'Which hostile mob attacks by throwing splash potions?', 'Blaze', 'Skeleton', 'Drowned', 'Witch', 3, 'Witches throw harmful splash potions and drink potions themselves to heal.', 32, true),
  ('zombie-villager-cured', 'Which mob can you cure with Weakness and a golden apple?', 'Husk', 'Zombie Villager', 'Zombie', 'Drowned', 1, 'A zombie villager hit with Weakness and fed a golden apple turns back into a villager.', 33, true),
  ('pillager-fires-crossbow', 'Which weapon does a pillager attack with?', 'Trident', 'Crossbow', 'Axe', 'Bow', 1, 'Pillagers are ranged illagers that shoot arrows from crossbows.', 34, true),
  ('blaze-drops-rods', 'Which mob drops the rods needed for brewing stands?', 'Magma Cube', 'Blaze', 'Endermite', 'Wither Skeleton', 1, 'Blazes drop blaze rods, an important ingredient for brewing and finding the End.', 35, true),
  ('blaze-powder-for-eye-of-ender', 'What ingredient from the Nether is combined with an ender pearl to make an Eye of Ender?', 'Gunpowder', 'Nether Brick', 'Blaze Powder', 'Glow Ink', 2, 'Blaze powder is combined with an ender pearl to craft an Eye of Ender.', 36, false),
  ('ghast-shoots-fireballs', 'Which large flying Nether mob shoots fireballs?', 'Strider', 'Hoglin', 'Ghast', 'Piglin', 2, 'Ghasts float through big Nether spaces and attack by launching fireballs.', 37, true),
  ('lever-toggles-circuit', 'Which simple switch can turn a redstone circuit on and off?', 'Lever', 'Cauldron', 'Item Frame', 'Ladder', 0, 'A lever stays in place after you flip it, so it is great for simple redstone control.', 38, true),
  ('repeater-refreshes-signal', 'Which redstone component is commonly used to refresh a weakening signal?', 'Ladder', 'Bed', 'Boat', 'Repeater', 3, 'Repeaters boost redstone signals back to full strength and can also add delay.', 39, false),
  ('compass-points-to-world-spawn', 'In the Overworld, where does a regular compass point?', 'Nether Portal', 'Your bed', 'Nearest village', 'World spawn', 3, 'A normal compass always points to the world spawn, not to your bed or base.', 40, true),
  ('shield-blocks-attacks', 'Which item can you raise to block arrows and hits?', 'Iron Helmet', 'Shield', 'Turtle Shell', 'Iron Chestplate', 1, 'Armor only lowers damage, but a raised shield fully blocks most hits from the front.', 41, true),
  ('sleep-skips-thunderstorm', 'Besides at night, when can you sleep in a bed?', 'During a thunderstorm', 'At noon', 'During snowfall', 'At sunrise', 0, 'Thunderstorms are dark enough for monsters to spawn, so beds work then even in daytime.', 42, true),
  ('water-bucket-softens-falls', 'Which item cancels fall damage if you place it just before landing?', 'Lava Bucket', 'Fishing Rod', 'Milk Bucket', 'Water Bucket', 3, 'Landing in water cancels fall damage, so placing water just before impact saves you.', 43, true),
  ('phantom-comes-after-no-sleep', 'Which flying mob attacks players who skip sleep for several nights?', 'Bat', 'Bee', 'Phantom', 'Parrot', 2, 'Phantoms spawn in the night sky above players who have not slept for a while.', 44, true),
  ('anvil-can-rename-items', 'What useful thing can an anvil do besides repairs and enchant combining?', 'Change biomes', 'Rename items', 'Smelt ores', 'Duplicate blocks', 1, 'Anvils can also rename items, not just repair or combine them.', 45, false),
  ('anvil-combines-enchantments', 'Which block lets you combine enchantments from a book onto a tool?', 'Smoker', 'Barrel', 'Anvil', 'Bed', 2, 'Anvils are used to combine items, rename them, and apply enchantments from books.', 46, true),
  ('bookshelves-need-air-gap', 'For a bookshelf to power an enchanting table, what must stay between them?', 'An empty air block', 'A torch', 'A carpet', 'A sign', 0, 'Bookshelves only help an enchanting table when the space between them stays open.', 47, false),
  ('brewing-stand-makes-cleric', 'A villager linked to which workstation becomes a cleric?', 'Stonecutter', 'Fletching Table', 'Cartography Table', 'Brewing Stand', 3, 'The brewing stand is the workstation for clerics.', 48, false),
  ('cartographer-sells-mansion-map', 'Who can trade a map that helps players find a woodland mansion?', 'Cleric', 'Librarian', 'Mason', 'Cartographer', 3, 'Cartographers are the villagers known for selling structure maps.', 49, false),
  ('cartographer-sells-ocean-map', 'Which villager can sell a map that leads toward an ocean monument?', 'Butcher', 'Shepherd', 'Farmer', 'Cartographer', 3, 'Cartographers can trade explorer maps that point to major structures such as ocean monuments.', 50, false),
  ('curing-zombie-villager-lowers-prices', 'After a zombie villager is cured, what often happens to its trade prices?', 'They disappear forever', 'They become random biomes', 'They get cheaper', 'They turn into bed prices', 2, 'Cured villagers often offer discounted trades to the player who helped them.', 51, false),
  ('enchanted-books-applied-with-anvil', 'Which block do players use to apply an enchanted book onto gear?', 'Composter', 'Bell', 'Loom', 'Anvil', 3, 'Anvils are used to combine enchanted books with tools, armor, and weapons.', 52, false),
  ('enchanting-table-needs-xp-levels', 'Besides lapis lazuli, what else does enchanting table use up?', 'Village reputation', 'Hearts', 'Food points', 'Experience levels', 3, 'Enchanting uses both lapis lazuli and experience levels.', 53, false),
  ('lectern-makes-librarian', 'Which job-site block turns an unemployed villager into a librarian?', 'Lectern', 'Composter', 'Cauldron', 'Blast Furnace', 0, 'Villagers pick jobs from nearby workstations, and the lectern creates librarians.', 54, true),
  ('smithing-table-makes-toolsmith', 'Which workstation block is linked to the toolsmith profession?', 'Bell', 'Note Block', 'Loom', 'Smithing Table', 3, 'The toolsmith profession uses the smithing table as its workstation.', 55, false),
  ('three-enchanting-choices', 'How many enchantment options does an enchanting table usually show at once?', '4', '1', '2', '3', 3, 'An enchanting table normally presents three enchantment choices at a time.', 56, false),
  ('unemployed-villager-claims-job-block', 'What can turn an unemployed villager into a worker?', 'Holding an emerald', 'Claiming a nearby job block', 'Fighting a mob', 'Sleeping in the Nether', 1, 'An unemployed villager can take a profession when it links to a workstation.', 57, false),
  ('villager-needs-bed-to-breed', 'What must a village have available for villagers to breed successfully?', 'Spare beds', 'Lava pools', 'Armor stands', 'Diamond blocks', 0, 'Villager breeding depends on village conditions including available beds.', 58, false),
  ('villagers-restock-at-workstation', 'Where does a villager usually need access to in order to restock trades?', 'A brewing recipe', 'A beacon', 'A nether portal', 'Its workstation', 3, 'Villagers usually restock by working at their own profession block.', 59, false),
  ('bread-easy-hunger-refill', 'Which food can you craft from just three wheat?', 'Cake', 'Pumpkin Pie', 'Cookie', 'Bread', 3, 'Three wheat in a row make bread; cookies need cocoa, cake and pie need eggs and sugar.', 60, true),
  ('milk-clears-most-effects', 'Which drink removes all your status effects at once?', 'Milk Bucket', 'Water Bottle', 'Potion of Healing', 'Honey Bottle', 0, 'Milk clears every effect, good and bad, while honey only removes Poison.', 61, true),
  ('rotten-flesh-emergency-food', 'Which zombie drop is edible but often gives you Hunger?', 'Potato', 'Rotten Flesh', 'Carrot', 'Iron Ingot', 1, 'Rotten flesh has an 80% chance to cause Hunger, so eat it only in an emergency.', 62, true),
  ('air-bubbles-show-drowning', 'Underwater, which icons run out before you start to drown?', 'Armor Icons', 'XP Bar', 'Drumsticks', 'Air Bubbles', 3, 'Bubbles show your air; when they are gone you lose health every second.', 63, true),
  ('spider-eye-causes-poison', 'Which food always poisons you when eaten?', 'Sweet Berries', 'Spider Eye', 'Rotten Flesh', 'Raw Chicken', 1, 'A spider eye always gives Poison, while rotten flesh and raw chicken only risk Hunger.', 64, true),
  ('torches-help-stop-indoor-spawns', 'What stops hostile mobs from spawning inside your house?', 'Torches', 'Flower Pots', 'Paintings', 'Item Frames', 0, 'Hostile mobs need total darkness to spawn, and torches remove it.', 65, true),
  ('sleep-turns-world-to-morning', 'What can stop you from sleeping in a bed at night?', 'Monsters nearby', 'Wearing armor', 'Full inventory', 'Low hunger', 0, 'You cannot rest while hostile mobs are within about 8 blocks of the bed.', 66, true),
  ('roof-completes-first-shelter', 'How many real-time minutes does one full day-and-night cycle last?', '60', '30', '20', '10', 2, 'A full day lasts 20 minutes, and about 7 of them are night, when hostile mobs roam.', 67, true),
  ('water-puts-out-fire', 'What quickly puts out the flames when you are on fire?', 'Sand', 'Wool', 'Water', 'Gravel', 2, 'Stepping into water instantly puts out the fire, so keep a water bucket near lava.', 68, true),
  ('minecart-rides-on-rails', 'Which vehicle is made to ride along rails?', 'Elytra', 'Boat', 'Minecart', 'Lead', 2, 'Minecarts roll on rails and can carry players, mobs or items.', 69, true),
  ('wooden-sword-basic-weapon', 'Which item is crafted from two planks and one stick?', 'Wooden Sword', 'Wooden Axe', 'Wooden Pickaxe', 'Wooden Shovel', 0, 'Two planks on a stick make a sword, while a pickaxe or axe needs three planks and two sticks.', 70, true),
  ('log-smelts-into-charcoal', 'What do you get by smelting a log in a furnace?', 'Stick', 'Coal', 'Planks', 'Charcoal', 3, 'A smelted log becomes charcoal, which burns just as long as regular coal.', 71, true),
  ('cobblestone-smelts-into-stone', 'What do you get by smelting a cactus in a furnace?', 'Slimeball', 'Lime Dye', 'Green Dye', 'Dried Kelp', 2, 'Smelting cactus is how you get green dye, and mixing it with white dye makes lime dye.', 72, true),
  ('dried-kelp-block-is-fuel', 'Which of these blocks can be burned as furnace fuel?', 'Dried Kelp Block', 'Honey Block', 'Slime Block', 'Hay Bale', 0, 'A dried kelp block smelts 20 items, so a kelp farm gives you endless fuel.', 73, true),
  ('anvil-renames-and-repairs', 'Which workstation lets you rename items and combine enchantments?', 'Smithing Table', 'Anvil', 'Cartography Table', 'Loom', 1, 'An anvil spends experience levels to rename, repair or merge enchanted items.', 74, true),
  ('loom-adds-banner-patterns-crafting', 'Which workstation is used to add patterns to banners?', 'Grindstone', 'Smoker', 'Loom', 'Blast Furnace', 2, 'A loom combines a banner and dye to add designs layer by layer.', 75, true),
  ('grindstone-clears-enchantments', 'Which block do you craft by surrounding a furnace with four logs?', 'Campfire', 'Barrel', 'Smoker', 'Blast Furnace', 2, 'Four logs around a furnace make a smoker, which is also the butcher''s job block.', 76, true),
  ('stone-pickaxe-mines-iron-ore', 'What is the weakest pickaxe that can mine iron ore?', 'Golden Pickaxe', 'Iron Pickaxe', 'Stone Pickaxe', 'Wooden Pickaxe', 2, 'Wooden and golden pickaxes break iron ore without dropping anything, so stone is the minimum.', 77, true),
  ('shears-need-iron-ingots', 'Which item is crafted from just two iron ingots?', 'Cauldron', 'Bucket', 'Minecart', 'Shears', 3, 'Two iron ingots placed diagonally make shears, while a bucket needs three.', 78, true),
  ('paper-from-sugar-cane', 'What is sugar cane crafted into for books and maps?', 'Clay', 'Paper', 'String', 'Leather', 1, 'Three sugar cane in a row make three paper for books, maps and firework rockets.', 79, true),
  ('flint-and-steel-lights-portals', 'Which furnace fuel smelts the most items?', 'Dried Kelp Block', 'Lava Bucket', 'Block of Coal', 'Blaze Rod', 1, 'A lava bucket smelts 100 items, more than a block of coal (80), so lava makes a great fuel.', 80, true),
  ('sandstone-crafted-from-sand', 'In a crafting grid, four sand blocks make what desert building block?', 'Mud Bricks', 'Stone Bricks', 'Quartz Block', 'Sandstone', 3, 'Sandstone is the classic desert building block crafted from sand.', 81, false),
  ('stone-bricks-crafted-from-stone', 'Which classic gray building block is crafted from four stone blocks?', 'Smooth Quartz', 'Cobblestone Stairs', 'Stone Bricks', 'Glass Pane', 2, 'Stone bricks are crafted from stone and are a common strong-looking building block.', 82, false),
  ('axe-creates-stripped-log', 'Used on a log, an axe creates which cleaner wood variant?', 'Cut Copper', 'Stripped Log', 'Moss Block', 'Chiseled Stone', 1, 'An axe can strip bark from logs, creating a cleaner-looking wood block.', 83, false),
  ('smooth-stone-comes-from-second-smelt', 'If ordinary stone is smelted again, what smoother block comes out?', 'Polished Andesite', 'Deepslate', 'Cracked Stone Bricks', 'Smooth Stone', 3, 'Smelting stone again produces smooth stone.', 84, false),
  ('terracotta-smelts-from-clay-block', 'When a clay block is smelted, what solid building block does it become?', 'Terracotta', 'Snow Block', 'Concrete', 'Sandstone', 0, 'Smelting a clay block turns it into terracotta.', 85, false),
  ('pressure-plate-sends-signal-when-stepped-on', 'Stepped on by a player or mob, which flat block can send a redstone signal?', 'Pressure Plate', 'Flower Pot', 'Trapdoor', 'Carpet', 0, 'Pressure plates trigger a redstone signal when something stands on them.', 86, false),
  ('glass-drops-nothing-without-silk-touch', 'Broken with a normal tool, which window block usually drops nothing?', 'Glass', 'Cobblestone', 'Dirt', 'Ladder', 0, 'Glass normally shatters without dropping itself unless Silk Touch is used.', 87, false),
  ('leaves-decay-without-nearby-log', 'If they are not near logs, what often happens to natural leaves after a tree is cut?', 'They Become Wool', 'They Turn to Stone', 'They Decay', 'They Catch Fire Automatically', 2, 'Natural leaves usually decay after the supporting logs are removed.', 88, false),
  ('sponge-soaks-up-water', 'Placed in water, which block soaks up nearby water source blocks?', 'Terracotta', 'Wool', 'Sponge', 'Bedrock', 2, 'Sponges absorb nearby water source blocks when placed.', 89, false),
  ('unsupported-scaffolding-breaks', 'If there is no support within range underneath, what tall building block eventually breaks?', 'Glass', 'Barrel', 'Scaffolding', 'Fence', 2, 'Scaffolding needs nearby support or it will break instead of floating forever.', 90, false),
  ('potatoes-grow-from-potatoes', 'Which crop sometimes drops a poisonous version of itself when harvested?', 'Beetroot', 'Carrot', 'Sweet Berries', 'Potato', 3, 'Fully grown potatoes have a small chance to also drop a poisonous potato, which is risky to eat.', 91, true),
  ('sugar-cane-needs-water-nearby', 'Which plant can only be planted on a block right next to water?', 'Bamboo', 'Sugar Cane', 'Cactus', 'Sweet Berries', 1, 'Sugar cane needs water touching the block it stands on, which is why it grows along rivers.', 92, true),
  ('egg-is-needed-for-cake', 'Besides milk, sugar and wheat, what goes into a cake recipe?', 'Leather', 'Feather', 'Egg', 'Honey Bottle', 2, 'A cake uses 3 milk buckets, 2 sugar, 3 wheat and 1 egg, so you need chickens as well as cows.', 93, true),
  ('sugar-completes-pumpkin-pie', 'Pumpkin pie is crafted from a pumpkin, an egg and what else?', 'Sugar', 'Cocoa Beans', 'Wheat', 'Milk Bucket', 0, 'Pumpkin pie is shapeless: just a pumpkin, an egg and sugar from sugar cane, with no milk or wheat.', 94, true),
  ('seeds-breed-chickens', 'Which item do you use to breed chickens?', 'Apple', 'Wheat', 'Bread', 'Wheat Seeds', 3, 'Chickens eat seeds, not grown wheat; any seeds work, including pumpkin, melon and beetroot seeds.', 95, true),
  ('golden-carrot-breeds-rabbits', 'Which flower can you use to breed rabbits?', 'Poppy', 'Dandelion', 'Cornflower', 'Oxeye Daisy', 1, 'Rabbits breed with carrots, golden carrots or dandelions, the yellow flower they also eat in the wild.', 96, true),
  ('golden-apple-breeds-horses', 'Which food makes two tamed horses ready to breed?', 'Golden Apple', 'Sugar', 'Apple', 'Wheat', 0, 'Horses breed only with golden apples or golden carrots; plain apples, sugar and wheat just heal them.', 97, true),
  ('cocoa-beans-grow-on-jungle-logs', 'On which log can cocoa beans be planted?', 'Birch Log', 'Oak Log', 'Jungle Log', 'Mangrove Log', 2, 'Cocoa pods grow on the side of jungle logs, the same trees they hang from in jungles.', 98, true),
  ('glass-bottle-collects-honey', 'Which item collects honey from a full beehive?', 'Cauldron', 'Glass Bottle', 'Bucket', 'Bowl', 1, 'Honey is collected into an empty glass bottle, giving a honey bottle that also cures poison.', 99, true),
  ('shears-collect-honeycomb', 'Which tool harvests honeycomb from a full beehive?', 'Shears', 'Shovel', 'Axe', 'Hoe', 0, 'Shears snip 3 honeycombs off a full hive or nest, which you can use to wax copper or craft candles.', 100, true),
  ('cocoa-beans-craft-cookies', 'Which ingredient goes between two wheat to craft cookies?', 'Cocoa Beans', 'Sugar', 'Beetroot', 'Egg', 0, 'Two wheat with cocoa beans in the middle make 8 cookies, so cocoa farms are worth planting.', 101, true),
  ('goat-can-ram-players', 'Which mountain mob can suddenly ram you and knock you off a cliff?', 'Rabbit', 'Sheep', 'Goat', 'Llama', 2, 'Goats live in mountains and sometimes charge at players, which can push you off a ledge.', 102, true),
  ('llama-spits-when-angry', 'Which animal spits at mobs and players that attack it?', 'Horse', 'Panda', 'Goat', 'Llama', 3, 'Llamas defend themselves by spitting, and they also spit at wolves on sight.', 103, true),
  ('bee-dies-after-stinging', 'Which mob dies soon after it stings someone?', 'Endermite', 'Phantom', 'Bee', 'Cave Spider', 2, 'A bee loses its stinger when it stings, and it dies about a minute later.', 104, true),
  ('polar-bear-protects-cub', 'Which snowy-biome animal turns hostile if you go near its cub?', 'Polar Bear', 'Fox', 'Goat', 'Rabbit', 0, 'Adult polar bears are neutral, but they attack players who come close to their cubs.', 105, true),
  ('drowned-can-throw-trident', 'Which underwater undead mob can throw a trident at you?', 'Skeleton', 'Drowned', 'Zombie', 'Husk', 1, 'Some drowned spawn holding a trident and throw it, and they are the only mob that can drop one.', 106, true),
  ('ghast-launches-fireballs', 'Which snowy-biome mob shoots arrows that give you Slowness?', 'Skeleton', 'Stray', 'Husk', 'Pillager', 1, 'Strays are icy skeletons from snowy biomes, and their tipped arrows slow you down.', 107, true),
  ('arrows-needed-for-bow', 'Which item forms the tip of an arrow in its crafting recipe?', 'Gravel', 'Bone', 'Flint', 'Iron Nugget', 2, 'Arrows are crafted from flint, a stick and a feather; flint drops from broken gravel.', 108, true),
  ('golden-apple-gives-extra-hearts', 'Which item is crafted from six planks and one iron ingot?', 'Crossbow', 'Barrel', 'Shield', 'Bucket', 2, 'Six planks with an iron ingot at the top make a shield, which blocks most attacks from the front.', 109, true),
  ('potion-of-healing-restores-health', 'Which potion gives back lost hearts instantly?', 'Potion of Fire Resistance', 'Potion of Healing', 'Potion of Swiftness', 'Potion of Night Vision', 1, 'Healing works at once, unlike Regeneration, which restores hearts slowly over time.', 110, true),
  ('end-crystal-heals-dragon', 'Standing on obsidian pillars, which object restores the dragon''s health?', 'Beacon', 'End Crystal', 'Sea Lantern', 'Respawn Anchor', 1, 'End crystals heal the Ender Dragon until players destroy them.', 111, false),
  ('dragon-egg-appears-after-fight', 'After the dragon is defeated, which rare trophy block appears on the exit portal?', 'Beacon', 'Dragon Egg', 'Conduit', 'Nether Star', 1, 'A Dragon Egg appears after the Ender Dragon is defeated.', 112, false),
  ('shulker-causes-levitation', 'Inside End Cities, which hostile mob shoots projectiles that cause levitation?', 'Piglin', 'Shulker', 'Slime', 'Blaze', 1, 'Shulkers are End City mobs known for levitation projectiles.', 113, false),
  ('fire-resistance-helps-in-lava', 'For crossing dangerous lava areas, which potion effect is especially helpful?', 'Night Vision', 'Slow Falling', 'Fire Resistance', 'Luck', 2, 'Fire Resistance makes lava and fire much less dangerous during Nether travel.', 114, false),
  ('lodestone-guides-special-compass', 'In a dimension where normal compasses fail, which block can a lodestone compass point to?', 'Smithing Table', 'Lodestone', 'Beacon', 'Bell', 1, 'A lodestone can anchor a compass so it points correctly even outside the Overworld.', 115, false),
  ('respawn-anchor-sets-spawn-in-nether', 'Charged before use, which block lets players set a respawn point in the Nether?', 'Crafting Table', 'Jukebox', 'Campfire', 'Respawn Anchor', 3, 'A respawn anchor can set a Nether respawn point when it has charges.', 116, false),
  ('soul-speed-helps-on-soul-sand', 'On soul sand and soul soil, which boot enchantment makes travel much faster?', 'Soul Speed', 'Looting', 'Feather Falling', 'Respiration', 0, 'Soul Speed boosts movement on soul sand and soul soil.', 117, false),
  ('comparator-reads-container-fullness', 'Reading how full a chest is, which component compares signal strength?', 'Comparator', 'Trapdoor', 'Button', 'Piston', 0, 'Comparators can measure things like container fullness and compare signal strengths.', 118, false),
  ('sticky-piston-pulls-block-back', 'Retracting after extension, which piston type can pull one block back with it?', 'Sticky Piston', 'Observer', 'Redstone Lamp', 'Daylight Sensor', 0, 'Sticky pistons can pull a block back when they retract.', 119, false),
  ('note-block-plays-musical-tone', 'Powered by a pulse, which decorative block makes a musical note sound?', 'Grindstone', 'Barrel', 'Note Block', 'Chest', 2, 'Note blocks produce musical tones when activated.', 120, false)
) as v(content_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, sort_order, is_active)
where pack.slug = 'minecraft-en-medium'
on conflict (pack_id, content_id) do update set
  prompt = excluded.prompt,
  option_a = excluded.option_a,
  option_b = excluded.option_b,
  option_c = excluded.option_c,
  option_d = excluded.option_d,
  correct_option = excluded.correct_option,
  explanation = excluded.explanation,
  sort_order = excluded.sort_order,
  is_active = excluded.is_active;

insert into public.question_packs (category_id, locale, age_band, difficulty, title, slug, is_active)
select id, 'en', '8-12', 'hard', 'MineMind en hard', 'minecraft-en-hard', true
from public.quiz_categories
where slug = 'minecraft'
on conflict (slug) do update set is_active = true, title = excluded.title;

insert into public.questions (pack_id, content_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, sort_order, is_active)
select pack.id, v.content_id, v.prompt, v.option_a, v.option_b, v.option_c, v.option_d, v.correct_option, v.explanation, v.sort_order, v.is_active
from public.question_packs pack
cross join (values
  ('ancient-city-deep-dark', 'What biome contains ancient cities?', 'Deep Dark', 'Dripstone Caves', 'Lush Caves', 'Basalt Deltas', 0, 'Ancient cities generate in the deep dark.', 1, false),
  ('badlands-above-ground-mineshafts', 'Which biome is especially known for exposed abandoned mineshafts?', 'Badlands', 'Mushroom Fields', 'Warm Ocean', 'Cherry Grove', 0, 'Badlands can generate mineshafts exposed high in the terrain, unlike many other biomes.', 2, false),
  ('bastion-remnant-nether', 'Bastion remnants generate in which dimension?', 'The Overworld', 'The Nether', 'All dimensions', 'The End', 1, 'Bastion remnants are large Nether structures.', 3, false),
  ('buried-treasure-found-from-map', 'What item usually points a player toward buried treasure?', 'A treasure map', 'An enchanted book', 'A bell', 'A goat horn', 0, 'Buried treasure is normally tracked with a treasure map.', 4, false),
  ('deep-dark-has-sculk', 'Sculk blocks are the clearest sign of which biome?', 'Beach', 'Savanna', 'Deep Dark', 'River', 2, 'The deep dark is characterized by sculk-covered terrain.', 5, false),
  ('desert-well-desert', 'Desert wells appear in which biome type?', 'Meadow', 'Mangrove Swamp', 'Frozen Peaks', 'Desert', 3, 'Desert wells are a small structure tied to desert generation.', 6, false),
  ('end-city-has-shulkers', 'Which structure is famous for containing shulkers?', 'Igloo', 'Jungle Temple', 'End City', 'Desert Well', 2, 'Shulkers are found in end cities, where players also look for special loot.', 7, false),
  ('end-city-outer-end', 'In what region do players search for end cities?', 'The Overworld ocean floor', 'The outer End islands', 'Any village biome', 'The Nether roof', 1, 'End cities generate in the outer End, not near the central dragon island.', 8, false),
  ('frozen-ocean-has-icebergs', 'Icebergs are most strongly linked with which biome?', 'Swamp', 'Warm Ocean', 'Frozen Ocean', 'Badlands', 2, 'Frozen oceans are cold water biomes known for ice and icebergs.', 9, false),
  ('mushroom-fields-safe-from-many-mobs', 'Which biome is famous because many common hostile mobs do not spawn there?', 'Mushroom Fields', 'Savanna', 'Taiga', 'Stony Peaks', 0, 'Mushroom fields are unusual and calm, which makes them feel extra safe to explore.', 10, true),
  ('nether-fortress-has-blazes', 'Which major structure is the classic place to find blazes?', 'Ocean Ruins', 'Nether Fortress', 'Pillager Outpost', 'Woodland Mansion', 1, 'Blazes are strongly tied to Nether fortresses and their spawners.', 11, false),
  ('ruined-portal-two-dimensions', 'A ruined portal can appear in which two dimensions?', 'The Nether and the End', 'The Overworld and the End', 'The Overworld and the Nether', 'Only the Overworld', 2, 'Ruined portals can generate in both the Overworld and the Nether.', 12, false),
  ('stronghold-holds-end-portal', 'Which underground structure contains an End Portal room?', 'Ancient City', 'Stronghold', 'Pillager Outpost', 'Village', 1, 'Strongholds are special because their portal room is the path to the End dimension.', 13, true),
  ('trial-chamber-underground', 'Trial chambers are explored in what general kind of location?', 'Floating over rivers', 'Inside villages', 'Underground', 'At the world spawn point', 2, 'Trial chambers are underground structures, not surface landmarks.', 14, false),
  ('woodland-mansion-dark-forest', 'In which biome does a woodland mansion generate?', 'Savanna', 'Desert', 'Dark Forest', 'Birch Forest', 2, 'Woodland mansions generate in dark forests.', 15, false),
  ('honey-block-slows-slide', 'Which sticky block slows entities as they slide down its side?', 'Coal Block', 'Sea Lantern', 'Glass Block', 'Honey Block', 3, 'Honey blocks reduce slide speed on their sides and change movement in platforming builds.', 16, false),
  ('piston-pushes-blocks', 'Which redstone block can push another block forward?', 'Observer', 'Dropper', 'Comparator', 'Piston', 3, 'Pistons are the classic redstone block for pushing and moving other blocks.', 17, true),
  ('scaffolding-climbs-fast', 'Which bamboo-based block lets builders climb up and down quickly?', 'Target Block', 'Bookshelf', 'Scaffolding', 'Grindstone', 2, 'Scaffolding is perfect for tall builds because it is easy to climb and remove.', 18, true),
  ('slime-block-bounces-fall', 'Landing on which block can bounce a player back upward?', 'Moss Block', 'Gravel', 'Bookshelf', 'Slime Block', 3, 'Slime blocks can bounce entities instead of ending the fall normally.', 19, false),
  ('stairs-make-corners', 'Which block type can automatically change shape to make neat corners?', 'Pressure Plates', 'Stairs', 'Glass Panes', 'Fence Gates', 1, 'Stairs connect into corner shapes, which helps roofs and pathways look smoother.', 20, true),
  ('blast-furnace-smelts-ore-fast', 'Which block turns raw gold into ingots twice as fast as usual?', 'Cartography Table', 'Smoker', 'Stonecutter', 'Blast Furnace', 3, 'This block only works on ores and metal gear, and in exchange it runs at double speed.', 21, true),
  ('compass-needs-redstone', 'Which item sits in the center of the compass recipe, surrounded by iron?', 'Sugar', 'Glowstone Dust', 'Blaze Powder', 'Redstone Dust', 3, 'Four iron ingots around one redstone dust make a compass that points to the world spawn.', 22, true),
  ('hopper-moves-items-between-containers', 'Which block pulls items out of a chest placed above it?', 'Observer', 'Hopper', 'Barrel', 'Dropper', 1, 'A hopper sucks items from the container above and pushes them wherever its spout points.', 23, true),
  ('smithing-table-upgrades-netherite', 'Where do you upgrade diamond gear to netherite?', 'Anvil', 'Blast Furnace', 'Enchanting Table', 'Smithing Table', 3, 'It combines diamond gear, a netherite ingot and a netherite upgrade template.', 24, true),
  ('smoker-cooks-food-faster', 'Which block cooks food twice as fast as a furnace?', 'Campfire', 'Smoker', 'Stonecutter', 'Blast Furnace', 1, 'A smoker only handles food, and in exchange it cooks at double speed.', 25, true),
  ('campfire-calms-bees', 'What can you place under a beehive so bees stay calm when you take honey?', 'Torch', 'Bell', 'Campfire', 'Lantern', 2, 'Smoke rising from a campfire below the hive calms the bees, so they don''t attack when you harvest.', 26, true),
  ('composter-makes-bone-meal', 'Which block turns extra seeds and plants into bone meal?', 'Grindstone', 'Smoker', 'Cauldron', 'Composter', 3, 'Each plant you put in has a chance to raise the level, and a full composter gives one bone meal.', 27, true),
  ('silk-touch-moves-bee-nest', 'Which enchantment lets you pick up a bee nest with the bees still inside?', 'Fortune', 'Efficiency', 'Unbreaking', 'Silk Touch', 3, 'Silk Touch makes the nest drop as an item that keeps its bees; without it a bee nest drops nothing.', 28, true),
  ('cat-scares-creepers', 'Which pet makes creepers run away from it?', 'Wolf', 'Cat', 'Axolotl', 'Horse', 1, 'Creepers are afraid of cats and ocelots, so a cat near your base keeps them away.', 29, true),
  ('charged-creeper-lightning', 'What turns a normal creeper into a charged creeper?', 'Full moon', 'Lightning strike', 'Splash potion', 'Redstone signal', 1, 'Lightning striking near a creeper charges it, making its explosion much stronger.', 30, true),
  ('smite-hurts-undead', 'Which sword enchantment adds extra damage only to undead mobs?', 'Knockback', 'Looting', 'Smite', 'Sharpness', 2, 'Smite boosts damage against undead like zombies and skeletons, while Sharpness helps against all mobs.', 31, true),
  ('wither-skeleton-drops-skull', 'How many wither skeleton skulls do you need to summon the Wither?', '5', '4', '1', '3', 3, 'The Wither is built from 4 soul sand or soul soil blocks with 3 wither skeleton skulls on top.', 32, true),
  ('eye-of-ender-finds-stronghold', 'Which item helps you locate a stronghold before entering the End?', 'Ender Pearl', 'Clock', 'Fire Charge', 'Eye of Ender', 3, 'Eyes of Ender fly toward a stronghold, helping players find the portal room path.', 33, true),
  ('magma-block-pulls-down-bubbles', 'Which block makes a water bubble column pull players downward?', 'Prismarine', 'Sea Lantern', 'Magma Block', 'Soul Sand', 2, 'A magma block creates a downward bubble column, while soul sand pushes upward.', 34, true),
  ('observer-detects-updates', 'Which redstone component detects a block update and outputs a pulse?', 'Observer', 'Composter', 'Daylight Sensor', 'Bell', 0, 'Observers detect changes in the block they face and emit a short redstone pulse.', 35, false),
  ('respawn-anchor-charged-glowstone', 'What item is used to charge a respawn anchor?', 'Redstone Dust', 'Glowstone', 'Quartz', 'Blaze Rod', 1, 'Respawn anchors are charged with glowstone.', 36, false),
  ('warped-forest-many-endermen', 'Which Nether biome is one of the safest places to find lots of endermen?', 'Soul Sand Valley', 'Warped Forest', 'Crimson Forest', 'Basalt Deltas', 1, 'Warped forests have lots of endermen and fewer dangerous piglins and hoglins than some other Nether biomes.', 37, true),
  ('campfire-cooks-without-fuel', 'Which block cooks food without needing any fuel?', 'Campfire', 'Furnace', 'Crafting Table', 'Smoker', 0, 'A lit campfire cooks up to four food items for free, while furnaces and smokers burn fuel.', 38, true),
  ('honey-bottle-clears-poison', 'Which item cures Poison without drinking milk?', 'Cookie', 'Apple', 'Honey Bottle', 'Spider Eye', 2, 'Drinking honey removes only Poison, so your good potion effects stay active.', 39, true),
  ('powder-snow-needs-leather-boots', 'Which boots let you walk on powder snow without sinking?', 'Diamond Boots', 'Chainmail Boots', 'Leather Boots', 'Iron Boots', 2, 'Only leather boots keep you on top of powder snow; other boots let you sink and freeze.', 40, true),
  ('pumpkin-stops-enderman-stare', 'What can you wear on your head to look at Endermen safely?', 'Carved Pumpkin', 'Turtle Shell', 'Chainmail Helmet', 'Leather Cap', 0, 'A carved pumpkin hides your gaze from Endermen, though it blocks part of your view.', 41, true),
  ('totem-of-undying-saves-once', 'Which rare item can save you from death one time?', 'Heart of the Sea', 'Nether Star', 'Golden Apple', 'Totem of Undying', 3, 'A held totem is used up to keep you alive at half a heart and grant healing effects.', 42, true),
  ('aqua-affinity-speeds-underwater-mining', 'Which helmet enchantment helps players mine faster underwater?', 'Infinity', 'Feather Falling', 'Aqua Affinity', 'Sharpness', 2, 'Aqua Affinity reduces the underwater mining penalty.', 43, false),
  ('channeling-needs-thunderstorm', 'Under what weather does Channeling call down lightning with a thrown trident?', 'Any cave', 'A snowstorm', 'A thunderstorm', 'A clear sunrise', 2, 'Channeling only calls lightning during a thunderstorm.', 44, false),
  ('efficiency-speeds-mining', 'What enchantment makes a mining tool break blocks faster?', 'Looting', 'Curse of Binding', 'Efficiency', 'Thorns', 2, 'Efficiency increases block-breaking speed on suitable tools.', 45, false),
  ('fortune-increases-ore-drops', 'Which enchantment can increase the amount dropped from many ores?', 'Respiration', 'Punch', 'Fortune', 'Knockback', 2, 'Fortune can increase drops from many mined resources.', 46, false),
  ('frost-walker-freezes-water', 'Which boot enchantment temporarily freezes water underfoot?', 'Soul Speed', 'Swift Sneak', 'Quick Charge', 'Frost Walker', 3, 'Frost Walker creates temporary ice as the wearer walks across water.', 47, false),
  ('golden-apple-cures-zombie-villager', 'What special item is used after Weakness to cure a zombie villager?', 'Golden Apple', 'Glow Berries', 'Enchanted Book', 'Totem of Undying', 0, 'Curing a zombie villager requires Weakness and then a golden apple.', 48, false),
  ('grindstone-removes-enchantments', 'Which block removes most enchantments from an item and gives back some experience?', 'Stonecutter', 'Beacon', 'Grindstone', 'Brewing Stand', 2, 'A grindstone can clean off most enchantments and return a little experience to the player.', 49, true),
  ('infinity-still-needs-one-arrow', 'What must stay in the inventory for Infinity to work on a bow?', 'A fishing rod', 'A bottle o'' enchanting', 'A shield', 'At least one arrow', 3, 'Infinity removes most arrow consumption, but one arrow still has to be present.', 50, false),
  ('looting-helps-mob-drops', 'Which sword enchantment can improve drops from mobs?', 'Riptide', 'Looting', 'Flame', 'Impaling', 1, 'Looting increases the chances or amount of certain mob drops.', 51, false),
  ('mending-repairs-with-xp', 'Which enchantment repairs an item when you collect experience?', 'Mending', 'Thorns', 'Punch', 'Aqua Affinity', 0, 'Mending is powerful because experience points can repair your favorite gear for you.', 52, true),
  ('protection-reduces-damage', 'Which armor enchantment broadly helps reduce incoming damage?', 'Lure', 'Silk Touch', 'Aqua Affinity', 'Protection', 3, 'Protection is a broad defensive enchantment for armor.', 53, false),
  ('silk-touch-drops-glass', 'Which enchantment lets glass drop itself instead of shattering?', 'Sharpness', 'Silk Touch', 'Respiration', 'Looting', 1, 'Silk Touch makes fragile blocks like glass drop themselves when mined.', 54, false),
  ('thorns-damages-attacker', 'When armor has Thorns, what can happen to an attacker?', 'It drops an emerald', 'It can take damage back', 'It changes profession', 'It heals instantly', 1, 'Thorns can damage attackers when they hit the wearer.', 55, false),
  ('unbreaking-reduces-durability-loss', 'Which enchantment helps tools and armor lose durability less often?', 'Depth Strider', 'Fire Aspect', 'Unbreaking', 'Sweeping Edge', 2, 'Unbreaking lowers the chance that a use will consume durability.', 56, false),
  ('weaponsmith-uses-grindstone', 'Which villager job uses a grindstone as its job-site block?', 'Cleric', 'Weaponsmith', 'Toolsmith', 'Armorer', 1, 'The grindstone belongs to the weaponsmith, who focuses on swords and axes.', 57, true),
  ('golden-apple-gives-absorption', 'Which food gives you extra Absorption hearts?', 'Dried Kelp', 'Pumpkin Pie', 'Beetroot Soup', 'Golden Apple', 3, 'A golden apple gives Absorption and Regeneration, great before a tough fight.', 58, true),
  ('totem-must-be-held-in-hand', 'Where must a Totem of Undying be to save you?', 'In an armor slot', 'In your inventory', 'In a chest', 'In your hand', 3, 'The totem only works in your main hand or off-hand, not in your bag.', 59, true),
  ('milk-removes-bad-omen', 'Which item clears Bad Omen before you reach a village?', 'Suspicious Stew', 'Honey Bottle', 'Golden Apple', 'Milk Bucket', 3, 'Milk removes Bad Omen, so you can enter a village without starting a raid.', 60, true),
  ('bed-explodes-in-nether-survival', 'What happens if you try to sleep in a bed in the Nether?', 'Night is skipped', 'It explodes', 'Nothing happens', 'Spawn point is set', 1, 'Beds explode in the Nether and the End, so use a respawn anchor there instead.', 61, true),
  ('zombie-breaks-door-on-hard', 'On Hard difficulty, which mob can break down wooden doors?', 'Enderman', 'Creeper', 'Zombie', 'Skeleton', 2, 'On Hard, zombies can smash wooden doors, so use iron doors or block the entrance.', 62, true),
  ('sleep-prevents-phantom-spawns', 'After how many nights without sleep can phantoms start to spawn?', '10', '1', '3', '5', 2, 'Phantoms can appear once you go three in-game days without sleeping or dying.', 63, true),
  ('respawn-anchor-sets-nether-spawn', 'Which block lets you reappear in the Nether after dying?', 'Beacon', 'Respawn Anchor', 'Furnace', 'Lodestone', 1, 'Each glowstone adds a charge, and every respawn at the anchor uses one up.', 64, true),
  ('ender-pearl-teleports-player', 'Which thrown item teleports you to where it lands?', 'Egg', 'Ender Pearl', 'Snowball', 'Trident', 1, 'An ender pearl moves you to its landing spot but costs a bit of health.', 65, true),
  ('magma-block-pulls-downward', 'What is the highest fall, in blocks, that does no damage?', '3', '2', '5', '8', 0, 'A 3-block fall is safe, but from 4 blocks and higher you start losing health.', 66, true),
  ('soul-sand-pushes-upward', 'Under water, which block makes a bubble column that lifts you up?', 'Magma Block', 'Gravel', 'Soul Sand', 'Obsidian', 2, 'Soul sand creates rising bubble columns, handy for fast water elevators.', 67, true),
  ('glass-pane-from-glass-blocks', 'How many glass panes do six glass blocks make?', '6', '8', '16', '12', 2, 'Six glass blocks become sixteen panes, which makes panes a cheap way to glaze big windows.', 68, true),
  ('blast-furnace-not-for-food', 'Which of these blocks can''t cook raw food?', 'Smoker', 'Furnace', 'Blast Furnace', 'Campfire', 2, 'A blast furnace only smelts ores, raw metal and metal gear, so food has to go elsewhere.', 69, true),
  ('smoker-not-for-ores', 'Which of these won''t a smoker cook?', 'Potato', 'Raw Cod', 'Raw Iron', 'Raw Beef', 2, 'A smoker works only on food, so raw iron needs a furnace or blast furnace.', 70, true),
  ('cartography-table-expands-maps-crafting', 'In a cartography table, what do you add to a map to zoom it out?', 'Compass', 'Glass Pane', 'Ink Sac', 'Paper', 3, 'One sheet of paper zooms the map out a level, showing a wider area in less detail.', 71, true),
  ('brewing-stand-makes-potions-crafting', 'Which item, with three cobblestone, crafts a brewing stand?', 'Blaze Rod', 'Iron Ingot', 'Blaze Powder', 'Stick', 0, 'The blaze rod becomes the stand''s pole, so you must defeat a blaze before you can brew.', 72, true),
  ('stonecutter-chooses-stone-shapes', 'How many stone slabs does a stonecutter make from one stone block?', '2', '1', '8', '3', 0, 'One block splits into two slabs, the same ratio as crafting but without needing three blocks at once.', 73, true),
  ('anvil-can-break-from-use', 'Which workstation gets damaged with use and can finally break?', 'Grindstone', 'Anvil', 'Cartography Table', 'Smithing Table', 1, 'Each use has a 12% chance to damage an anvil, and after its third damage stage it breaks.', 74, true),
  ('loom-simplifies-banner-patterns', 'Besides planks, which item do you need to craft a loom?', 'Wool', 'Iron Ingot', 'String', 'Leather', 2, 'Two string placed above two planks make a loom.', 75, true),
  ('obsidian-needed-for-enchanting-table', 'Besides diamonds and a book, which block crafts an enchanting table?', 'Basalt', 'Obsidian', 'Block of Coal', 'Deepslate', 1, 'Four obsidian, two diamonds and a book make it, so you need a diamond pickaxe first.', 76, true),
  ('redstone-needed-for-clock', 'Which item surrounds redstone dust in the clock recipe?', 'Iron Ingot', 'Emerald', 'Gold Ingot', 'Copper Ingot', 2, 'Four gold ingots around redstone make a clock, while iron in the same shape makes a compass.', 77, true),
  ('obsidian-needs-diamond-pickaxe', 'To mine obsidian and actually collect it, which tool tier or better is required?', 'Shears', 'Wooden Pickaxe', 'Diamond Pickaxe', 'Stone Pickaxe', 2, 'Obsidian can only be collected with a diamond pickaxe or better.', 78, false),
  ('deepslate-mines-slower-than-stone', 'Compared with normal stone, which deep-layer block takes longer to mine?', 'Sand', 'Wool', 'Deepslate', 'Dirt', 2, 'Deepslate is slower to mine than ordinary stone.', 79, false),
  ('glowstone-drops-dust-when-broken', 'Broken in the Nether, which glowing block usually drops glowstone dust instead of itself?', 'Glowstone', 'Basalt', 'Soul Sand', 'Netherrack', 0, 'Glowstone usually breaks into glowstone dust rather than dropping the full block.', 80, false),
  ('nether-quartz-ore-drops-quartz', 'In the Nether, which white-speckled ore block drops Nether Quartz?', 'Nether Quartz Ore', 'Iron Ore', 'Coal Ore', 'Emerald Ore', 0, 'Nether quartz ore is the Nether block that drops Nether Quartz.', 81, false),
  ('copper-oxidizes-green-over-time', 'After a long time outside, which building metal slowly changes toward green?', 'Copper', 'Iron', 'Quartz', 'Gold', 0, 'Copper blocks oxidize over time and change color toward green.', 82, false),
  ('scaffolding-extends-outward-with-support', 'Which builder block can extend outward several spaces before it needs support below?', 'Glass Pane', 'Fence', 'Scaffolding', 'Ladder', 2, 'Scaffolding can extend outward a limited distance before it needs support from below.', 83, false),
  ('trapdoor-makes-ladder-hatch', 'For a ceiling hatch above a ladder, which thin hinged block is often used?', 'Trapdoor', 'Carpet', 'Rail', 'Bell', 0, 'Trapdoors are commonly used for hatches because they open and close in a thin space.', 84, false),
  ('fence-connects-into-lines', 'Placed next to more of its own kind, which pen block connects into long lines automatically?', 'Fence', 'Lantern', 'Glass', 'Torch', 0, 'Fences automatically connect to each other to form pens and boundaries.', 85, false),
  ('piston-cannot-push-obsidian', 'Powered by redstone, which common block can a normal piston not push?', 'Wool', 'Obsidian', 'Sand', 'Dirt', 1, 'Normal pistons cannot push obsidian.', 86, false),
  ('slime-block-drags-neighboring-blocks', 'When a piston moves it, which bouncy block can pull neighboring blocks along too?', 'Ice', 'Coal Block', 'Glass', 'Slime Block', 3, 'Slime blocks can stick to nearby blocks and drag them when pushed or pulled.', 87, false),
  ('tropical-fish-breeds-axolotls', 'What do you feed axolotls to make them breed?', 'Bucket of Cod', 'Bucket of Pufferfish', 'Bucket of Tropical Fish', 'Bucket of Salmon', 2, 'Axolotls only take live tropical fish in a bucket, and you get the empty water bucket back.', 88, true),
  ('slimeball-breeds-frogs', 'Which item do you use to breed frogs?', 'Spider Eye', 'Slimeball', 'Kelp', 'Magma Cream', 1, 'Frogs eat small slimes in the wild, so slimeballs make them breed and lay frogspawn in water.', 89, true),
  ('beetroot-crafts-into-soup', 'How many beetroots do you need to craft one beetroot soup?', '8', '6', '3', '4', 1, 'Beetroot soup takes 6 beetroots and a bowl, a lot of crops for one meal.', 90, true),
  ('striders-breed-with-warped-fungus', 'Which item do you use to breed striders?', 'Crimson Fungus', 'Red Mushroom', 'Nether Wart', 'Warped Fungus', 3, 'Striders love warped fungus: it breeds them, and on a stick it lets you steer one across lava.', 91, true),
  ('turtles-breed-with-seagrass', 'Which plant do you feed turtles to breed them?', 'Lily Pad', 'Sugar Cane', 'Kelp', 'Seagrass', 3, 'Turtles eat seagrass; a fed turtle swims to its home beach and lays eggs in the sand.', 92, true),
  ('foxes-breed-with-sweet-berries', 'Which food do you use to breed foxes?', 'Sweet Berries', 'Melon Slice', 'Beetroot', 'Apple', 0, 'Foxes love berries: both sweet berries and glow berries make them breed.', 93, true),
  ('potato-smelts-into-baked-potato', 'Which of these crops becomes a better food when cooked in a furnace?', 'Carrot', 'Potato', 'Pumpkin', 'Beetroot', 1, 'Smelting a potato gives a baked potato, which restores much more hunger than a raw one.', 94, true),
  ('flower-turns-stew-suspicious', 'Besides a bowl and two mushrooms, what is needed to craft suspicious stew?', 'Spider Eye', 'Flower', 'Sugar', 'Wheat', 1, 'The flower decides the stew''s hidden effect, for example a dandelion restores hunger.', 95, true),
  ('cake-uses-three-milk-buckets', 'How many milk buckets does one cake recipe need?', '1', '4', '2', '3', 3, 'A cake uses a whole top row of milk buckets, and the empty buckets go back into your inventory.', 96, true),
  ('nether-wart-grows-on-soul-sand', 'Which block must nether wart be planted on?', 'Farmland', 'Netherrack', 'Soul Soil', 'Soul Sand', 3, 'Nether wart grows only on soul sand, so brewers bring soul sand home to farm it.', 97, true),
  ('pumpkin-needs-empty-space-beside-stem', 'What light level do crops need at least to keep growing?', '9', '15', '4', '12', 0, 'Crops need light level 9 or more, so an underground farm needs torches or lamps nearby.', 98, true),
  ('cactus-breaks-when-side-touches-block', 'Which plant breaks if a solid block is placed right next to it?', 'Wheat', 'Bamboo', 'Sugar Cane', 'Cactus', 3, 'A cactus pops off as an item when any side touches a solid block, which is how cactus farms work.', 99, true),
  ('tamed-wolf-attacks-hostiles', 'Which hostile mob will a tamed wolf refuse to attack?', 'Witch', 'Skeleton', 'Creeper', 'Zombie', 2, 'Tamed wolves help fight most mobs but never attack creepers, so you must deal with those yourself.', 100, true),
  ('piglin-barters-with-gold', 'Which Nether mob trades you random items for gold ingots?', 'Piglin', 'Wither Skeleton', 'Zombified Piglin', 'Hoglin', 0, 'Piglins take a thrown gold ingot, inspect it and then toss back a random item.', 101, true),
  ('zombified-piglin-angers-group', 'Which neutral Nether mob makes its whole group attack if you hit just one?', 'Enderman', 'Magma Cube', 'Zombified Piglin', 'Strider', 2, 'Hitting one zombified piglin angers every one nearby, so a single swing can start a big fight.', 102, true),
  ('bees-swarm-after-nest-broken', 'Dancing near a playing jukebox, which mob duplicates when given an amethyst shard?', 'Bee', 'Allay', 'Vex', 'Parrot', 1, 'A dancing allay given an amethyst shard makes a copy of itself, then needs 5 minutes before it can do it again.', 103, true),
  ('iron-golem-hits-hard-if-provoked', 'How many iron blocks do you need to build an iron golem?', '6', '3', '5', '4', 3, 'Place 4 iron blocks in a T shape and put a carved pumpkin on top to create an iron golem.', 104, true),
  ('evoker-summons-vexes', 'Which illager casts spells and summons flying vexes?', 'Witch', 'Evoker', 'Pillager', 'Vindicator', 1, 'Evokers summon vexes and fang traps, and they drop a Totem of Undying when defeated.', 105, true),
  ('guardian-fires-laser-beam', 'Which ocean monument mob attacks with a charging laser beam?', 'Drowned', 'Guardian', 'Squid', 'Pufferfish', 1, 'Guardians lock on with a beam that charges up and then deals damage, even through water.', 106, true),
  ('endermite-can-spawn-from-pearl', 'Which tiny hostile mob can appear when a thrown ender pearl lands?', 'Silverfish', 'Cave Spider', 'Vex', 'Endermite', 3, 'Each thrown ender pearl has a 5% chance to spawn an endermite.', 107, true),
  ('bane-of-arthropods-vs-spiders', 'Which enchantment deals extra damage to spiders, bees and silverfish?', 'Bane of Arthropods', 'Fire Aspect', 'Sharpness', 'Smite', 0, 'Bane of Arthropods hurts bug-like mobs more and also slows them down.', 108, true),
  ('totem-works-from-hand-slot', 'Which weapon hits harder the farther you fall before striking?', 'Axe', 'Trident', 'Mace', 'Crossbow', 2, 'A mace adds bonus damage based on how far you fell, so players strike with it after a big jump.', 109, true),
  ('strength-potion-boosts-melee', 'Which potion makes your melee hits deal more damage?', 'Potion of Invisibility', 'Potion of Leaping', 'Potion of Slow Falling', 'Potion of Strength', 3, 'Strength adds bonus damage to every melee hit, which helps a lot in boss fights.', 110, true),
  ('twelve-eyes-activate-portal', 'To fill every frame slot and activate an End portal, how many Eyes of Ender are needed?', 'Eight', 'Twelve', 'Sixteen', 'Ten', 1, 'An End portal frame has twelve slots, one for each Eye of Ender.', 111, false),
  ('chorus-fruit-teleports-randomly', 'Eaten in the End or elsewhere, which food may teleport the player randomly?', 'Chorus Fruit', 'Golden Carrot', 'Glow Berries', 'Cookie', 0, 'Chorus fruit randomly teleports the player after it is eaten.', 112, false),
  ('dragon-breath-caught-in-bottle', 'Collected from a dragon attack cloud, which item is gathered with a glass bottle?', 'Potion of Healing', 'Honey Bottle', 'Dragon''s Breath', 'Bottle o'' Enchanting', 2, 'Dragon''s Breath can be bottled from lingering dragon attack clouds.', 113, false),
  ('elytra-found-in-end-ship', 'At the end of certain End City ships, which gliding item can be found?', 'Shield', 'Trident', 'Totem of Undying', 'Elytra', 3, 'Elytra are found in End City ships and let players glide.', 114, false),
  ('crying-obsidian-crafts-anchor', 'For crafting a respawn anchor, which purple block is required?', 'Crying Obsidian', 'Netherrack', 'Smooth Stone', 'End Stone', 0, 'Crying Obsidian is a key ingredient in the respawn anchor recipe.', 115, false),
  ('warped-fungus-scares-hoglins', 'To keep hoglins away from a path or camp, which fungus item can be useful?', 'Crimson Fungus', 'Glow Lichen', 'Red Mushroom', 'Warped Fungus', 3, 'Hoglins are afraid of warped fungus, which can help players stay safer in the Nether.', 116, false),
  ('blue-ice-makes-fast-boat-road', 'For extremely fast boat travel tunnels, which slippery block is often used?', 'Cobblestone', 'Sand', 'Blue Ice', 'Wool', 2, 'Blue ice is very slippery and is used in high-speed boat paths, including in the Nether.', 117, false),
  ('repeater-adds-redstone-delay', 'Clicked through several settings, which component can add delay to a redstone signal?', 'Bell', 'Repeater', 'Lectern', 'Comparator', 1, 'Repeaters can refresh signals and also add adjustable delay.', 118, false),
  ('target-block-rewards-accurate-hit', 'Hit near the bullseye, which block outputs a stronger signal for better aim?', 'Piston', 'Target Block', 'Button', 'Pressure Plate', 1, 'A target block outputs stronger redstone power when hit closer to the center.', 119, false),
  ('daylight-sensor-reads-sky-light', 'Watching the sun above, which sensor block can power day-and-night circuits?', 'Tripwire Hook', 'Stonecutter', 'Observer', 'Daylight Sensor', 3, 'Daylight sensors measure sky light and are useful for automatic day/night circuits.', 120, false)
) as v(content_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, sort_order, is_active)
where pack.slug = 'minecraft-en-hard'
on conflict (pack_id, content_id) do update set
  prompt = excluded.prompt,
  option_a = excluded.option_a,
  option_b = excluded.option_b,
  option_c = excluded.option_c,
  option_d = excluded.option_d,
  correct_option = excluded.correct_option,
  explanation = excluded.explanation,
  sort_order = excluded.sort_order,
  is_active = excluded.is_active;

insert into public.question_packs (category_id, locale, age_band, difficulty, title, slug, is_active)
select id, 'ru', '8-12', 'easy', 'MineMind ru easy', 'minecraft-ru-easy', true
from public.quiz_categories
where slug = 'minecraft'
on conflict (slug) do update set is_active = true, title = excluded.title;

insert into public.questions (pack_id, content_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, sort_order, is_active)
select pack.id, v.content_id, v.prompt, v.option_a, v.option_b, v.option_c, v.option_d, v.correct_option, v.explanation, v.sort_order, v.is_active
from public.question_packs pack
cross join (values
  ('badlands-has-terracotta', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. Класичним знаком якого біома є теракотові пагорби? За цією ситуацією визнач правильну місцевість або споруду.', 'Болото', 'Рівнини', 'Безплідні землі', 'Засніжені рівнини', 2, 'Безплідні землі легко впізнати за шарами теракоти та рельєфом, схожим на месу. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 1, false),
  ('bamboo-jungle-has-bamboo', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. У записнику гравця є така польова підказка: Який біом найімовірніше заповнений бамбуком? За цією ситуацією визнач правильну місцевість або споруду.', 'Бамбукові джунглі', 'Замерзлий океан', 'Темні глибини', 'Рівнини', 0, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 2, false),
  ('beach-is-sandy-shore', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. У записнику гравця є така польова підказка: Який біом зазвичай утворює піщану смугу вздовж океану? За цією ситуацією визнач правильну місцевість або споруду.', 'Меса', 'Пляж', 'Лука', 'Річка', 1, 'Пляжі зазвичай утворюють піщані береги вздовж океанів та інших великих водойм. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 3, false),
  ('cherry-grove-has-pink-trees', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. У записнику гравця є така польова підказка: Який біом виділяється рожевими вишневими деревами? За цією ситуацією визнач правильну місцевість або споруду.', 'Незерська пустка', 'Болото', 'Вишневий гай', 'Скелястий берег', 2, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 4, false),
  ('desert-has-no-rain', 'В каком жарком биоме не идёт дождь?', 'Равнины', 'Река', 'Лес', 'Пустыня', 3, 'Пустыни остаются сухими, поэтому обычного дождя там не бывает.', 5, true),
  ('jungle-has-vines', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. У записнику гравця є така польова підказка: Де гравець знайде високі дерева та багато ліан? За цією ситуацією визнач правильну місцевість або споруду.', 'Пустеля', 'Замерзлий океан', 'Джунглі', 'Грибні поля', 2, 'Джунглі відомі високими деревами, густим листям і великою кількістю ліан. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 6, false),
  ('mushroom-fields-has-giant-mushrooms', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. У записнику гравця є така польова підказка: Який біом відомий гігантськими грибами замість звичайних дерев? За цією ситуацією визнач правильну місцевість або споруду.', 'Засніжені рівнини', 'Грибні поля', 'Савана', 'Бамбукові джунглі', 1, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 7, false),
  ('ocean-mostly-water', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. Якщо біом здебільшого складається з відкритих водойм, яким біомом він, імовірно, буде? За цією ситуацією визнач правильну місцевість або споруду.', 'Савана', 'Океан', 'Тайга', 'Безплідні землі', 1, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 8, false),
  ('plains-open-grassland', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. У записнику гравця є така польова підказка: Який біом варто шукати гравцеві, який хоче широкі відкриті луки? За цією ситуацією визнач правильну місцевість або споруду.', 'Темні глибини', 'Базальтові дельти', 'Вишневий гай', 'Рівнини', 3, 'Рівнини відкриті й порослі травою, тому там зручно будувати й пересуватися. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 9, false),
  ('river-cuts-through-land', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. У записнику гравця є така польова підказка: Який біом часто виглядає як звивиста смуга води, що прорізає суходіл? За цією ситуацією визнач правильну місцевість або споруду.', 'Річка', 'Гай', 'Пустеля', 'Грибні поля', 0, 'Річки тягнуться довгими водними руслами крізь інші ділянки звичайного світу. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 10, false),
  ('savanna-has-acacia-trees', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. У записнику гравця є така польова підказка: Де гравець найчастіше очікує знайти дерева акації? За цією ситуацією визнач правильну місцевість або споруду.', 'Савана', 'Темний ліс', 'Замерзла річка', 'Грибні поля', 0, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 11, false),
  ('snowy-plains-has-snow', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. У записнику гравця є така польова підказка: Який біом зазвичай покритий снігом? За цією ситуацією визнач правильну місцевість або споруду.', 'Засніжені рівнини', 'Мангрове болото', 'Джунглі', 'Пустеля', 0, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 12, false),
  ('swamp-has-lily-pads', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. У записнику гравця є така польова підказка: Який біом славиться мілководдям і багатьма лататтями? За цією ситуацією визнач правильну місцевість або споруду.', 'Безплідні землі', 'Болото', 'Савана', 'Засніжені рівнини', 1, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 13, false),
  ('taiga-has-spruce', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. Які дерева особливо поширені в тайговому біомі? За цією ситуацією визнач правильну місцевість або споруду.', 'Акація', 'Мангровий ліс', 'Ялина', 'Вишня', 2, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 14, false),
  ('village-has-villagers', 'В какой структуре часто есть жители, кровати и поля с культурами?', 'Кораблекрушение', 'Деревня', 'Разрушенный портал', 'Заброшенная шахта', 1, 'Деревни полезно находить в начале, потому что там часто есть укрытие, еда и торговля.', 15, true),
  ('cobblestone-from-stone', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. Коли камінь видобувають кайлом, який блок зазвичай випадає? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Цегла', 'Гравій', 'Глина', 'Кругляк', 3, 'Зі звичайного каменю зазвичай випадає кругляк, якщо не діють особливі умови на кшталт Шовкового дотику. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 16, false),
  ('glass-is-see-through', 'Сквозь какой блок легко смотреть и хорошо делать окна?', 'Булыжник', 'Терракота', 'Стекло', 'Шерсть', 2, 'Стекло пропускает свет и позволяет видеть наружу, при этом закрывая базу.', 17, true),
  ('obsidian-from-water-and-lava', 'Какой блок образуется, когда вода касается источника лавы?', 'Глина', 'Обсидиан', 'Базальт', 'Кирпичи', 1, 'Источник лавы становится обсидианом, когда на него попадает вода.', 18, true),
  ('planks-build-starter-house', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. У записнику гравця є така польова підказка: Який блок багато гравців виготовляють із колод для початкового будинку? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Дерев''яні дошки', 'Вовняний килим', 'Шибка', 'Редстоуновий пил', 0, 'Дошки — один із перших будівельних матеріалів, які гравці роблять із колод. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 19, false),
  ('sand-falls-with-gravity', 'Какой блок падает вниз, если под ним нет опоры?', 'Дубовые доски', 'Книжная полка', 'Каменные кирпичи', 'Песок', 3, 'Песок является гравитационным блоком, поэтому падает, когда исчезает блок под ним.', 20, true),
  ('coal-fuels-furnace', 'Какой предмет чаще всего используют как топливо для печи?', 'Песок', 'Уголь', 'Булыжник', 'Нить', 1, 'Один уголь горит достаточно долго, чтобы переплавить 8 предметов.', 21, true),
  ('crafting-table-basics', 'Какой блок даёт сетку 3×3 для создания инструментов и предметов?', 'Сундук', 'Верстак', 'Печь', 'Кровать', 1, 'В инвентаре есть только сетка 2×2, поэтому для больших рецептов вроде инструментов нужен верстак.', 22, true),
  ('furnace-smelts-raw-iron', 'Какой блок превращает рудное железо в слитки, если добавить топливо?', 'Бочка', 'Печь', 'Компостница', 'Наковальня', 1, 'Печь сжигает топливо и переплавляет руду, поэтому из рудного железа выходят слитки.', 23, true),
  ('planks-from-logs', 'Сколько железных слитков нужно, чтобы скрафтить железный блок?', '6', '9', '4', '8', 1, 'Девять слитков заполняют всю сетку 3×3, а блок можно снова разобрать на девять слитков.', 24, true),
  ('sticks-from-planks', 'Какой предмет из досок служит рукоятью в большинстве рецептов инструментов?', 'Лестница', 'Кнопка', 'Миска', 'Палка', 3, 'Две доски друг над другом дают четыре палки, а они нужны для инструментов и факелов.', 25, true),
  ('pickaxe-mines-stone', 'Какой инструмент нужен, чтобы из добытого камня что-то выпало?', 'Топор', 'Лопата', 'Кирка', 'Мотыга', 2, 'Камень, добытый рукой или другим инструментом, ничего не даёт, поэтому нужна кирка.', 26, true),
  ('carrots-breed-pigs', 'Какой едой можно разводить свиней?', 'Пшеница', 'Морковь', 'Ламинария', 'Красный гриб', 1, 'Свиньи любят корнеплоды: морковь, картофель и свёкла заставляют их размножаться, а пшеница нет.', 27, true),
  ('chickens-lay-eggs', 'Что курица сама оставляет каждые несколько минут?', 'Перо', 'Яйцо', 'Кожа', 'Семена пшеницы', 1, 'Курицы несут яйцо раз в 5–10 минут, а перья выпадают только когда курицу убивают.', 28, true),
  ('cow-drops-leather', 'Какое животное может выронить кожу?', 'Корова', 'Свинья', 'Овца', 'Курица', 0, 'Коровы дают кожу и сырую говядину, так что ферма коров даёт и еду, и кожу для книг и брони.', 29, true),
  ('sheep-give-wool', 'Какое животное можно остричь, чтобы получить шерсть?', 'Коза', 'Корова', 'Свинья', 'Овца', 3, 'Остриженная овца снова обрастает шерстью, когда поест траву, так что даёт шерсть снова и снова.', 30, true),
  ('wheat-grows-from-seeds', 'Из травы может выпасть семя. Какая культура из него вырастет?', 'Морковь', 'Кактус', 'Сахарный тростник', 'Пшеница', 3, 'Из травы выпадают семена пшеницы, поэтому пшеница обычно первая культура, которую сажает новичок.', 31, true),
  ('bone-meal-speeds-growth', 'Какой предмет ускоряет рост посевов, если использовать его на них?', 'Бумага', 'Костная мука', 'Порох', 'Сахар', 1, 'Костная мука сразу продвигает посев на одну или несколько стадий роста, так что ждать не нужно.', 32, true),
  ('bucket-collects-cow-milk', 'Что нужно использовать на корове, чтобы набрать молока?', 'Бутылочка', 'Миска', 'Ведро', 'Ножницы', 2, 'Молоко — жидкость, как вода, поэтому его носят в ведре; ведро молока ещё и снимает эффекты зелий.', 33, true),
  ('hoe-makes-farmland', 'Какой инструмент превращает землю в пашню?', 'Кирка', 'Мотыга', 'Ножницы', 'Лопата', 1, 'Семена можно сажать только на пашню, так что вспахать землю мотыгой — первый шаг любой фермы.', 34, true),
  ('creeper-explodes', 'Какой враждебный моб шипит перед тем, как взорваться?', 'Крипер', 'Зомби', 'Скелет', 'Паук', 0, 'Крипер тихо подкрадывается, шипит и взрывается, разрушая блоки и раня игрока.', 35, true),
  ('large-slime-splits', 'Какой зелёный прыгающий моб после победы делится на маленькие копии?', 'Слизень', 'Ведьма', 'Крипер', 'Эндермен', 0, 'Большой слизень распадается на несколько маленьких, а средние делятся ещё раз.', 36, true),
  ('skeleton-uses-bow', 'Какой частый враждебный моб стреляет в тебя из лука?', 'Крипер', 'Скелет', 'Зомби', 'Слизень', 1, 'Скелеты атакуют издалека, поэтому щит или укрытие очень помогают.', 37, true),
  ('spider-climbs-walls', 'Какой враждебный моб умеет лазать по отвесным стенам?', 'Паук', 'Эндермен', 'Крипер', 'Зомби', 0, 'Пауки лазают по вертикальным поверхностям, так что обычная стена их не остановит.', 38, true),
  ('zombies-burn-in-day', 'Кто из этих мобов загорается под прямыми лучами солнца?', 'Паук', 'Зомби', 'Крипер', 'Ведьма', 1, 'Зомби горят днём, если не стоят в тени или воде и не носят шлем.', 39, true),
  ('button-short-redstone-pulse', 'У Незері, Краї та редстоуні помилка швидко коштує ресурсів, тому треба знати базову взаємодію наперед. У записнику гравця є така польова підказка: Який маленький вхідний блок при натисканні зазвичай подає лише короткий редстоун-імпульс? За цією ситуацією обери компонент, ресурс або правило прогресії, яке спрацює.', 'Книжкова шафа', 'Піч', 'Кнопка', 'Скриня', 2, 'Кнопка подає короткий редстоун-сигнал лише на мить після натискання. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 40, false),
  ('flint-and-steel-lights-portal', 'У Незері, Краї та редстоуні помилка швидко коштує ресурсів, тому треба знати базову взаємодію наперед. У записнику гравця є така польова підказка: Який інструмент найчастіше використовують, щоб запалити портал у Незер? За цією ситуацією обери компонент, ресурс або правило прогресії, яке спрацює.', 'Кресало', 'Ножиці', 'Компас', 'Підзорна труба', 0, 'Кресалом найчастіше запалюють рамку порталу в Незер. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 41, false),
  ('nether-portal-needs-obsidian', 'Какой блок обычно используют для рамки портала в Незер?', 'Камень', 'Песчаник', 'Обсидиан', 'Медный блок', 2, 'Большинство порталов в Незер строят из обсидиана, потому что он держит рамку портала.', 42, true),
  ('redstone-dust-carries-power', 'Какая пыль переносит редстоун-сигнал между механизмами?', 'Порох', 'Сахар', 'Редстоуновая пыль', 'Пыль светокамня', 2, 'Редстоуновая пыль соединяет переключатели и механизмы, чтобы схема работала.', 43, true),
  ('soul-sand-slows-movement', 'У Незері, Краї та редстоуні помилка швидко коштує ресурсів, тому треба знати базову взаємодію наперед. У записнику гравця є така польова підказка: Який блок сповільнює рух, коли гравець проходить через нього? За цією ситуацією обери компонент, ресурс або правило прогресії, яке спрацює.', 'Гладкий камінь', 'Сухий лід', 'Вугільна руда', 'Пісок душ', 3, 'Пісок душ сповільнює рух і має особливі взаємодії з бульбашковими колонами. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 44, false),
  ('bed-sets-respawn', 'Какой предмет позволяет спать и задать точку возрождения?', 'Лодка', 'Сундук', 'Кровать', 'Флаг', 2, 'Сон в кровати пропускает ночь и ставит точку возрождения рядом с ней.', 45, true),
  ('cooked-food-better-hunger', 'Какая из этих еды лучше всего утоляет голод?', 'Ломтик арбуза', 'Жареная свинина', 'Сырая свинина', 'Яблоко', 1, 'Жареная свинина восстанавливает 8 единиц голода, намного больше сырого мяса, яблока или арбуза.', 46, true),
  ('eating-refills-hunger', 'Какая шкала заполняется, когда ты ешь?', 'Шкала воздуха', 'Шкала брони', 'Шкала опыта', 'Шкала голода', 3, 'Еда заполняет шкалу голода, а полная шкала позволяет бегать и восстанавливать здоровье.', 47, true),
  ('shelter-before-first-night', 'Что стоит построить до первой ночи, чтобы выжить?', 'Портал Незера', 'Укрытие', 'Маяк', 'Чародейский стол', 1, 'Враждебные мобы появляются в темноте, поэтому простое закрытое укрытие спасает в первую ночь.', 48, true),
  ('torch-lights-caves', 'Что игроки ставят, чтобы осветить темные пещеры?', 'Дверь', 'Табличка', 'Факел', 'Сундук', 2, 'Факелы дают свет, поэтому в пещере лучше видно, а монстров рядом появляется меньше.', 49, true),
  ('armorer-uses-blast-furnace', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. У записнику гравця є така польова підказка: Який робочий блок використовує селянин-броняр? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Плавильна піч', 'Картографічний стіл', 'Кафедра', 'Варильна стійка', 0, 'Бронярі використовують плавильні печі як свій робочий блок. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 50, false),
  ('barrel-makes-fisherman', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. У записнику гравця є така польова підказка: Яка робоча станція перетворює селянина на рибалку? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Ковадло', 'Каменеріз', 'Компостер', 'Бочка', 3, 'Бочка є робочим блоком рибалки. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 51, false),
  ('bookshelves-boost-enchanting', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. У записнику гравця є така польова підказка: Який сусідній блок допомагає столу зачарувань пропонувати сильніші чари? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Бочка', 'Книжкова шафа', 'Ліхтар', 'Мішень', 1, 'Книжкові шафи навколо столу зачарувань підсилюють доступні варіанти чарів. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 52, false),
  ('cartographer-uses-cartography-table', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. У записнику гравця є така польова підказка: На якому робочому блоці працюють картографи? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Стіл лучника', 'Плавильна піч', 'Компостер', 'Картографічний стіл', 3, 'Картографи працюють із картографічним столом. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 53, false),
  ('cauldron-makes-leatherworker', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. У записнику гравця є така польова підказка: Який блок допомагає селянину стати шкіряником? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Ткацький верстат', 'Коптильня', 'Казан', 'Бочка', 2, 'Казан найкраще відповідає описаній механіці села або зачарувань. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 54, false),
  ('composter-makes-farmer', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. У записнику гравця є така польова підказка: Який блок робочого місця дає селянину професію фермера? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Ткацький верстат', 'Ковадло', 'Коптильня', 'Компостер', 3, 'Компостер є блоком робочого місця, пов’язаним із професією фермера. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 55, false),
  ('emeralds-for-trading', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. У записнику гравця є така польова підказка: Який камінь є звичайною валютою в торгівлі селянинами? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Діамант', 'Аметистовий уламок', 'Кварц', 'Смарагд', 3, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 56, false),
  ('fletcher-uses-fletching-table', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. Селянин із яким робочим блоком стає лучником? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Бочка', 'Коптильня', 'Точило', 'Стіл лучника', 3, 'Стіл лучника є блоком робочого місця селянина-лучника. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 57, false),
  ('lapis-for-enchanting', 'Какой синий предмет нужен вместе с опытом, чтобы зачаровать снаряжение на столе?', 'Синий лёд', 'Алмаз', 'Призмарин', 'Лазурит', 3, 'Стол зачарований использует лазурит и уровни опыта для наложения чар.', 58, true),
  ('librarian-sells-books', 'Какая профессия жителя часто продаёт зачарованные книги?', 'Библиотекарь', 'Рыбак', 'Мясник', 'Фермер', 0, 'Библиотекари являются отличными торговцами, когда нужны полезные зачарования.', 59, true),
  ('loom-makes-shepherd', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. Коли селянин береться за ткацький верстат, яка професія з’являється? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Каменяр', 'Мʼясник', 'Вівчар', 'Священник', 2, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 60, false),
  ('nitwit-has-no-profession', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. У записнику гравця є така польова підказка: Який селянин не бере нормальної професії? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Лучник', 'Священник', 'Фермер', 'Нездара', 3, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 61, false),
  ('smoker-makes-butcher', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. У якому районі села створюється професія м’ясника? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Ткацький верстат', 'Коптильня', 'Дзвін', 'Ковальський стіл', 1, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 62, false),
  ('stonecutter-makes-mason', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. У записнику гравця є така польова підказка: Який робочий блок треба поставити, щоб безробітний селянин став майстром каменю? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Каменяр', 'Рибалка', 'Інструментальник', 'Вівчар', 0, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 63, false),
  ('villagers-sleep-in-beds', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. У записнику гравця є така польова підказка: Чим зазвичай користуються селяни вночі, коли село нормально працює? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Ліжка', 'Доменні печі', 'Вогнища', 'Вагонетки', 0, 'Ліжка найкраще відповідає описаній механіці села або зачарувань. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 64, false),
  ('hearts-show-player-health', 'Какие значки на экране показывают твое здоровье?', 'Значки брони', 'Пузырьки', 'Сердечки', 'Куриные ножки', 2, 'Каждое полное сердечко равно 2 единицам здоровья, а потеря всех означает смерть.', 65, true),
  ('armor-cuts-incoming-damage', 'Какое снаряжение уменьшает урон от ударов мобов?', 'Седло', 'Ножницы', 'Компас', 'Броня', 3, 'Каждая часть брони добавляет защиту, и чем ее больше, тем меньше урон от ударов.', 66, true),
  ('night-more-hostile-spawns', 'Какой предмет показывает, день сейчас или ночь, даже глубоко под землёй?', 'Часы', 'Компас', 'Возвратный компас', 'Подзорная труба', 0, 'Циферблат часов показывает солнце и луну, поэтому ты знаешь, когда безопасно выходить из укрытия.', 67, true),
  ('door-closes-base-entrance', 'Какой блок у входа в укрытие не пускает мобов, но пропускает тебя?', 'Цветочный горшок', 'Дверь', 'Картина', 'Ковёр', 1, 'Дверь ты открываешь и закрываешь сам, а большинство мобов через нее не пройдет.', 68, true),
  ('wool-used-for-bed', 'Какой блок — это вырезанная тыква с факелом внутри?', 'Морской фонарь', 'Светильник Джека', 'Светокамень', 'Фонарь', 1, 'Светильник Джека светит как факел, поэтому освещает укрытие и даже светит под водой.', 69, true),
  ('ladder-climbs-vertical-wall', 'Какое растение ранит тебя, когда ты его касаешься?', 'Мёртвый куст', 'Бамбук', 'Сахарный тростник', 'Кактус', 3, 'Кактус ранит всех, кто его коснётся, поэтому держи его подальше от дорожек и загонов.', 70, true),
  ('boat-travels-over-water', 'Какой предмет позволяет быстро пересечь реку или океан?', 'Поводок', 'Вагонетка', 'Лодка', 'Седло', 2, 'Лодка держится на воде и движется намного быстрее, чем ты плывешь.', 71, true),
  ('torch-brightens-dark-spaces', 'Что, кроме палки, нужно для крафта факела?', 'Кремень', 'Порох', 'Кость', 'Уголь', 3, 'Факел крафтят из угля или древесного угля над палкой.', 72, true),
  ('sneaking-prevents-edge-fall', 'Какое действие не дает тебе сойти с края блока?', 'Плавание', 'Подкрадывание', 'Планирование', 'Бег', 1, 'Когда крадешься, ты останавливаешься на краю блока, поэтому строить высоко безопаснее.', 73, true),
  ('bucket-picks-up-water-source', 'Какой предмет позволяет набрать блок-источник воды?', 'Ведро', 'Миска', 'Котёл', 'Цветочный горшок', 0, 'Пустое ведро набирает источник воды или лавы, чтобы поставить его в другом месте.', 74, true),
  ('chest-stores-home-items', 'Какой блок обычно крафтят, чтобы хранить дома много вещей?', 'Фонарь', 'Сундук', 'Кровать', 'Печь', 1, 'Сундук вмещает 27 стаков, а два рядом становятся большим двойным сундуком.', 75, true),
  ('bed-crafted-from-wool-and-planks', 'Какой предмет крафтят из трёх блоков шерсти и трёх досок?', 'Лодка', 'Кровать', 'Щит', 'Лестница', 1, 'Сон в кровати пропускает ночь и задаёт точку возрождения.', 76, true),
  ('furnace-crafted-from-cobblestone', 'Какой блок крафтят из восьми булыжников, выложенных кольцом?', 'Печь', 'Наковальня', 'Раздатчик', 'Бочка', 0, 'Восемь булыжников вокруг пустого центра дают печь для руды и еды.', 77, true),
  ('four-planks-make-crafting-table', 'Какой блок получается из четырёх досок в сетке 2×2 в инвентаре?', 'Бочка', 'Верстак', 'Книжная полка', 'Сундук', 1, 'Четыре доски квадратом дают верстак — первый шаг к большим рецептам.', 78, true),
  ('planks-work-as-furnace-fuel', 'Нет угля? Что из этого тоже можно сжечь в печи?', 'Доски', 'Камень', 'Стекло', 'Гравий', 0, 'Деревянные вещи горят в печи, и одна доска переплавляет полтора предмета.', 79, true),
  ('pickaxe-breaks-stone-faster', 'Какой инструмент быстрее всего рубит брёвна?', 'Ножницы', 'Топор', 'Лопата', 'Кирка', 1, 'Топор создан для дерева, поэтому брёвна и доски ломаются им гораздо быстрее.', 80, true),
  ('stone-drops-cobblestone', 'Сколько алмазов нужно, чтобы скрафтить алмазную кирку?', '3', '2', '5', '4', 0, 'Кирке нужны три единицы материала сверху и две палки под ними.', 81, true),
  ('iron-ingots-craft-bucket', 'Какой слиток нужен, чтобы скрафтить ведро?', 'Железный слиток', 'Незеритовый слиток', 'Золотой слиток', 'Медный слиток', 0, 'Три железных слитка в форме буквы V дают ведро для воды, лавы или молока.', 82, true),
  ('stone-next-tier-after-wood', 'Какой материал для инструментов идёт сразу после дерева?', 'Алмаз', 'Незерит', 'Железо', 'Камень', 3, 'Каменные инструменты требуют только булыжника и палок, а служат дольше деревянных.', 83, true),
  ('logs-turn-into-planks', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. У записнику гравця є така польова підказка: Який блок, зрізаний із дерева, зазвичай спершу перетворюють на дошки? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Вовна', 'Колода', 'Пісок', 'Гравій', 1, 'Колода — це той блок, який зазвичай спершу перетворюють на дошки. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 84, false),
  ('dirt-under-many-grass-blocks', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. У записнику гравця є така польова підказка: Який звичайний природний блок знаходиться під багатьма трав’яними блоками? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Скло', 'Мідь', 'Ґрунт', 'Вовна', 2, 'Поведінка блока в світі збігається з описаною будівельною ситуацією. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 85, false),
  ('clay-can-be-smelted-into-bricks', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. Зі ставків і річок який м’який блок можна переплавити на цеглу? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Гравій', 'Лід', 'Вугільна руда', 'Глина', 3, 'Глина — саме той блок чи предмет, що підходить до описаної властивости або будівельної ситуації. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 86, false),
  ('door-swings-open-for-houses', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. Для входу в будинок, який блок відкривається та закривається, як прості ворота? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Плита', 'Двері', 'Смолоскип', 'Килим', 1, 'Двері — саме той блок чи предмет, що підходить до описаної властивости або будівельної ситуації. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 87, false),
  ('fence-gate-opens-between-fences', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. Через який блок між двома огорожами можуть пройти гравці та тварини? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Ліхтар', 'Ворота паркану', 'Драбина', 'Шибка', 1, 'Ворота паркану — саме той блок чи предмет, що підходить до описаної властивости або будівельної ситуації. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 88, false),
  ('stairs-help-players-climb-builds', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. У записнику гравця є така польова підказка: Який фасонний блок найчастіше використовують, щоб простіше ходити по будівлі? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Килим', 'Сходи', 'Натискна плита', 'Вовна', 1, 'Сходи найкраще пасує до описаної поведінки блока або будівельного використання. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 89, false),
  ('glass-pane-makes-thin-window', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. У записнику гравця є така польова підказка: Що можуть розмістити гравці для більш тонкого вікна, ніж повні скляні блоки? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Шибка', 'Ліжко', 'Піч', 'Скриня', 0, 'Поведінка блока в світі збігається з описаною будівельною ситуацією. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 90, false),
  ('gravel-falls-like-sand', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. Як пісок, який пухкий блок падає вниз, якщо його ніщо не підтримує? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Скло', 'Кругляк', 'Гравій', 'Дубові дошки', 2, 'Гравій — саме той блок чи предмет, що підходить до описаної властивости або будівельної ситуації. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 91, false),
  ('flowing-lava-and-water-make-cobblestone', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. У записнику гравця є така польова підказка: Який блок зазвичай утворюється, коли текуча лава стикається з водою? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Кругляк', 'Глина', 'Обсидіан', 'Пісковик', 0, 'Кругляк найкраще пасує до описаної поведінки блока або будівельного використання. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 92, false),
  ('ice-can-melt-into-water', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. У записнику гравця є така польова підказка: Який замерзлий блок може розплавитися у воду під час сильного світла чи тепла? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Камінь', 'Лід', 'Скло', 'Вовна', 1, 'Поведінка блока в світі збігається з описаною будівельною ситуацією. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 93, false),
  ('wheat-breeds-cows-and-sheep', 'Какой культурой можно разводить коров и овец?', 'Морковь', 'Картофель', 'Свёкла', 'Пшеница', 3, 'Коровы, овцы и козы едят пшеницу, так что одно поле пшеницы прокормит большинство животных фермы.', 94, true),
  ('carrot-plants-more-carrots', 'Какую культуру сажают самим урожаем, без отдельных семян?', 'Морковь', 'Пшеница', 'Тыква', 'Свёкла', 0, 'У моркови, как и у картофеля, нет семян: сажаешь морковь и собираешь несколько новых.', 95, true),
  ('melon-block-grows-from-melon-stem', 'Какой блок урожая при разрушении даёт ломтики?', 'Тыква', 'Кактус', 'Арбуз', 'Сноп сена', 2, 'Блок арбуза распадается на 3–7 ломтиков, а тыква выпадает целым блоком.', 96, true),
  ('three-wheat-craft-bread', 'Во что превращается сырая говядина, если пожарить её в печи?', 'Жареная курица', 'Стейк', 'Жареная свинина', 'Жареная баранина', 1, 'Жареная говядина называется стейком и утоляет голод так же, как жареная свинина.', 97, true),
  ('bowl-carries-mushroom-stew', 'Что, кроме красного и коричневого грибов, нужно для тушёных грибов?', 'Ведро', 'Палка', 'Миска', 'Бутылочка', 2, 'Тушёные грибы подают в миске, и после еды пустая миска возвращается к тебе.', 98, true),
  ('hay-bale-stores-extra-wheat', 'Какой блок крафтят из девяти пшениц?', 'Блок мха', 'Блок сушёной ламинарии', 'Сноп сена', 'Белая шерсть', 2, 'Сноп сена вмещает девять пшениц в одном блоке, экономит место и кормит лошадей и лам.', 99, true),
  ('pandas-breed-with-bamboo', 'Каким растением кормят панд, чтобы они размножились?', 'Бамбук', 'Сахарный тростник', 'Пшеница', 'Ламинария', 0, 'Панды живут в бамбуковых джунглях и едят бамбук, поэтому именно он заставляет их размножаться.', 100, true),
  ('cow-makes-moo-sound', 'Какое морское существо даёт чернильные мешки?', 'Треска', 'Спрут', 'Дельфин', 'Черепаха', 1, 'Спруты дают чернильные мешки, из которых делают чёрный краситель и книгу и перо.', 101, true),
  ('sheep-can-be-sheared', 'Какой маленький летающий моб спит вниз головой в тёмных пещерах?', 'Попугай', 'Летучая мышь', 'Тихоня', 'Пчела', 1, 'Летучие мыши висят вниз головой под сводами пещер и порхают, когда рядом появляется игрок.', 102, true),
  ('bee-produces-honey', 'Какой маленький моб наполняет гнёзда и ульи мёдом?', 'Летучая мышь', 'Пчела', 'Попугай', 'Курица', 1, 'Пчёлы собирают пыльцу с цветов и несут домой, постепенно наполняя гнездо мёдом.', 103, true),
  ('wolf-can-be-tamed-as-pet', 'На каком приручённом животном можно ездить, надев на него седло?', 'Попугай', 'Волк', 'Лошадь', 'Кошка', 2, 'Приручённая лошадь под седлом везёт тебя и слушается управления — это быстрее, чем пешком.', 104, true),
  ('pig-likes-carrots', 'Какое животное можно приручить, скормив ему семена?', 'Кошка', 'Курица', 'Волк', 'Попугай', 3, 'Семена приручают попугая, и после этого он может сидеть у тебя на плече.', 105, true),
  ('shield-blocks-many-hits', 'Что, кроме палок, нужно для крафта лука?', 'Кожа', 'Перо', 'Нить', 'Шерсть', 2, 'Три палки и три нити дают лук, а нити проще всего добыть из пауков.', 106, true),
  ('sword-is-basic-melee-weapon', 'Какой предмет с верстака создан именно для ближнего боя?', 'Меч', 'Мотыга', 'Лопата', 'Ведро', 0, 'Меч — основное оружие ближнего боя, он бьёт сильнее мотыги или лопаты.', 107, true),
  ('bow-fires-arrows', 'Какое оружие натягивают, чтобы стрелять стрелами по далёким мобам?', 'Трезубец', 'Лук', 'Меч', 'Топор', 1, 'Лук позволяет атаковать с безопасного расстояния: чем дольше натягиваешь, тем сильнее выстрел.', 108, true),
  ('armor-reduces-attack-damage', 'Какой полный комплект брони защищает хуже всего?', 'Алмазная броня', 'Кожаная броня', 'Незеритовая броня', 'Железная броня', 1, 'Кожа — самая слабая броня, а алмаз и незерит защищают лучше всего.', 109, true),
  ('torches-help-stop-spawns', 'Какой меч наносит больше всего урона?', 'Алмазный меч', 'Каменный меч', 'Незеритовый меч', 'Железный меч', 2, 'Незерит — самый прочный материал, поэтому незеритовый меч бьёт сильнее алмазного и служит дольше.', 110, true),
  ('ender-pearl-drops-from-enderman', 'У Незері, Краї та редстоуні помилка швидко коштує ресурсів, тому треба знати базову взаємодію наперед. Перемога над ендерменом може викинути предмет, використаний пізніше для завершення прогресу? За цією ситуацією обери компонент, ресурс або правило прогресії, яке спрацює.', 'Призмариновий уламок', 'Перлина Ендера', 'Зірка Незеру', 'Стрижень іфрита', 1, 'Перлина Ендера найкраще відповідає описаній механіці редстоуну або вимірів. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 111, false),
  ('end-portal-opens-path-to-end', 'У Незері, Краї та редстоуні помилка швидко коштує ресурсів, тому треба знати базову взаємодію наперед. У записнику гравця є така польова підказка: Який портал переносить гравців у вимір дракона, коли його активовано? За цією ситуацією обери компонент, ресурс або правило прогресії, яке спрацює.', 'Портал Незеру', 'Зруйнований портал', 'Портал Енду', 'Лавовий басейн', 2, 'Саме портал Енду веде до виміру, де гравця чекає дракон Енду. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 112, false),
  ('ender-dragon-is-end-boss', 'У Незері, Краї та редстоуні помилка швидко коштує ресурсів, тому треба знати базову взаємодію наперед. У записнику гравця є така польова підказка: Який бос чекає на гравця на головному острові Енду? За цією ситуацією обери компонент, ресурс або правило прогресії, яке спрацює.', 'Ґаст', 'Боронитель', 'Дракон Енду', 'Візер', 2, 'У прогресії між вимірами або редстоун-механіці ця умова є вирішальною. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 113, false),
  ('stronghold-contains-end-portal', 'У Незері, Краї та редстоуні помилка швидко коштує ресурсів, тому треба знати базову взаємодію наперед. У записнику гравця є така польова підказка: Яка підземна споруда зазвичай містить кімнату з порталом Енду? За цією ситуацією обери компонент, ресурс або правило прогресії, яке спрацює.', 'Село', 'Фортеця', 'Стародавнє місто', 'Покинута шахта', 1, 'Портал Енду зазвичай знаходять у спеціальній кімнаті фортеці. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 114, false),
  ('end-stone-covers-end-islands', 'У Незері, Краї та редстоуні помилка швидко коштує ресурсів, тому треба знати базову взаємодію наперед. У записнику гравця є така польова підказка: Який блідий блок утворює основу багатьох островів на більшій частині Краю? За цією ситуацією обери компонент, ресурс або правило прогресії, яке спрацює.', 'Пісковик', 'Пісок душ', 'Камінь Енду', 'Обсидіан', 2, 'У прогресії між вимірами або редстоун-механіці ця умова є вирішальною. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 115, false),
  ('redstone-torch-provides-power', 'У Незері, Краї та редстоуні помилка швидко коштує ресурсів, тому треба знати базову взаємодію наперед. У записнику гравця є така польова підказка: Який блок, що світиться червоним на стіні або підлозі, працює як просте постійне джерело живлення? За цією ситуацією обери компонент, ресурс або правило прогресії, яке спрацює.', 'Багаття', 'Редстоуновий смолоскип', 'Ліхтар', 'Смолоскип душ', 1, 'Редстоуновий смолоскип постійно подає сигнал і є одним із базових компонентів редстоуну. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 116, false),
  ('pressure-plate-triggers-on-step', 'У Незері, Краї та редстоуні помилка швидко коштує ресурсів, тому треба знати базову взаємодію наперед. У записнику гравця є така польова підказка: Який плаский блок може активувати схему, коли на нього наступає гравець або моб? За цією ситуацією обери компонент, ресурс або правило прогресії, яке спрацює.', 'Шибка', 'Прапор', 'Квітковий горщик', 'Натискна плита', 3, 'Натискна плита активується, коли на неї стають, і подає редстоун-сигнал. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 117, false),
  ('piston-pushes-block-forward', 'У Незері, Краї та редстоуні помилка швидко коштує ресурсів, тому треба знати базову взаємодію наперед. У записнику гравця є така польова підказка: Який редстоун-блок може штовхнути інший блок уперед? За цією ситуацією обери компонент, ресурс або правило прогресії, яке спрацює.', 'Кафедра', 'Поршень', 'Повторювач', 'Спостерігач', 1, 'Поршень є класичним редстоун-блоком для штовхання інших блоків. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 118, false),
  ('strider-walks-on-lava', 'У Незері, Краї та редстоуні помилка швидко коштує ресурсів, тому треба знати базову взаємодію наперед. У записнику гравця є така польова підказка: Який верховий моб може ходити по поверхні лави в Незері? За цією ситуацією обери компонент, ресурс або правило прогресії, яке спрацює.', 'Кінь', 'Блукач', 'Піґлін', 'Іфрит', 1, 'Блукач може ходити по лаві, і гравець може осідлати його. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 119, false),
  ('warped-fungus-stick-steers-strider', 'У Незері, Краї та редстоуні помилка швидко коштує ресурсів, тому треба знати базову взаємодію наперед. У записнику гравця є така польова підказка: Який спеціальний предмет на палиці використовується для керування мандрівником? За цією ситуацією обери компонент, ресурс або правило прогресії, яке спрацює.', 'Морква на паличці', 'Повідець', 'Вудка', 'Химерний гриб на паличці', 3, 'У прогресії між вимірами або редстоун-механіці ця умова є вирішальною. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 120, false)
) as v(content_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, sort_order, is_active)
where pack.slug = 'minecraft-ru-easy'
on conflict (pack_id, content_id) do update set
  prompt = excluded.prompt,
  option_a = excluded.option_a,
  option_b = excluded.option_b,
  option_c = excluded.option_c,
  option_d = excluded.option_d,
  correct_option = excluded.correct_option,
  explanation = excluded.explanation,
  sort_order = excluded.sort_order,
  is_active = excluded.is_active;

insert into public.question_packs (category_id, locale, age_band, difficulty, title, slug, is_active)
select id, 'ru', '8-12', 'medium', 'MineMind ru medium', 'minecraft-ru-medium', true
from public.quiz_categories
where slug = 'minecraft'
on conflict (slug) do update set is_active = true, title = excluded.title;

insert into public.questions (pack_id, content_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, sort_order, is_active)
select pack.id, v.content_id, v.prompt, v.option_a, v.option_b, v.option_c, v.option_d, v.correct_option, v.explanation, v.sort_order, v.is_active
from public.question_packs pack
cross join (values
  ('amethyst-geode-underground', 'Плануючи маршрут за ресурсами, ти порівнюєш рельєф, рослини й структури, щоб не витратити день марно. Де зазвичай знаходять аметистові жеоди? На основі цього визнач правильну місцевість або споруду.', 'Під землею', 'Всередині болотяної хатини', 'На вершині села', 'У Кінцевому небі', 0, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 1, false),
  ('desert-temple-desert', 'Плануючи маршрут за ресурсами, ти порівнюєш рельєф, рослини й структури, щоб не витратити день марно. Який біом є звичайним домом для пустельного храму? На основі цього визнач правильну місцевість або споруду.', 'Пустеля', 'Вишневий гай', 'Болото', 'Тайга', 0, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 2, false),
  ('dripstone-caves-have-pointed-dripstone', 'Плануючи маршрут за ресурсами, ти порівнюєш рельєф, рослини й структури, щоб не витратити день марно. Загострений сталактит є ознакою якого печерного біома? На основі цього визнач правильну місцевість або споруду.', 'Пляж', 'Грибні поля', 'Сталактитові печери', 'Вишневий гай', 2, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 3, false),
  ('igloo-in-snowy-biomes', 'Какая холодная структура может появиться в снежных биомах?', 'Иглу', 'Храм джунглей', 'Крепость Незера', 'Пустынная пирамида', 0, 'Иглу подходят снежным местам и даже могут скрывать маленький сюрприз внизу.', 4, true),
  ('jungle-temple-jungle', 'Плануючи маршрут за ресурсами, ти порівнюєш рельєф, рослини й структури, щоб не витратити день марно. Де генерують храми в джунглях? На основі цього визнач правильну місцевість або споруду.', 'Джунглі', 'Засніжені схили', 'Лука', 'Океан', 0, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 5, false),
  ('lush-caves-have-glow-berries', 'Плануючи маршрут за ресурсами, ти порівнюєш рельєф, рослини й структури, щоб не витратити день марно. Який печерний біом відомий сяйними ягодами та пишними рослинами? На основі цього визнач правильну місцевість або споруду.', 'Базальтові дельти', 'Безплідні землі', 'Засніжені рівнини', 'Зарослі печери', 3, 'Зарослі печери відомі густою рослинністю, мохом і сяйними ягодами. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 6, false),
  ('mangrove-swamp-has-mud', 'Какой биом известен мангровыми деревьями и большим количеством грязи?', 'Замёрзший океан', 'Саванна', 'Бесплодные земли', 'Мангровое болото', 3, 'Мангровые болота выделяются мангровыми корнями, лягушками и грязной землёй.', 7, true),
  ('mineshaft-underground', 'Плануючи маршрут за ресурсами, ти порівнюєш рельєф, рослини й структури, щоб не витратити день марно. Де найчастіше шукати покинуті шахти з дерев’яними проходами, рейками й павутиною? На основі цього визнач правильну місцевість або споруду.', 'На грибних островах', 'Під землею', 'Всередині океанів', 'В небі', 1, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 8, false),
  ('ocean-monument-guardians', 'Какая океанская структура является домом для стражей?', 'Иглу', 'Крепость', 'Океанский монумент', 'Лесной особняк', 2, 'Океанские монументы — это подводные структуры, которые охраняют стражи и древние стражи.', 9, true),
  ('ocean-ruins-underwater', 'Плануючи маршрут за ресурсами, ти порівнюєш рельєф, рослини й структури, щоб не витратити день марно. Яка споруда зазвичай знаходиться під водою і часто складається з потертих кам’яних блоків? На основі цього визнач правильну місцевість або споруду.', 'Фортеця', 'Розбійницька застава', 'Підводні руїни', 'Лісовий маєток', 2, 'Підводні руїни — це затоплені структури, розкидані по океанах. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 10, false),
  ('pillager-outpost-has-pillagers', 'Плануючи маршрут за ресурсами, ти порівнюєш рельєф, рослини й структури, щоб не витратити день марно. Яка ворожа структура тісно асоціюється з грабіжниками? На основі цього визнач правильну місцевість або споруду.', 'Храм джунглів', 'Судові руїни', 'Океанічний монумент', 'Розбійницька застава', 3, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 11, false),
  ('shipwrecks-near-ocean', 'Плануючи маршрут за ресурсами, ти порівнюєш рельєф, рослини й структури, щоб не витратити день марно. Яка структура зазвичай зустрічається в океанічних районах? На основі цього визнач правильну місцевість або споруду.', 'Хатина відьми', 'Корабельна аварія', 'Лісовий маєток', 'Фортеця Незеру', 1, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 12, false),
  ('strongholds-underground', 'Плануючи маршрут за ресурсами, ти порівнюєш рельєф, рослини й структури, щоб не витратити день марно. Де зазвичай знаходяться опорні пункти, перш ніж гравці проникають у них? На основі цього визнач правильну місцевість або споруду.', 'Над океанами', 'На верхівках дерев', 'Всередині сіл', 'Під землею', 3, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 13, false),
  ('warm-ocean-has-coral', 'Плануючи маршрут за ресурсами, ти порівнюєш рельєф, рослини й структури, щоб не витратити день марно. З яким біомом найбільше пов’язані коралові рифи? На основі цього визнач правильну місцевість або споруду.', 'Замерзла річка', 'Теплий океан', 'Темні глибини', 'Тайга', 1, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 14, false),
  ('witch-hut-swamp', 'Плануючи маршрут за ресурсами, ти порівнюєш рельєф, рослини й структури, щоб не витратити день марно. Який біом асоціюється з хатинами відьом? На основі цього визнач правильну місцевість або споруду.', 'Болото', 'Безплідні землі', 'Савана', 'Пляж', 0, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 15, false),
  ('concrete-powder-hardens-in-water', 'У споруді треба врахувати форму, падіння, прозорість, сигнал або взаємодію блока з водою та інструментами. Що відбувається з бетонним порошком, коли він торкається води? На основі цього обери блок або будівельну поведінку, яка спрацює в грі.', 'Він перетворюється на бетон', 'Воно зникає', 'Він стає піском', 'Він росте вгору', 0, 'Бетонний порошок твердне після контакту з водою й перетворюється на бетон. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 16, false),
  ('fence-stops-animal-escape', 'У споруді треба врахувати форму, падіння, прозорість, сигнал або взаємодію блока з водою та інструментами. Який блок часто використовують для утримання тварин у загоні? На основі цього обери блок або будівельну поведінку, яка спрацює в грі.', 'Прапор', 'Скриня', 'Смолоскип', 'Паркан', 3, 'Паркани зручні для загонів, бо тварини не можуть просто пройти крізь них. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 17, false),
  ('ladder-climbs-wall', 'Какой блок помогает подняться прямо вверх по стене?', 'Ковёр', 'Лестница', 'Люк', 'Забор', 1, 'Лестницы крепятся к блокам и создают быстрый вертикальный путь для игрока.', 18, true),
  ('slab-is-half-block', 'Какой строительный элемент имеет высоту только половины полного блока?', 'Панель', 'Плита', 'Стена', 'Факел', 1, 'Плиты удобны для полов, крыш и более плавных форм, потому что имеют половинную высоту.', 19, true),
  ('trapdoor-covers-hole', 'У споруді треба врахувати форму, падіння, прозорість, сигнал або взаємодію блока з водою та інструментами. Який навісний блок стане в нагоді для перекриття невеликого отвору підлоги? На основі цього обери блок або будівельну поведінку, яка спрацює в грі.', 'Натискна плита', 'Драбина', 'Табличка', 'Люк', 3, 'Люк добре перекриває отвір у підлозі або стелі на один блок. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 20, false),
  ('charcoal-works-for-torches', 'Какой предмет кладут над палкой, чтобы скрафтить факел?', 'Древесный уголь', 'Кремень', 'Порох', 'Светокаменная пыль', 0, 'Факелу подходит уголь или древесный уголь, так что переплавленные брёвна выручат без руды.', 21, true),
  ('chest-needs-eight-planks', 'Сколько досок нужно, чтобы скрафтить сундук?', '9', '6', '7', '8', 3, 'Доски занимают все ячейки сетки 3×3, кроме центральной.', 22, true),
  ('sand-smelts-into-glass', 'Что получится, если переплавить песок в печи?', 'Стекло', 'Незерский кварц', 'Гравий', 'Глина', 0, 'Жар плавит песок в стекло — главный блок для окон.', 23, true),
  ('stonecutter-shapes-stone-builds', 'Какая станция делает из блока ступеньки, плиту или стену без верстака?', 'Точило', 'Камнерез', 'Ткацкий станок', 'Стол кузнеца', 1, 'Ты выбираешь нужную форму, а станция берёт по одному блоку, так что полный рецепт не нужен.', 24, true),
  ('bee-pollinates-crops', 'Какой моб ускоряет рост посевов после посещения цветов?', 'Кролик', 'Тихоня', 'Попугай', 'Пчела', 3, 'Пчела с пыльцой помогает расти посевам, над которыми летит, так что улей у фермы ускоряет её.', 25, true),
  ('water-keeps-farmland-hydrated', 'Какой блок поддерживает влажность пашни рядом?', 'Лава', 'Блок снега', 'Лёд', 'Вода', 3, 'Вода в пределах 4 блоков держит пашню влажной и тёмной, а на влажной пашне посевы растут быстрее.', 26, true),
  ('dry-farmland-becomes-dirt', 'Во что превращается сухая пашня, на которой ничего не посажено?', 'Гравий', 'Земля', 'Грязь', 'Песок', 1, 'Без воды и посевов пашня высыхает и снова становится землёй; прыжки по ней делают то же самое.', 27, true),
  ('kelp-grows-underwater', 'Какое растение растёт вверх, находясь полностью под водой?', 'Сахарный тростник', 'Ламинария', 'Бамбук', 'Кактус', 1, 'Ламинария растёт вверх сквозь блоки воды, поэтому отлично подходит для автоматической подводной фермы.', 28, true),
  ('bone-tames-wolf', 'Какой предмет нужно скормить дикому волку, чтобы приручить его?', 'Кожа', 'Перо', 'Нить', 'Кость', 3, 'Каждая кость может приручить волка, после чего он получает ошейник и следует за тобой.', 29, true),
  ('enderman-hurt-by-water', 'Какой моб получает урон от воды и дождя?', 'Паук', 'Ведьма', 'Зомби', 'Эндермен', 3, 'Вода ранит эндерменов, поэтому встать в воду — простой способ от них спастись.', 30, true),
  ('iron-golem-defends-village', 'Какой большой моб появляется в деревнях и отбивается от зомби?', 'Странствующий торговец', 'Снежный голем', 'Железный голем', 'Разбойник', 2, 'Железные големы охраняют крестьян и нападают на враждебных мобов в деревне.', 31, true),
  ('witch-throws-potions', 'Какой враждебный моб атакует, бросая взрывные зелья?', 'Всполох', 'Скелет', 'Утопленник', 'Ведьма', 3, 'Ведьмы бросают вредные зелья, а сами пьют зелья, чтобы лечиться.', 32, true),
  ('zombie-villager-cured', 'Какого моба можно вылечить слабостью и золотым яблоком?', 'Кадавр', 'Крестьянин-зомби', 'Зомби', 'Утопленник', 1, 'Крестьянин-зомби со слабостью после золотого яблока снова становится обычным крестьянином.', 33, true),
  ('pillager-fires-crossbow', 'Каким оружием атакует разбойник?', 'Трезубец', 'Арбалет', 'Топор', 'Лук', 1, 'Разбойники — это иллагеры, которые стреляют издалека из арбалетов.', 34, true),
  ('blaze-drops-rods', 'Какой моб даёт стержни, нужные для варочных стоек?', 'Магмовый куб', 'Ифрит', 'Эндермит', 'Скелет-иссушитель', 1, 'Ифриты дают стержни ифрита, важные для варки зелий и поиска Края.', 35, true),
  ('blaze-powder-for-eye-of-ender', 'Ти збираєш портал, сигнал або прогрес до Краю й маєш правильно поєднати ресурс, моба або компонент. Який інгредієнт із Незеру поєднують із перлиною Ендера, щоб створити Око Ендера? На основі цього обери компонент, ресурс або правило прогресії, яке спрацює.', 'Порох', 'Незерська цеглина', 'Вогняний порошок', 'Світяться чорнила', 2, 'У прогресії між вимірами або редстоун-механіці ця умова є вирішальною. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 36, false),
  ('ghast-shoots-fireballs', 'Какой большой летающий моб Незера стреляет огненными шарами?', 'Лавомер', 'Хоглин', 'Гаст', 'Пиглин', 2, 'Гасты летают в больших пространствах Незера и атакуют огненными шарами.', 37, true),
  ('lever-toggles-circuit', 'Какой простой переключатель может включать и выключать редстоун-схему?', 'Рычаг', 'Котёл', 'Рамка', 'Лестница', 0, 'Рычаг остаётся в выбранном положении после переключения, поэтому удобен для простого управления схемами.', 38, true),
  ('repeater-refreshes-signal', 'Ти збираєш портал, сигнал або прогрес до Краю й маєш правильно поєднати ресурс, моба або компонент. Який редстоун-компонент зазвичай використовують, щоб відновити ослаблений сигнал? На основі цього обери компонент, ресурс або правило прогресії, яке спрацює.', 'Драбина', 'Ліжко', 'Човен', 'Повторювач', 3, 'У прогресії між вимірами або редстоун-механіці ця умова є вирішальною. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 39, false),
  ('compass-points-to-world-spawn', 'Куда указывает обычный компас в обычном мире?', 'Портал Незера', 'Твоя кровать', 'Ближайшая деревня', 'Точка появления мира', 3, 'Обычный компас всегда указывает на точку появления мира, а не на кровать или базу.', 40, true),
  ('shield-blocks-attacks', 'Какой предмет можно поднять, чтобы блокировать стрелы и удары?', 'Железный шлем', 'Щит', 'Черепаший панцирь', 'Железный нагрудник', 1, 'Броня лишь снижает урон, а поднятый щит полностью блокирует большинство ударов спереди.', 41, true),
  ('sleep-skips-thunderstorm', 'Когда, кроме ночи, можно спать в кровати?', 'Во время грозы', 'В полдень', 'Во время снегопада', 'На рассвете', 0, 'Во время грозы достаточно темно для монстров, поэтому кровать работает даже днем.', 42, true),
  ('water-bucket-softens-falls', 'Какой предмет отменит урон от падения, если поставить его перед приземлением?', 'Ведро лавы', 'Удочка', 'Ведро молока', 'Ведро воды', 3, 'Приземление в воду отменяет урон от падения, поэтому вода перед ударом спасает.', 43, true),
  ('phantom-comes-after-no-sleep', 'Какой летающий моб нападает на игроков, что несколько ночей не спали?', 'Летучая мышь', 'Пчела', 'Фантом', 'Попугай', 2, 'Фантомы появляются в ночном небе над игроками, которые давно не спали.', 44, true),
  ('anvil-can-rename-items', 'Ти прокачуєш спорядження через торги й чари, тому маєш обрати станцію, ресурс або дію без зайвого рандому. Що корисного може зробити ковадло, крім ремонту й поєднання зачарувань? На основі цього обери професію, станцію, ресурс або зачарування без плутанини.', 'Змінювати біоми', 'Перейменовувати предмети', 'Переплавляти руди', 'Копіювати блоки', 1, 'Ковадло дає змогу не лише ремонтувати предмети, а й перейменовувати їх. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 45, false),
  ('anvil-combines-enchantments', 'Какой блок позволяет перенести зачарование с книги на инструмент?', 'Коптильня', 'Бочка', 'Наковальня', 'Кровать', 2, 'Наковальни используют, чтобы объединять предметы, переименовывать их и переносить чары с книг.', 46, true),
  ('bookshelves-need-air-gap', 'Ти прокачуєш спорядження через торги й чари, тому маєш обрати станцію, ресурс або дію без зайвого рандому. Щоб книжкова полиця живила стіл зачарування, що має залишатися між ними? На основі цього обери професію, станцію, ресурс або зачарування без плутанини.', 'Порожній блок повітря', 'Факел', 'Килим', 'Знак', 0, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 47, false),
  ('brewing-stand-makes-cleric', 'Ти прокачуєш спорядження через торги й чари, тому маєш обрати станцію, ресурс або дію без зайвого рандому. Селянин із якою робочою станцією стає священнослужителем? На основі цього обери професію, станцію, ресурс або зачарування без плутанини.', 'Каменеріз', 'Стіл лучника', 'Картографічний стіл', 'Варильна стійка', 3, 'Варильна стійка є блоком робочого місця священнослужителя. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 48, false),
  ('cartographer-sells-mansion-map', 'Ти прокачуєш спорядження через торги й чари, тому маєш обрати станцію, ресурс або дію без зайвого рандому. Хто може продати карту, яка допомагає гравцям знайти лісовий палац? На основі цього обери професію, станцію, ресурс або зачарування без плутанини.', 'Священник', 'Бібліотекар', 'Каменяр', 'Картограф', 3, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 49, false),
  ('cartographer-sells-ocean-map', 'Ти прокачуєш спорядження через торги й чари, тому маєш обрати станцію, ресурс або дію без зайвого рандому. Який селянин може продати карту, що веде до океанічного монумента? На основі цього обери професію, станцію, ресурс або зачарування без плутанини.', 'Мʼясник', 'Вівчар', 'Фермер', 'Картограф', 3, 'Картографи продають карти дослідника, які можуть вести до великих структур, зокрема океанічних монументів. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 50, false),
  ('curing-zombie-villager-lowers-prices', 'Ти прокачуєш спорядження через торги й чари, тому маєш обрати станцію, ресурс або дію без зайвого рандому. Після того як зомбі-селянин виліковується, що часто відбувається з його торговими цінами? На основі цього обери професію, станцію, ресурс або зачарування без плутанини.', 'Вони зникають назавжди', 'Вони стають випадковими біомами', 'Вони стають дешевшими', 'Вони перетворюються на ціни на ліжко', 2, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 51, false),
  ('enchanted-books-applied-with-anvil', 'Ти прокачуєш спорядження через торги й чари, тому маєш обрати станцію, ресурс або дію без зайвого рандому. Який блок використовують гравці, щоб застосувати зачаровану книгу на спорядження? На основі цього обери професію, станцію, ресурс або зачарування без плутанини.', 'Компостер', 'Дзвін', 'Ткацький верстат', 'Ковадло', 3, 'Ковадло найкраще відповідає описаній механіці села або зачарувань. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 52, false),
  ('enchanting-table-needs-xp-levels', 'Ти прокачуєш спорядження через торги й чари, тому маєш обрати станцію, ресурс або дію без зайвого рандому. Окрім лазуриту, на що ще витрачається стіл зачарування? На основі цього обери професію, станцію, ресурс або зачарування без плутанини.', 'Репутація села', 'Серця', 'Очки голоду', 'Рівні досвіду', 3, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 53, false),
  ('lectern-makes-librarian', 'Какой рабочий блок превращает безработного жителя в библиотекаря?', 'Кафедра', 'Компостер', 'Котёл', 'Плавильная печь', 0, 'Жители получают профессии от рабочих блоков рядом, и кафедра делает их библиотекарями.', 54, true),
  ('smithing-table-makes-toolsmith', 'Ти прокачуєш спорядження через торги й чари, тому маєш обрати станцію, ресурс або дію без зайвого рандому. Який блок робочого місця пов’язаний із професією коваля інструментів? На основі цього обери професію, станцію, ресурс або зачарування без плутанини.', 'Дзвін', 'Нотний блок', 'Ткацький верстат', 'Ковальський стіл', 3, 'Ковальський стіл є блоком робочого місця коваля інструментів. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 55, false),
  ('three-enchanting-choices', 'Ти прокачуєш спорядження через торги й чари, тому маєш обрати станцію, ресурс або дію без зайвого рандому. Скільки варіантів зачарування зазвичай показує стіл зачарування? На основі цього обери професію, станцію, ресурс або зачарування без плутанини.', '4', '1', '2', '3', 3, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 56, false),
  ('unemployed-villager-claims-job-block', 'Ти прокачуєш спорядження через торги й чари, тому маєш обрати станцію, ресурс або дію без зайвого рандому. Що може перетворити безробітного селянина на робітника? На основі цього обери професію, станцію, ресурс або зачарування без плутанини.', 'Тримає смарагд', 'Заявка на сусідній блок роботи', 'Боротьба з натовпом', 'Спить у Пустоті', 1, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 57, false),
  ('villager-needs-bed-to-breed', 'Ти прокачуєш спорядження через торги й чари, тому маєш обрати станцію, ресурс або дію без зайвого рандому. Що має бути в селі, щоб селяни успішно розмножувалися? На основі цього обери професію, станцію, ресурс або зачарування без плутанини.', 'Запасні ліжка', 'Басейни лави', 'Підставки для броні', 'Алмазні блоки', 0, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 58, false),
  ('villagers-restock-at-workstation', 'Ти прокачуєш спорядження через торги й чари, тому маєш обрати станцію, ресурс або дію без зайвого рандому. Куди зазвичай потрібен доступ селянину, щоб поповнити запаси торгів? На основі цього обери професію, станцію, ресурс або зачарування без плутанини.', 'Рецепт приготування', 'Маяк', 'Портал у Незер', 'Його робоча станція', 3, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 59, false),
  ('bread-easy-hunger-refill', 'Какую еду можно скрафтить всего из трёх пшениц?', 'Торт', 'Тыквенный пирог', 'Печенье', 'Хлеб', 3, 'Три пшеницы в ряд дают хлеб, а для печенья нужно какао, для торта и пирога яйца и сахар.', 60, true),
  ('milk-clears-most-effects', 'Какой напиток снимает все эффекты сразу?', 'Ведро молока', 'Бутылочка воды', 'Зелье исцеления', 'Бутылочка мёда', 0, 'Молоко снимает все эффекты, и хорошие, и плохие, а мёд убирает только отравление.', 61, true),
  ('rotten-flesh-emergency-food', 'Какой дроп зомби съедобен, но часто вызывает голод?', 'Картофель', 'Гнилая плоть', 'Морковь', 'Железный слиток', 1, 'Гнилая плоть с шансом 80% накладывает голод, поэтому ешь ее только в крайнем случае.', 62, true),
  ('air-bubbles-show-drowning', 'Какие значки под водой исчезают, прежде чем ты начнешь тонуть?', 'Значки брони', 'Шкала опыта', 'Куриные ножки', 'Пузырьки воздуха', 3, 'Пузырьки показывают запас воздуха; когда их нет, ты каждую секунду теряешь здоровье.', 63, true),
  ('spider-eye-causes-poison', 'Какая еда всегда отравляет, если ее съесть?', 'Сладкие ягоды', 'Паучий глаз', 'Гнилая плоть', 'Сырая курица', 1, 'Паучий глаз всегда дает отравление, а гнилая плоть и сырая курица лишь могут дать голод.', 64, true),
  ('torches-help-stop-indoor-spawns', 'Что мешает враждебным мобам появляться в твоем доме?', 'Факелы', 'Цветочные горшки', 'Картины', 'Рамки', 0, 'Враждебным мобам для появления нужна полная темнота, а факелы ее убирают.', 65, true),
  ('sleep-turns-world-to-morning', 'Что может помешать тебе спать в кровати ночью?', 'Монстры рядом', 'Надетая броня', 'Полный инвентарь', 'Мало сытости', 0, 'Ты не сможешь спать, пока враждебные мобы ближе примерно 8 блоков к кровати.', 66, true),
  ('roof-completes-first-shelter', 'Сколько минут реального времени длятся полные игровые сутки?', '60', '30', '20', '10', 2, 'Полные сутки длятся 20 минут, и примерно 7 из них — ночь, когда бродят враждебные мобы.', 67, true),
  ('water-puts-out-fire', 'Что быстро тушит огонь, когда ты горишь?', 'Песок', 'Шерсть', 'Вода', 'Гравий', 2, 'Вода сразу тушит огонь, поэтому держи ведро воды рядом с лавой.', 68, true),
  ('minecart-rides-on-rails', 'Какой транспорт создан для езды по рельсам?', 'Элитры', 'Лодка', 'Вагонетка', 'Поводок', 2, 'Вагонетка едет по рельсам и может везти игроков, мобов или предметы.', 69, true),
  ('wooden-sword-basic-weapon', 'Какой предмет крафтят из двух досок и одной палки?', 'Деревянный меч', 'Деревянный топор', 'Деревянная кирка', 'Деревянная лопата', 0, 'Две доски на палке дают меч, а кирке или топору нужно три доски и две палки.', 70, true),
  ('log-smelts-into-charcoal', 'Что получится, если переплавить бревно в печи?', 'Палка', 'Уголь', 'Доски', 'Древесный уголь', 3, 'Переплавленное бревно становится древесным углём, который горит так же долго, как обычный.', 71, true),
  ('cobblestone-smelts-into-stone', 'Что получится, если переплавить кактус в печи?', 'Сгусток слизи', 'Лаймовый краситель', 'Зелёный краситель', 'Сушёная ламинария', 2, 'Переплавленный кактус даёт зелёный краситель, а с белым красителем он становится лаймовым.', 72, true),
  ('dried-kelp-block-is-fuel', 'Какой из этих блоков можно сжечь в печи как топливо?', 'Блок сушёной ламинарии', 'Блок мёда', 'Блок слизи', 'Сноп сена', 0, 'Блок сушёной ламинарии переплавляет 20 предметов, так что ферма ламинарии даёт бесконечное топливо.', 73, true),
  ('anvil-renames-and-repairs', 'Какая станция позволяет переименовывать предметы и объединять зачарования?', 'Стол кузнеца', 'Наковальня', 'Стол картографа', 'Ткацкий станок', 1, 'Наковальня тратит уровни опыта, чтобы переименовать, починить или объединить зачарованные вещи.', 74, true),
  ('loom-adds-banner-patterns-crafting', 'Какая станция наносит узоры на флаги?', 'Точило', 'Коптильня', 'Ткацкий станок', 'Плавильная печь', 2, 'Станция соединяет флаг и краситель, чтобы добавлять узоры слой за слоем.', 75, true),
  ('grindstone-clears-enchantments', 'Какой блок крафтят, окружив печь четырьмя брёвнами?', 'Костёр', 'Бочка', 'Коптильня', 'Плавильная печь', 2, 'Четыре бревна вокруг печи дают коптильню, которая ещё и рабочий блок мясника.', 76, true),
  ('stone-pickaxe-mines-iron-ore', 'Какая самая слабая кирка уже может добыть железную руду?', 'Золотая кирка', 'Железная кирка', 'Каменная кирка', 'Деревянная кирка', 2, 'Деревянная и золотая кирки ломают железную руду без добычи, так что минимум — каменная.', 77, true),
  ('shears-need-iron-ingots', 'Какой предмет крафтят всего из двух железных слитков?', 'Котёл', 'Ведро', 'Вагонетка', 'Ножницы', 3, 'Два железных слитка по диагонали дают ножницы, а для ведра их нужно три.', 78, true),
  ('paper-from-sugar-cane', 'Во что крафтят сахарный тростник для книг и карт?', 'Глина', 'Бумага', 'Нить', 'Кожа', 1, 'Три сахарных тростника в ряд дают три листа бумаги для книг, карт и фейерверков.', 79, true),
  ('flint-and-steel-lights-portals', 'Какое топливо для печи переплавляет больше всего предметов?', 'Блок сушёной ламинарии', 'Ведро лавы', 'Угольный блок', 'Огненный стержень', 1, 'Ведро лавы переплавляет 100 предметов — больше, чем угольный блок (80), поэтому лава — отличное топливо.', 80, true),
  ('sandstone-crafted-from-sand', 'У споруді треба врахувати форму, падіння, прозорість, сигнал або взаємодію блока з водою та інструментами. Чотири піщані блоки створюють будівельний блок пустелі в сітці крафта? На основі цього обери блок або будівельну поведінку, яка спрацює в грі.', 'Лимпач', 'Камʼяна цегла', 'Кварцовий блок', 'Пісковик', 3, 'Пісковик — саме той блок чи предмет, що підходить до описаної властивости або будівельної ситуації. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 81, false),
  ('stone-bricks-crafted-from-stone', 'У споруді треба врахувати форму, падіння, прозорість, сигнал або взаємодію блока з водою та інструментами. Який класичний сірий будівельний блок складається з чотирьох кам’яних блоків? На основі цього обери блок або будівельну поведінку, яка спрацює в грі.', 'Гладкий кварц', 'Сходи з кругляку', 'Камʼяна цегла', 'Шибка', 2, 'Камʼяна цегла найкраще пасує до описаної поведінки блока або будівельного використання. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 82, false),
  ('axe-creates-stripped-log', 'У споруді треба врахувати форму, падіння, прозорість, сигнал або взаємодію блока з водою та інструментами. Який чистіший варіант деревини створює сокира, яка використовується на колоді? На основі цього обери блок або будівельну поведінку, яка спрацює в грі.', 'Тесана мідь', 'Обдираний журнал', 'Моховий блок', 'Точений камінь', 1, 'Обдираний журнал найкраще пасує до описаної поведінки блока або будівельного використання. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 83, false),
  ('smooth-stone-comes-from-second-smelt', 'У споруді треба врахувати форму, падіння, прозорість, сигнал або взаємодію блока з водою та інструментами. Якщо звичайний камінь знову виплавити, який більш гладкий блок вийде? На основі цього обери блок або будівельну поведінку, яка спрацює в грі.', 'Полірований андезит', 'Глибосланець', 'Тріснута кам''яна цегла', 'Гладкий камінь', 3, 'Поведінка блока в світі збігається з описаною будівельною ситуацією. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 84, false),
  ('terracotta-smelts-from-clay-block', 'У споруді треба врахувати форму, падіння, прозорість, сигнал або взаємодію блока з водою та інструментами. Коли глиняний блок плавлять, яким твердим будівельним блоком він стає? На основі цього обери блок або будівельну поведінку, яка спрацює в грі.', 'Теракота', 'Сніговий блок', 'Бетонні', 'Пісковик', 0, 'Теракота — саме той блок чи предмет, що підходить до описаної властивости або будівельної ситуації. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 85, false),
  ('pressure-plate-sends-signal-when-stepped-on', 'У споруді треба врахувати форму, падіння, прозорість, сигнал або взаємодію блока з водою та інструментами. Який плаский блок подає редстоун-сигнал, коли на нього наступає гравець або моб? На основі цього обери блок або будівельну поведінку, яка спрацює в грі.', 'Натискна плита', 'Квітковий горщик', 'Люк', 'Килим', 0, 'Поведінка блока в світі збігається з описаною будівельною ситуацією. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 86, false),
  ('glass-drops-nothing-without-silk-touch', 'У споруді треба врахувати форму, падіння, прозорість, сигнал або взаємодію блока з водою та інструментами. Який віконний блок, зламаний звичайним інструментом, зазвичай нічого не падає? На основі цього обери блок або будівельну поведінку, яка спрацює в грі.', 'Скло', 'Кругляк', 'Ґрунт', 'Драбина', 0, 'Поведінка блока в світі збігається з описаною будівельною ситуацією. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 87, false),
  ('leaves-decay-without-nearby-log', 'У споруді треба врахувати форму, падіння, прозорість, сигнал або взаємодію блока з водою та інструментами. Якщо їх немає біля колод, що часто відбувається з природним листям після зрізу дерева? На основі цього обери блок або будівельну поведінку, яка спрацює в грі.', 'Вони стають вовною', 'Вони перетворюються на камінь', 'Вони розкладаються', 'Вони загоряються автоматично', 2, 'Вони розкладаються найкраще пасує до описаної поведінки блока або будівельного використання. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 88, false),
  ('sponge-soaks-up-water', 'У споруді треба врахувати форму, падіння, прозорість, сигнал або взаємодію блока з водою та інструментами. Який блок, поміщений у воду, вбирає сусідні блоки джерела води? На основі цього обери блок або будівельну поведінку, яка спрацює в грі.', 'Теракота', 'Вовна', 'Губка', 'Корінна порода', 2, 'Губка найкраще пасує до описаної поведінки блока або будівельного використання. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 89, false),
  ('unsupported-scaffolding-breaks', 'У споруді треба врахувати форму, падіння, прозорість, сигнал або взаємодію блока з водою та інструментами. Якщо знизу немає опори в межах діапазону, який високий будівельний блок зрештою зламається? На основі цього обери блок або будівельну поведінку, яка спрацює в грі.', 'Скло', 'Бочка', 'Підмостки', 'Паркан', 2, 'Підмостки — саме той блок чи предмет, що підходить до описаної властивости або будівельної ситуації. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 90, false),
  ('potatoes-grow-from-potatoes', 'Какая культура при сборе иногда даёт ядовитую версию себя?', 'Свёкла', 'Морковь', 'Сладкие ягоды', 'Картофель', 3, 'Созревший картофель с небольшим шансом даёт ещё и ядовитый картофель, который есть опасно.', 91, true),
  ('sugar-cane-needs-water-nearby', 'Какое растение можно посадить только на блок рядом с водой?', 'Бамбук', 'Сахарный тростник', 'Кактус', 'Сладкие ягоды', 1, 'Сахарному тростнику нужна вода рядом с блоком, на котором он стоит, поэтому он растёт у рек.', 92, true),
  ('egg-is-needed-for-cake', 'Что, кроме молока, сахара и пшеницы, входит в рецепт торта?', 'Кожа', 'Перо', 'Яйцо', 'Бутылочка мёда', 2, 'Торт — это 3 ведра молока, 2 сахара, 3 пшеницы и 1 яйцо, так что нужны и куры, и коровы.', 93, true),
  ('sugar-completes-pumpkin-pie', 'Тыквенный пирог крафтят из тыквы, яйца и чего ещё?', 'Сахар', 'Какао-бобы', 'Пшеница', 'Ведро молока', 0, 'Тыквенный пирог — это только тыква, яйцо и сахар из тростника, без молока и пшеницы.', 94, true),
  ('seeds-breed-chickens', 'Каким предметом разводят кур?', 'Яблоко', 'Пшеница', 'Хлеб', 'Семена пшеницы', 3, 'Куры едят семена, а не пшеницу; подойдут любые семена, включая тыквенные, арбузные и свекольные.', 95, true),
  ('golden-carrot-breeds-rabbits', 'Каким цветком можно разводить кроликов?', 'Мак', 'Одуванчик', 'Синий василёк', 'Ромашка', 1, 'Кролики размножаются от моркови, золотой моркови или одуванчика — жёлтого цветка, который они едят.', 96, true),
  ('golden-apple-breeds-horses', 'Какая еда заставляет двух приручённых лошадей размножиться?', 'Золотое яблоко', 'Сахар', 'Яблоко', 'Пшеница', 0, 'Лошади размножаются только от золотых яблок или золотой моркови; яблоки, сахар и пшеница их лишь лечат.', 97, true),
  ('cocoa-beans-grow-on-jungle-logs', 'На какое бревно можно посадить какао-бобы?', 'Берёзовое бревно', 'Дубовое бревно', 'Бревно джунглевого дерева', 'Мангровое бревно', 2, 'Плоды какао растут сбоку на брёвнах джунглевого дерева — тех же деревьях, на которых висят в джунглях.', 98, true),
  ('glass-bottle-collects-honey', 'Каким предметом набирают мёд из полного улья?', 'Котёл', 'Бутылочка', 'Ведро', 'Миска', 1, 'Мёд набирают в пустую бутылочку, и бутылочка мёда ещё и лечит отравление.', 99, true),
  ('shears-collect-honeycomb', 'Каким инструментом собирают соты из полного улья?', 'Ножницы', 'Лопата', 'Топор', 'Мотыга', 0, 'Ножницы срезают 3 сот с полного улья или гнезда, а из них делают свечи и вощат медь.', 100, true),
  ('cocoa-beans-craft-cookies', 'Какой ингредиент кладут между двумя пшеницами, чтобы скрафтить печенье?', 'Какао-бобы', 'Сахар', 'Свёкла', 'Яйцо', 0, 'Две пшеницы с какао-бобами посередине дают 8 печений, так что ферма какао стоит того.', 101, true),
  ('goat-can-ram-players', 'Какой горный моб может внезапно протаранить тебя и сбросить со скалы?', 'Кролик', 'Овца', 'Коза', 'Лама', 2, 'Козы живут в горах и иногда разгоняются на игрока, сталкивая его с обрыва.', 102, true),
  ('llama-spits-when-angry', 'Какое животное плюётся в мобов и игроков, которые на него нападают?', 'Лошадь', 'Панда', 'Коза', 'Лама', 3, 'Ламы защищаются плевками, а в волков плюются, едва их увидят.', 103, true),
  ('bee-dies-after-stinging', 'Какой моб погибает вскоре после того, как кого-то ужалит?', 'Эндермит', 'Фантом', 'Пчела', 'Пещерный паук', 2, 'Ужалив, пчела теряет жало и погибает примерно через минуту.', 104, true),
  ('polar-bear-protects-cub', 'Какое животное снежных биомов нападает, если подойти к его детёнышу?', 'Белый медведь', 'Лисица', 'Коза', 'Кролик', 0, 'Взрослые белые медведи нейтральны, но нападают на игрока рядом со своими детёнышами.', 105, true),
  ('drowned-can-throw-trident', 'Какой подводный моб-нежить может бросить в тебя трезубец?', 'Скелет', 'Утопленник', 'Зомби', 'Кадавр', 1, 'Некоторые утопленники держат трезубец и бросают его; только с них он может выпасть.', 106, true),
  ('ghast-launches-fireballs', 'Какой моб снежных биомов стреляет стрелами, дающими Замедление?', 'Скелет', 'Зимогор', 'Кадавр', 'Разбойник', 1, 'Зимогоры — ледяные скелеты снежных биомов, а их стрелы замедляют тебя.', 107, true),
  ('arrows-needed-for-bow', 'Какой предмет становится наконечником в рецепте стрелы?', 'Гравий', 'Кость', 'Кремень', 'Кусочек железа', 2, 'Стрелы крафтят из кремня, палки и пера; кремень выпадает из гравия.', 108, true),
  ('golden-apple-gives-extra-hearts', 'Какой предмет крафтят из шести досок и одного железного слитка?', 'Арбалет', 'Бочка', 'Щит', 'Ведро', 2, 'Шесть досок и железный слиток сверху дают щит, который блокирует большинство атак спереди.', 109, true),
  ('potion-of-healing-restores-health', 'Какое зелье мгновенно возвращает потерянные сердца?', 'Зелье огнестойкости', 'Зелье исцеления', 'Зелье стремительности', 'Зелье ночного зрения', 1, 'Исцеление действует сразу, в отличие от регенерации, которая восстанавливает сердца постепенно.', 110, true),
  ('end-crystal-heals-dragon', 'Ти збираєш портал, сигнал або прогрес до Краю й маєш правильно поєднати ресурс, моба або компонент. Який предмет, що стоїть на обсидіанових стовпах, відновлює здоров''я дракона? На основі цього обери компонент, ресурс або правило прогресії, яке спрацює.', 'Маяк', 'Кристал Енду', 'Морський ліхтар', 'Якір відродження', 1, 'У прогресії між вимірами або редстоун-механіці ця умова є вирішальною. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 111, false),
  ('dragon-egg-appears-after-fight', 'Ти збираєш портал, сигнал або прогрес до Краю й маєш правильно поєднати ресурс, моба або компонент. Який рідкісний трофейний блок з’явиться на порталі виходу після перемоги над драконом? На основі цього обери компонент, ресурс або правило прогресії, яке спрацює.', 'Маяк', 'Яйце дракона', 'Провідник', 'Зірка Незеру', 1, 'Яйце дракона найкраще відповідає описаній механіці редстоуну або вимірів. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 112, false),
  ('shulker-causes-levitation', 'Ти збираєш портал, сигнал або прогрес до Краю й маєш правильно поєднати ресурс, моба або компонент. Який ворожий моб у містах Енду накладає левітацію своїми снарядами? На основі цього обери компонент, ресурс або правило прогресії, яке спрацює.', 'Піглін', 'Шалкер', 'Слизень', 'Іфрит', 1, 'Шалкери стріляють снарядами, які накладають ефект левітації. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 113, false),
  ('fire-resistance-helps-in-lava', 'Ти збираєш портал, сигнал або прогрес до Краю й маєш правильно поєднати ресурс, моба або компонент. Ефект якого зілля особливо корисний для перетину небезпечних лавових ділянок? На основі цього обери компонент, ресурс або правило прогресії, яке спрацює.', 'Нічне бачення', 'Повільне падіння', 'Вогнестійкість', 'Везіння', 2, 'У прогресії між вимірами або редстоун-механіці ця умова є вирішальною. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 114, false),
  ('lodestone-guides-special-compass', 'Ти збираєш портал, сигнал або прогрес до Краю й маєш правильно поєднати ресурс, моба або компонент. На який блок може вказувати намагнічений компас у вимірах, де звичайний компас не працює? На основі цього обери компонент, ресурс або правило прогресії, яке спрацює.', 'Ковальський стіл', 'Магнетит', 'Маяк', 'Дзвін', 1, 'Магнетит прив’язує до себе компас і дає йому напрямок у вимірах, де звичайний компас не працює. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 115, false),
  ('respawn-anchor-sets-spawn-in-nether', 'Ти збираєш портал, сигнал або прогрес до Краю й маєш правильно поєднати ресурс, моба або компонент. Який блок після заряджання дозволяє встановити точку відродження в Незері? На основі цього обери компонент, ресурс або правило прогресії, яке спрацює.', 'Верстак', 'Програвач', 'Багаття', 'Якір відродження', 3, 'Якір відродження після заряджання світлокаменем дозволяє відроджуватися в Незері. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 116, false),
  ('soul-speed-helps-on-soul-sand', 'Ти збираєш портал, сигнал або прогрес до Краю й маєш правильно поєднати ресурс, моба або компонент. Яке зачарування прискорює рух по піску душ і ґрунту душ? На основі цього обери компонент, ресурс або правило прогресії, яке спрацює.', 'Швидкість душ', 'Грабунок', 'Невагомість', 'Дихання', 0, 'У прогресії між вимірами або редстоун-механіці ця умова є вирішальною. Тут важливо застосувати правило до конкретної ситуації, а не впізнати окреме слово.', 117, false),
  ('comparator-reads-container-fullness', 'Ти збираєш портал, сигнал або прогрес до Краю й маєш правильно поєднати ресурс, моба або компонент. Який редстоун-компонент зчитує, наскільки заповнений контейнер? На основі цього обери компонент, ресурс або правило прогресії, яке спрацює.', 'Компаратор', 'Люк', 'Кнопка', 'Поршень', 0, 'Компаратор найкраще відповідає описаній механіці редстоуну або вимірів. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 118, false),
  ('sticky-piston-pulls-block-back', 'Ти збираєш портал, сигнал або прогрес до Краю й маєш правильно поєднати ресурс, моба або компонент. Який тип поршня після втягування може потягнути блок назад? На основі цього обери компонент, ресурс або правило прогресії, яке спрацює.', 'Липкий поршень', 'Спостерігач', 'Редстоунова лампа', 'Датчик денного світла', 0, 'Липкий поршень найкраще відповідає описаній механіці редстоуну або вимірів. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 119, false),
  ('note-block-plays-musical-tone', 'Ти збираєш портал, сигнал або прогрес до Краю й маєш правильно поєднати ресурс, моба або компонент. Який декоративний блок відтворює музичну ноту після імпульсу? На основі цього обери компонент, ресурс або правило прогресії, яке спрацює.', 'Точило', 'Бочка', 'Нотний блок', 'Скриня', 2, 'Нотний блок найкраще відповідає описаній механіці редстоуну або вимірів. Тут важливо застосувати правило до ситуації, а не просто впізнати слово.', 120, false)
) as v(content_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, sort_order, is_active)
where pack.slug = 'minecraft-ru-medium'
on conflict (pack_id, content_id) do update set
  prompt = excluded.prompt,
  option_a = excluded.option_a,
  option_b = excluded.option_b,
  option_c = excluded.option_c,
  option_d = excluded.option_d,
  correct_option = excluded.correct_option,
  explanation = excluded.explanation,
  sort_order = excluded.sort_order,
  is_active = excluded.is_active;

insert into public.question_packs (category_id, locale, age_band, difficulty, title, slug, is_active)
select id, 'ru', '8-12', 'hard', 'MineMind ru hard', 'minecraft-ru-hard', true
from public.quiz_categories
where slug = 'minecraft'
on conflict (slug) do update set is_active = true, title = excluded.title;

insert into public.questions (pack_id, content_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, sort_order, is_active)
select pack.id, v.content_id, v.prompt, v.option_a, v.option_b, v.option_c, v.option_d, v.correct_option, v.explanation, v.sort_order, v.is_active
from public.question_packs pack
cross join (values
  ('ancient-city-deep-dark', 'Про-режим: ти ведеш довгу експедицію без зовнішньої мапи й маєш відрізнити біом або структуру за практичними наслідками для маршруту; для рейду по скалк-лут і уникнення вардена треба заздалегідь знати, в якому біомі шукати стародавні міста. Який це біом? На основі механіки Minecraft визнач правильну місцевість або споруду.', 'Темні глибини', 'Сталактитові печери', 'Зарослі печери', 'Базальтові дельти', 0, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 1, false),
  ('badlands-above-ground-mineshafts', 'Про-режим: ти ведеш довгу експедицію без зовнішньої мапи й маєш відрізнити біом або структуру за практичними наслідками для маршруту; ти шукаєш відкриті покинуті шахти без довгого копання під землею. Який біом найчастіше дає таку перевагу? На основі механіки Minecraft визнач правильну місцевість або споруду.', 'Безплідні землі', 'Грибні поля', 'Теплий океан', 'Вишневий гай', 0, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 2, false),
  ('bastion-remnant-nether', 'Про-режим: ти ведеш довгу експедицію без зовнішньої мапи й маєш відрізнити біом або структуру за практичними наслідками для маршруту; маршрут за золотом, піглінами й небезпечними залишками бастіонів планують у конкретному вимірі. Де вони генеруються? На основі механіки Minecraft визнач правильну місцевість або споруду.', 'Звичайний світ', 'Незер', 'Всі розміри', 'Край', 1, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 3, false),
  ('buried-treasure-found-from-map', 'Про-режим: ти ведеш довгу експедицію без зовнішньої мапи й маєш відрізнити біом або структуру за практичними наслідками для маршруту; після корабельної аварії ти не копаєш навмання, а йдеш за предметом, що веде до X на узбережжі. Що це? На основі механіки Minecraft визнач правильну місцевість або споруду.', 'Карта скарбів', 'Зачарована книга', 'Дзвіночок', 'Козячий ріг', 0, 'Закопані скарби зазвичай шукають за картою скарбів. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 4, false),
  ('deep-dark-has-sculk', 'Про-режим: ти ведеш довгу експедицію без зовнішньої мапи й маєш відрізнити біом або структуру за практичними наслідками для маршруту; якщо навколо скалк, сенсори й ризик викликати вардена, який біом ти фактично знайшов? На основі механіки Minecraft визнач правильну місцевість або споруду.', 'Пляж', 'Савана', 'Темні глибини', 'Річка', 2, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 5, false),
  ('desert-well-desert', 'Про-режим: ти ведеш довгу експедицію без зовнішньої мапи й маєш відрізнити біом або структуру за практичними наслідками для маршруту; під час спідран-маршруту ти бачиш малу криницю без луту; вона прив’язана до сухого біома. Якого? На основі механіки Minecraft визнач правильну місцевість або споруду.', 'Лука', 'Мангрове болото', 'Крижані вершини', 'Пустеля', 3, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 6, false),
  ('end-city-has-shulkers', 'Про-режим: ти ведеш довгу експедицію без зовнішньої мапи й маєш відрізнити біом або структуру за практичними наслідками для маршруту; тобі потрібні шалкерові панцирі для коробок, тож ціль — структура, де шалкери спавняться природно. Яка? На основі механіки Minecraft визнач правильну місцевість або споруду.', 'Іглу', 'Храм джунглів', 'Місто Енду', 'Пустельний колодязь', 2, 'Шалкери мешкають у містах Енду, де також можна знайти цінну здобич. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 7, false),
  ('end-city-outer-end', 'Про-режим: ти ведеш довгу експедицію без зовнішньої мапи й маєш відрізнити біом або структуру за практичними наслідками для маршруту; після дракона ти йдеш через портал-шлюз і шукаєш елітри. У якому регіоні з’являються міста Енду? На основі механіки Minecraft визнач правильну місцевість або споруду.', 'Надсвітове дно океану', 'Зовнішні острови Енду', 'Будь-який сільський біом', 'Дах Незеру', 1, 'Міста Енду генеруються на зовнішніх островах Енду, а не біля центрального острова дракона. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 8, false),
  ('frozen-ocean-has-icebergs', 'Про-режим: ти ведеш довгу експедицію без зовнішньої мапи й маєш відрізнити біом або структуру за практичними наслідками для маршруту; для льодових ресурсів і айсбергів ти обираєш океанічний біом із холодною генерацією. Який саме? На основі механіки Minecraft визнач правильну місцевість або споруду.', 'Болото', 'Теплий океан', 'Замерзлий океан', 'Безплідні землі', 2, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 9, false),
  ('mushroom-fields-safe-from-many-mobs', 'Какой биом известен тем, что там не появляется много обычных враждебных мобов?', 'Грибные поля', 'Саванна', 'Тайга', 'Каменистые вершины', 0, 'Грибные поля необычные и спокойные, поэтому там особенно безопасно исследовать мир.', 10, true),
  ('nether-fortress-has-blazes', 'Про-режим: ти ведеш довгу експедицію без зовнішньої мапи й маєш відрізнити біом або структуру за практичними наслідками для маршруту; для стрижнів іфрита й прогресу до Краю треба знайти структуру з природними спавнерами іфритів. Яку? На основі механіки Minecraft визнач правильну місцевість або споруду.', 'Підводні руїни', 'Фортеця Незеру', 'Розбійницька застава', 'Лісовий маєток', 1, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 11, false),
  ('ruined-portal-two-dimensions', 'Про-режим: ти ведеш довгу експедицію без зовнішньої мапи й маєш відрізнити біом або структуру за практичними наслідками для маршруту; ти фармиш скрині зруйнованих порталів і враховуєш, у яких вимірах вони можуть згенеруватися. Яка пара правильна? На основі механіки Minecraft визнач правильну місцевість або споруду.', 'Незер і Край', 'Звичайний світ і Край', 'Звичайний світ і Незер', 'Лише звичайний світ', 2, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 12, false),
  ('stronghold-holds-end-portal', 'Какая подземная структура содержит комнату с порталом в Край?', 'Древний город', 'Крепость', 'Аванпост разбойников', 'Деревня', 1, 'Крепости особенные тем, что их портал-комната ведёт в измерение Край.', 13, true),
  ('trial-chamber-underground', 'Про-режим: ти ведеш довгу експедицію без зовнішньої мапи й маєш відрізнити біом або структуру за практичними наслідками для маршруту; для пробних спавнерів і ключів треба планувати підземний рейд, а не пошук на поверхні. Де шукати пробні палаци? На основі механіки Minecraft визнач правильну місцевість або споруду.', 'Над річками', 'Всередині сіл', 'Під землею', 'У точці появи світу', 2, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 14, false),
  ('woodland-mansion-dark-forest', 'Про-режим: ти ведеш довгу експедицію без зовнішньої мапи й маєш відрізнити біом або структуру за практичними наслідками для маршруту; щоб знайти заклиначів і тотеми без рейду, ти йдеш за маєтком у правильний біом. Який? На основі механіки Minecraft визнач правильну місцевість або споруду.', 'Савана', 'Пустеля', 'Темний ліс', 'Березовий ліс', 2, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 15, false),
  ('honey-block-slows-slide', 'Про-режим: ти проектуєш механізм або складну базу й маєш вибрати блок за точною фізикою, дропом або редстоун-поведінкою; у паркурі або механізмі треба блок, що липко сповільнює ковзання сутностей по боковій грані. Який? На основі механіки Minecraft обери блок або будівельну поведінку, яка спрацює в грі.', 'Вугільний блок', 'Морський ліхтар', 'Склоблок', 'Медовий блок', 3, 'Поведінка блока в світі збігається з описаною будівельною ситуацією. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 16, false),
  ('piston-pushes-blocks', 'Какой редстоун-блок может толкать другой блок вперёд?', 'Наблюдатель', 'Выбрасыватель', 'Компаратор', 'Поршень', 3, 'Поршни являются классическими редстоун-блоками для толкания и перемещения других блоков.', 17, true),
  ('scaffolding-climbs-fast', 'Какой блок из бамбука позволяет строителям быстро подниматься и спускаться?', 'Мишень', 'Книжная полка', 'Подмостки', 'Точило', 2, 'Подмостки отлично подходят для высоких построек, потому что по ним легко лазать и убирать их.', 18, true),
  ('slime-block-bounces-fall', 'Про-режим: ти проектуєш механізм або складну базу й маєш вибрати блок за точною фізикою, дропом або редстоун-поведінкою; для трюкового спуску або лаунчера потрібен блок, що гасить падіння відскоком угору. Який? На основі механіки Minecraft обери блок або будівельну поведінку, яка спрацює в грі.', 'Моховий блок', 'Гравій', 'Книжкова шафа', 'Слизовий блок', 3, 'Поведінка блока в світі збігається з описаною будівельною ситуацією. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 19, false),
  ('stairs-make-corners', 'Какой тип блока может автоматически менять форму, чтобы делать аккуратные углы?', 'Нажимные плиты', 'Ступеньки', 'Стеклянные панели', 'Калитки', 1, 'Ступеньки соединяются в угловые формы, поэтому крыши и дорожки выглядят плавнее.', 20, true),
  ('blast-furnace-smelts-ore-fast', 'Какой блок превращает сырое золото в слитки вдвое быстрее обычного?', 'Стол картографа', 'Коптильня', 'Камнерез', 'Плавильная печь', 3, 'Этот блок работает только с рудой и металлическим снаряжением, зато вдвое быстрее.', 21, true),
  ('compass-needs-redstone', 'Какой предмет лежит в центре рецепта компаса, окружённый железом?', 'Сахар', 'Светокаменная пыль', 'Огненный порошок', 'Редстоуновая пыль', 3, 'Четыре железных слитка вокруг редстоуновой пыли дают компас, указывающий на точку появления мира.', 22, true),
  ('hopper-moves-items-between-containers', 'Какой блок вытягивает предметы из сундука, стоящего над ним?', 'Наблюдатель', 'Воронка', 'Бочка', 'Выбрасыватель', 1, 'Воронка забирает предметы из контейнера над собой и передаёт туда, куда смотрит её носик.', 23, true),
  ('smithing-table-upgrades-netherite', 'Где улучшают алмазное снаряжение до незеритового?', 'Наковальня', 'Плавильная печь', 'Чародейский стол', 'Стол кузнеца', 3, 'Он объединяет алмазное снаряжение, незеритовый слиток и шаблон незеритового улучшения.', 24, true),
  ('smoker-cooks-food-faster', 'Какой блок готовит еду вдвое быстрее печи?', 'Костёр', 'Коптильня', 'Камнерез', 'Плавильная печь', 1, 'Коптильня работает только с едой, зато готовит её вдвое быстрее.', 25, true),
  ('campfire-calms-bees', 'Что поставить под улей, чтобы пчёлы не злились, когда берёшь мёд?', 'Факел', 'Колокол', 'Костёр', 'Фонарь', 2, 'Дым от костра под ульем успокаивает пчёл, и они не нападают, когда ты собираешь мёд.', 26, true),
  ('composter-makes-bone-meal', 'Какой блок превращает лишние семена и растения в костную муку?', 'Точило', 'Коптильня', 'Котёл', 'Компостница', 3, 'Каждое растение может поднять уровень, а заполненная компостница даёт одну костную муку.', 27, true),
  ('silk-touch-moves-bee-nest', 'Какое зачарование позволяет забрать пчелиное гнездо вместе с пчёлами?', 'Удача', 'Эффективность', 'Прочность', 'Шёлковое касание', 3, 'Шёлковое касание даёт гнездо предметом вместе с пчёлами, а без него пчелиное гнездо ничего не даёт.', 28, true),
  ('cat-scares-creepers', 'Какого питомца боятся и обходят стороной криперы?', 'Волк', 'Кошка', 'Аксолотль', 'Лошадь', 1, 'Криперы боятся кошек и оцелотов, поэтому кошка у базы отпугивает их.', 29, true),
  ('charged-creeper-lightning', 'Что превращает обычного крипера в заряженного?', 'Полнолуние', 'Удар молнии', 'Взрывное зелье', 'Редстоун-сигнал', 1, 'Молния рядом с крипером заряжает его, и взрыв становится намного сильнее.', 30, true),
  ('smite-hurts-undead', 'Какое зачарование меча добавляет урон только нежити?', 'Отдача', 'Добыча', 'Небесная кара', 'Острота', 2, 'Небесная кара усиливает удары по нежити, а Острота — по всем мобам.', 31, true),
  ('wither-skeleton-drops-skull', 'Сколько черепов визер-скелета нужно, чтобы призвать Визера?', '5', '4', '1', '3', 3, 'Визера строят из 4 блоков песка или почвы душ и 3 черепов сверху.', 32, true),
  ('eye-of-ender-finds-stronghold', 'Какой предмет помогает найти крепость перед путешествием в Край?', 'Око Эндера', 'Часы', 'Жемчуг Эндера', 'Огненный заряд', 3, 'Глаза Эндера летят в сторону крепости и помогают найти путь к портал-комнате.', 33, true),
  ('magma-block-pulls-down-bubbles', 'Какой блок заставляет водяной пузырьковый столб тянуть игроков вниз?', 'Призмарин', 'Морской фонарь', 'Магмовый блок', 'Песок душ', 2, 'Магмовый блок создаёт нисходящий пузырьковый столб, а песок душ толкает вверх.', 34, true),
  ('observer-detects-updates', 'Про-режим: ти проходиш прогресію між вимірами або збираєш механізм, де важить точна умова сигналу, предмета чи структури; фермі потрібен короткий імпульс, коли перед компонентом змінюється блок або стан блока. Що ставлять? На основі механіки Minecraft обери компонент, ресурс або правило прогресії, яке спрацює.', 'Спостерігач', 'Компостер', 'Датчик денного світла', 'Дзвін', 0, 'Спостерігач найкраще відповідає описаній механіці редстоуну або вимірів. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 35, false),
  ('respawn-anchor-charged-glowstone', 'Про-режим: ти проходиш прогресію між вимірами або збираєш механізм, де важить точна умова сигналу, предмета чи структури; точку відродження в Незері треба зарядити витратним світним ресурсом перед використанням. Чим заряджають якір? На основі механіки Minecraft обери компонент, ресурс або правило прогресії, яке спрацює.', 'Редстоуновий пил', 'Світлокамінь', 'Кварц', 'Стрижень іфрита', 1, 'У прогресії між вимірами або редстоун-механіці ця умова є вирішальною. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 36, false),
  ('warped-forest-many-endermen', 'Какой биом Незера является одним из самых безопасных мест, где можно найти много эндерменов?', 'Долина песка душ', 'Искажённый лес', 'Багровый лес', 'Базальтовые дельты', 1, 'В искажённых лесах много эндерменов и меньше опасных пиглинов и хоглинов, чем в некоторых других биомах Незера.', 37, true),
  ('campfire-cooks-without-fuel', 'Какой блок готовит еду без всякого топлива?', 'Костёр', 'Печь', 'Верстак', 'Коптильня', 0, 'Горящий костёр бесплатно готовит до четырёх штук еды, а печи и коптильни сжигают топливо.', 38, true),
  ('honey-bottle-clears-poison', 'Какой предмет снимает отравление без молока?', 'Печенье', 'Яблоко', 'Бутылочка мёда', 'Паучий глаз', 2, 'Мёд снимает только отравление, поэтому полезные эффекты зелий остаются.', 39, true),
  ('powder-snow-needs-leather-boots', 'Какие ботинки позволяют ходить по рыхлому снегу, не проваливаясь?', 'Алмазные ботинки', 'Кольчужные ботинки', 'Кожаные ботинки', 'Железные ботинки', 2, 'Только кожаные ботинки держат тебя на рыхлом снегу, в других ты провалишься и замерзнешь.', 40, true),
  ('pumpkin-stops-enderman-stare', 'Что можно надеть на голову, чтобы безопасно смотреть на эндерменов?', 'Вырезанная тыква', 'Черепаший панцирь', 'Койф', 'Кожаный шлем', 0, 'Вырезанная тыква прячет твой взгляд от эндерменов, хотя закрывает часть обзора.', 41, true),
  ('totem-of-undying-saves-once', 'Какой редкий предмет может один раз спасти от смерти?', 'Сердце моря', 'Звезда Незера', 'Золотое яблоко', 'Тотем бессмертия', 3, 'Тотем в руке тратится, оставляет тебя живым с половиной сердца и дает эффекты лечения.', 42, true),
  ('aqua-affinity-speeds-underwater-mining', 'Про-режим: ти оптимізуєш торговий зал або фінальне спорядження й маєш врахувати професію, ресток, книгу, досвід або сумісність чарів; підводний видобуток повільний, тож шолому потрібне зачарування саме на швидкість копання у воді. Яке? На основі механіки Minecraft обери професію, станцію, ресурс або зачарування без плутанини.', 'Нескінченність', 'Невагомість', 'Рідність води', 'Гострота', 2, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 43, false),
  ('channeling-needs-thunderstorm', 'Про-режим: ти оптимізуєш торговий зал або фінальне спорядження й маєш врахувати професію, ресток, книгу, досвід або сумісність чарів; тризуб із Ченнелінгом не викликає блискавку будь-коли; потрібна конкретна погода. Яка? На основі механіки Minecraft обери професію, станцію, ресурс або зачарування без плутанини.', 'Будь-яка печера', 'Снігова буря', 'Гроза', 'Ясний схід сонця', 2, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 44, false),
  ('efficiency-speeds-mining', 'Про-режим: ти оптимізуєш торговий зал або фінальне спорядження й маєш врахувати професію, ресток, книгу, досвід або сумісність чарів; для маяка, шахти або масового копання інструмент має ламати блоки швидше без зміни дропу. Яке зачарування? На основі механіки Minecraft обери професію, станцію, ресурс або зачарування без плутанини.', 'Грабунок', 'Прокляття прив''язування', 'Ефективність', 'Шипи', 2, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 45, false),
  ('fortune-increases-ore-drops', 'Про-режим: ти оптимізуєш торговий зал або фінальне спорядження й маєш врахувати професію, ресток, книгу, досвід або сумісність чарів; при видобутку руд важливо збільшити кількість дропу, а не зберегти сам блок. Яке зачарування потрібне? На основі механіки Minecraft обери професію, станцію, ресурс або зачарування без плутанини.', 'Дихання', 'Поштовх', 'Удача', 'Відкидання', 2, 'Удача найкраще відповідає описаній механіці села або зачарувань. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 46, false),
  ('frost-walker-freezes-water', 'Про-режим: ти оптимізуєш торговий зал або фінальне спорядження й маєш врахувати професію, ресток, книгу, досвід або сумісність чарів; маршрут через воду треба проходити без човна, тимчасово створюючи лід під ногами. Яке зачарування чобіт це робить? На основі механіки Minecraft обери професію, станцію, ресурс або зачарування без плутанини.', 'Швидкість душ', 'Біг крадькома', 'Швидке заряджання', 'Льодохід', 3, 'Льодохід найкраще відповідає описаній механіці села або зачарувань. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 47, false),
  ('golden-apple-cures-zombie-villager', 'Про-режим: ти оптимізуєш торговий зал або фінальне спорядження й маєш врахувати професію, ресток, книгу, досвід або сумісність чарів; після накладання Слабкості зомбі-селянина треба завершити лікування спеціальною їжею. Якою? На основі механіки Minecraft обери професію, станцію, ресурс або зачарування без плутанини.', 'Золоте яблуко', 'Сяйні ягоди', 'Зачарована книга', 'Тотем безсмертя', 0, 'Золоте яблуко найкраще відповідає описаній механіці села або зачарувань. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 48, false),
  ('grindstone-removes-enchantments', 'Какой блок снимает большинство чар с предмета и возвращает немного опыта?', 'Камнерез', 'Маяк', 'Точило', 'Варочная стойка', 2, 'Точило может убрать большинство чар и вернуть игроку немного опыта.', 49, true),
  ('infinity-still-needs-one-arrow', 'Про-режим: ти оптимізуєш торговий зал або фінальне спорядження й маєш врахувати професію, ресток, книгу, досвід або сумісність чарів; лук із Нескінченністю не стріляє з порожнього інвентаря. Що мінімально має залишатися? На основі механіки Minecraft обери професію, станцію, ресурс або зачарування без плутанини.', 'Вудка', 'Пляшка чарів', 'Щит', 'Хоча б одну стрілу', 3, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 50, false),
  ('looting-helps-mob-drops', 'Про-режим: ти оптимізуєш торговий зал або фінальне спорядження й маєш врахувати професію, ресток, книгу, досвід або сумісність чарів; меч налаштовують під фарм рідкісного дропу з мобів, а не під шкоду по блоках. Яке зачарування? На основі механіки Minecraft обери професію, станцію, ресурс або зачарування без плутанини.', 'Тягун', 'Грабунок', 'Полум''я', 'Протикання', 1, 'Грабунок найкраще відповідає описаній механіці села або зачарувань. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 51, false),
  ('mending-repairs-with-xp', 'Какое зачарование чинит предмет, когда ты получаешь опыт?', 'Mending', 'Thorns', 'Punch', 'Aqua Affinity', 0, 'Mending сильное тем, что очки опыта могут чинить твоё любимое снаряжение.', 52, true),
  ('protection-reduces-damage', 'Про-режим: ти оптимізуєш торговий зал або фінальне спорядження й маєш врахувати професію, ресток, книгу, досвід або сумісність чарів; для універсального сету броні потрібне загальне зменшення вхідної шкоди, а не вузька протидія лише вогню чи вибухам. Яке зачарування? На основі механіки Minecraft обери професію, станцію, ресурс або зачарування без плутанини.', 'Приманка', 'Шовковий дотик', 'Рідність води', 'Захист', 3, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 53, false),
  ('silk-touch-drops-glass', 'Про-режим: ти оптимізуєш торговий зал або фінальне спорядження й маєш врахувати професію, ресток, книгу, досвід або сумісність чарів; треба забрати скло як блок і не втратити його при ламанні. Яке зачарування інструмента потрібне? На основі механіки Minecraft обери професію, станцію, ресурс або зачарування без плутанини.', 'Гострота', 'Шовковий дотик', 'Дихання', 'Грабунок', 1, 'Шовковий дотик найкраще відповідає описаній механіці села або зачарувань. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 54, false),
  ('thorns-damages-attacker', 'Про-режим: ти оптимізуєш торговий зал або фінальне спорядження й маєш врахувати професію, ресток, книгу, досвід або сумісність чарів; броня з Шипами має побічний ефект для того, хто б’є власника. Що може статися з нападником? На основі механіки Minecraft обери професію, станцію, ресурс або зачарування без плутанини.', 'З нього випадає смарагд', 'Це може повернути шкоду', 'Змінює професію', 'Заживає миттєво', 1, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 55, false),
  ('unbreaking-reduces-durability-loss', 'Про-режим: ти оптимізуєш торговий зал або фінальне спорядження й маєш врахувати професію, ресток, книгу, досвід або сумісність чарів; для довгої експедиції важливо, щоб інструмент рідше витрачав міцність при використанні. Яке зачарування? На основі механіки Minecraft обери професію, станцію, ресурс або зачарування без плутанини.', 'Глибинний бігун', 'Сила вогню', 'Незламність', 'Нищівне лезо', 2, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 56, false),
  ('weaponsmith-uses-grindstone', 'Какая профессия жителя использует точило как рабочий блок?', 'Священник', 'Оружейник', 'Инструментальщик', 'Бронник', 1, 'Точило относится к оружейнику, который специализируется на мечах и топорах.', 57, true),
  ('golden-apple-gives-absorption', 'Какая еда дает дополнительные сердечки поглощения?', 'Сушёная ламинария', 'Тыквенный пирог', 'Свекольный суп', 'Золотое яблоко', 3, 'Золотое яблоко дает поглощение и регенерацию, полезно перед тяжелым боем.', 58, true),
  ('totem-must-be-held-in-hand', 'Где должен быть тотем бессмертия, чтобы спасти тебя?', 'В слоте брони', 'В инвентаре', 'В сундуке', 'В руке', 3, 'Тотем работает только в основной или второй руке, а не в инвентаре.', 59, true),
  ('milk-removes-bad-omen', 'Какой предмет снимает Дурной знак до прихода в деревню?', 'Загадочное рагу', 'Бутылочка мёда', 'Золотое яблоко', 'Ведро молока', 3, 'Молоко снимает Дурной знак, поэтому ты войдешь в деревню без набега.', 60, true),
  ('bed-explodes-in-nether-survival', 'Что будет, если попробовать спать в кровати в Незере?', 'Ночь пропускается', 'Взрывается', 'Ничего не происходит', 'Сохраняется точка появления', 1, 'Кровати взрываются в Незере и Энде, поэтому там используй якорь возрождения.', 61, true),
  ('zombie-breaks-door-on-hard', 'Какой моб на сложном уровне может выломать деревянную дверь?', 'Эндермен', 'Крипер', 'Зомби', 'Скелет', 2, 'На сложном уровне зомби ломают деревянные двери, поэтому ставь железные или закладывай вход.', 62, true),
  ('sleep-prevents-phantom-spawns', 'После скольких ночей без сна могут появиться фантомы?', '10', '1', '3', '5', 2, 'Фантомы могут появиться, если ты три игровых дня не спал и не умирал.', 63, true),
  ('respawn-anchor-sets-nether-spawn', 'Какой блок позволяет снова появиться в Незере после смерти?', 'Маяк', 'Якорь возрождения', 'Печь', 'Магнетит', 1, 'Каждый светокамень добавляет заряд, а каждое возрождение у якоря тратит один.', 64, true),
  ('ender-pearl-teleports-player', 'Какой брошенный предмет переносит тебя туда, где он упал?', 'Яйцо', 'Эндер-жемчуг', 'Снежок', 'Трезубец', 1, 'Эндер-жемчуг переносит тебя на место падения, но отнимает немного здоровья.', 65, true),
  ('magma-block-pulls-downward', 'С какой наибольшей высоты в блоках можно упасть без урона?', '3', '2', '5', '8', 0, 'Падение с 3 блоков безопасно, а с 4 и выше ты уже теряешь здоровье.', 66, true),
  ('soul-sand-pushes-upward', 'Какой блок под водой создает столб пузырей, поднимающий вверх?', 'Магма', 'Гравий', 'Песок душ', 'Обсидиан', 2, 'Песок душ создает столб пузырей вверх, удобный для быстрых водяных лифтов.', 67, true),
  ('glass-pane-from-glass-blocks', 'Сколько стеклянных панелей дают шесть блоков стекла?', '6', '8', '16', '12', 2, 'Шесть блоков стекла превращаются в шестнадцать панелей, поэтому ими выгодно стеклить большие окна.', 68, true),
  ('blast-furnace-not-for-food', 'Какой из этих блоков не может приготовить сырую еду?', 'Коптильня', 'Печь', 'Плавильная печь', 'Костёр', 2, 'Плавильная печь переплавляет только руду, сырой металл и металлическое снаряжение, так что еду там не приготовить.', 69, true),
  ('smoker-not-for-ores', 'Что из этого коптильня не сможет обработать?', 'Картофель', 'Сырая треска', 'Рудное железо', 'Сырая говядина', 2, 'Коптильня работает только с едой, так что рудное железо нужно нести в печь или плавильную печь.', 70, true),
  ('cartography-table-expands-maps-crafting', 'Что добавляют к карте в столе картографа, чтобы отдалить её?', 'Компас', 'Стеклянная панель', 'Чернильный мешок', 'Бумага', 3, 'Один лист бумаги отдаляет карту на уровень, и она показывает большую область с меньшей детализацией.', 71, true),
  ('brewing-stand-makes-potions-crafting', 'Какой предмет вместе с тремя булыжниками даёт зельеварку?', 'Огненный стержень', 'Железный слиток', 'Огненный порошок', 'Палка', 0, 'Огненный стержень становится опорой зельеварки, так что перед зельеварением нужно победить всполоха.', 72, true),
  ('stonecutter-chooses-stone-shapes', 'Сколько каменных плит даёт камнерез из одного блока камня?', '2', '1', '8', '3', 0, 'Один блок делится на две плиты — как и на верстаке, но без необходимости класть три блока сразу.', 73, true),
  ('anvil-can-break-from-use', 'Какая станция повреждается от использования и в итоге ломается?', 'Точило', 'Наковальня', 'Стол картографа', 'Стол кузнеца', 1, 'Каждое использование с шансом 12% повреждает наковальню, а после третьей стадии она ломается.', 74, true),
  ('loom-simplifies-banner-patterns', 'Что, кроме досок, нужно, чтобы скрафтить ткацкий станок?', 'Шерсть', 'Железный слиток', 'Нить', 'Кожа', 2, 'Две нити над двумя досками дают ткацкий станок.', 75, true),
  ('obsidian-needed-for-enchanting-table', 'Какой блок, кроме алмазов и книги, нужен для чародейского стола?', 'Базальт', 'Обсидиан', 'Угольный блок', 'Глубинный сланец', 1, 'Четыре обсидиана, два алмаза и книга дают стол, так что сначала нужна алмазная кирка.', 76, true),
  ('redstone-needed-for-clock', 'Какой предмет окружает редстоуновую пыль в рецепте часов?', 'Железный слиток', 'Изумруд', 'Золотой слиток', 'Медный слиток', 2, 'Четыре золотых слитка вокруг редстоуна дают часы, а железные в той же форме — компас.', 77, true),
  ('obsidian-needs-diamond-pickaxe', 'Про-режим: ти проектуєш механізм або складну базу й маєш вибрати блок за точною фізикою, дропом або редстоун-поведінкою; портал будується з міцного блоку, але щоб забрати його як дроп, потрібен правильний рівень інструмента. Який мінімум? На основі механіки Minecraft обери блок або будівельну поведінку, яка спрацює в грі.', 'Ножиці', 'Дерев''яне кайло', 'Діамантове кайло', 'Кам''яне кайло', 2, 'Поведінка блока в світі збігається з описаною будівельною ситуацією. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 78, false),
  ('deepslate-mines-slower-than-stone', 'Про-режим: ти проектуєш механізм або складну базу й маєш вибрати блок за точною фізикою, дропом або редстоун-поведінкою; у глибоких шарах темп шахти падає, бо один кам’яний варіант ламається повільніше за звичайний камінь. Який? На основі механіки Minecraft обери блок або будівельну поведінку, яка спрацює в грі.', 'Пісок', 'Вовна', 'Глибосланець', 'Ґрунт', 2, 'Глибосланець — саме той блок чи предмет, що підходить до описаної властивости або будівельної ситуації. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 79, false),
  ('glowstone-drops-dust-when-broken', 'Про-режим: ти проектуєш механізм або складну базу й маєш вибрати блок за точною фізикою, дропом або редстоун-поведінкою; у Незері світний блок без Шовкового дотику зазвичай дає пил, а не сам блок. Який? На основі механіки Minecraft обери блок або будівельну поведінку, яка спрацює в грі.', 'Світлокамінь', 'Базальт', 'Пісок душ', 'Незерак', 0, 'Світлокамінь — саме той блок чи предмет, що підходить до описаної властивости або будівельної ситуації. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 80, false),
  ('nether-quartz-ore-drops-quartz', 'Про-режим: ти проектуєш механізм або складну базу й маєш вибрати блок за точною фізикою, дропом або редстоун-поведінкою; для компараторів і білого декору потрібен ресурс із руди з білими вкрапленнями у Незері. Яка руда? На основі механіки Minecraft обери блок або будівельну поведінку, яка спрацює в грі.', 'Незерська кварцова руда', 'Залізна руда', 'Вугільна руда', 'Смарагдова руда', 0, 'Незерська кварцова руда найкраще пасує до описаної поведінки блока або будівельного використання. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 81, false),
  ('copper-oxidizes-green-over-time', 'Про-режим: ти проектуєш механізм або складну базу й маєш вибрати блок за точною фізикою, дропом або редстоун-поведінкою; для декоративних білдів треба врахувати метал, який із часом зеленіє на повітрі. Який матеріал? На основі механіки Minecraft обери блок або будівельну поведінку, яка спрацює в грі.', 'Мідь', 'Залізо', 'Кварц', 'Золото', 0, 'Мідні блоки з часом окиснюються й поступово зеленіють. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 82, false),
  ('scaffolding-extends-outward-with-support', 'Про-режим: ти проектуєш механізм або складну базу й маєш вибрати блок за точною фізикою, дропом або редстоун-поведінкою; тимчасова платформа може виступати вбік лише до певної межі без нижньої опори. Який блок має це правило? На основі механіки Minecraft обери блок або будівельну поведінку, яка спрацює в грі.', 'Шибка', 'Паркан', 'Підмостки', 'Драбина', 2, 'Поведінка блока в світі збігається з описаною будівельною ситуацією. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 83, false),
  ('trapdoor-makes-ladder-hatch', 'Про-режим: ти проектуєш механізм або складну базу й маєш вибрати блок за точною фізикою, дропом або редстоун-поведінкою; вертикальний лаз над драбиною треба закривати тонким шарнірним блоком у стелі. Що ставлять? На основі механіки Minecraft обери блок або будівельну поведінку, яка спрацює в грі.', 'Люк', 'Килим', 'Рейки', 'Дзвін', 0, 'Люк — саме той блок чи предмет, що підходить до описаної властивости або будівельної ситуації. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 84, false),
  ('fence-connects-into-lines', 'Про-режим: ти проектуєш механізм або складну базу й маєш вибрати блок за точною фізикою, дропом або редстоун-поведінкою; для загонів потрібен блок, що сам з’єднується з сусідніми такими ж блоками в довгу лінію. Що це? На основі механіки Minecraft обери блок або будівельну поведінку, яка спрацює в грі.', 'Паркан', 'Ліхтар', 'Скло', 'Смолоскип', 0, 'Поведінка блока в світі збігається з описаною будівельною ситуацією. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 85, false),
  ('piston-cannot-push-obsidian', 'Про-режим: ти проектуєш механізм або складну базу й маєш вибрати блок за точною фізикою, дропом або редстоун-поведінкою; у поршневій схемі є блок, який звичайний поршень не зрушить навіть із сигналом. Який? На основі механіки Minecraft обери блок або будівельну поведінку, яка спрацює в грі.', 'Вовна', 'Обсидіан', 'Пісок', 'Ґрунт', 1, 'Поведінка блока в світі збігається з описаною будівельною ситуацією. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 86, false),
  ('slime-block-drags-neighboring-blocks', 'Про-режим: ти проектуєш механізм або складну базу й маєш вибрати блок за точною фізикою, дропом або редстоун-поведінкою; літаючий механізм має тягнути сусідні блоки разом із рухом поршня. Який липкий блок це робить? На основі механіки Minecraft обери блок або будівельну поведінку, яка спрацює в грі.', 'Лід', 'Вугільний блок', 'Скло', 'Слизовий блок', 3, 'Слизовий блок найкраще пасує до описаної поведінки блока або будівельного використання. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 87, false),
  ('tropical-fish-breeds-axolotls', 'Чем кормят аксолотлей, чтобы они размножились?', 'Треска в ведре', 'Иглобрюх в ведре', 'Тропическая рыба в ведре', 'Лосось в ведре', 2, 'Аксолотли берут только живую тропическую рыбу в ведре, а ведро с водой возвращается тебе.', 88, true),
  ('slimeball-breeds-frogs', 'Каким предметом разводят лягушек?', 'Паучий глаз', 'Сгусток слизи', 'Ламинария', 'Сгусток магмы', 1, 'В природе лягушки едят маленьких слизней, поэтому сгустки слизи заставляют их размножаться и метать икру.', 89, true),
  ('beetroot-crafts-into-soup', 'Сколько свёклы нужно, чтобы скрафтить один свекольный суп?', '8', '6', '3', '4', 1, 'Для свекольного супа нужно 6 штук свёклы и миска — немало урожая на одно блюдо.', 90, true),
  ('striders-breed-with-warped-fungus', 'Каким предметом разводят лавомерок?', 'Багровый гриб', 'Красный гриб', 'Незерский нарост', 'Искажённый гриб', 3, 'Лавомерки любят искажённые грибы: ими их разводят, а на удочке гриб помогает управлять лавомеркой.', 91, true),
  ('turtles-breed-with-seagrass', 'Каким растением кормят черепах, чтобы они размножились?', 'Кувшинка', 'Сахарный тростник', 'Ламинария', 'Морская трава', 3, 'Черепахи едят морскую траву; накормленная черепаха плывёт к родному пляжу и откладывает яйца в песок.', 92, true),
  ('foxes-breed-with-sweet-berries', 'Какой едой разводят лис?', 'Сладкие ягоды', 'Ломтик арбуза', 'Свёкла', 'Яблоко', 0, 'Лисы любят ягоды: и сладкие, и светящиеся ягоды заставляют их размножаться.', 93, true),
  ('potato-smelts-into-baked-potato', 'Какая из этих культур становится сытнее после готовки в печи?', 'Морковь', 'Картофель', 'Тыква', 'Свёкла', 1, 'Из картофеля в печи получается печёный картофель, который утоляет голод намного лучше сырого.', 94, true),
  ('flower-turns-stew-suspicious', 'Что, кроме миски и двух грибов, нужно для загадочного рагу?', 'Паучий глаз', 'Цветок', 'Сахар', 'Пшеница', 1, 'Цветок определяет скрытый эффект рагу: например, одуванчик восстанавливает сытость.', 95, true),
  ('cake-uses-three-milk-buckets', 'Сколько вёдер молока нужно для одного торта?', '1', '4', '2', '3', 3, 'Торт занимает весь верхний ряд вёдрами молока, а пустые вёдра возвращаются в инвентарь.', 96, true),
  ('nether-wart-grows-on-soul-sand', 'На какой блок обязательно сажают незерский нарост?', 'Пашня', 'Незерак', 'Почва душ', 'Песок душ', 3, 'Незерский нарост растёт только на песке душ, поэтому зельевары несут песок душ домой для фермы.', 97, true),
  ('pumpkin-needs-empty-space-beside-stem', 'Какой минимальный уровень света нужен посевам, чтобы расти?', '9', '15', '4', '12', 0, 'Посевам нужен свет уровня 9 или больше, поэтому подземной ферме нужны факелы или лампы.', 98, true),
  ('cactus-breaks-when-side-touches-block', 'Какое растение ломается, если рядом с ним поставить твёрдый блок?', 'Пшеница', 'Бамбук', 'Сахарный тростник', 'Кактус', 3, 'Кактус выпадает предметом, когда сбоку стоит твёрдый блок, — на этом работают кактусовые фермы.', 99, true),
  ('tamed-wolf-attacks-hostiles', 'Какого враждебного моба приручённый волк никогда не атакует?', 'Ведьма', 'Скелет', 'Крипер', 'Зомби', 2, 'Приручённые волки бьются с большинством мобов, но криперов не трогают.', 100, true),
  ('piglin-barters-with-gold', 'Какой моб Незера обменивает золотые слитки на случайные предметы?', 'Пиглин', 'Визер-скелет', 'Зомбифицированный пиглин', 'Хоглин', 0, 'Пиглин берёт брошенный золотой слиток, рассматривает его и бросает в ответ случайный предмет.', 101, true),
  ('zombified-piglin-angers-group', 'Какой нейтральный моб Незера поднимает в атаку всю группу, если ударить одного?', 'Эндермен', 'Магмовый куб', 'Зомбифицированный пиглин', 'Лавомерка', 2, 'Удар по одному зомбифицированному пиглину злит всех рядом, и начинается большая драка.', 102, true),
  ('bees-swarm-after-nest-broken', 'Какой моб, танцуя у проигрывателя, размножается, если дать ему осколок аметиста?', 'Пчела', 'Тихоня', 'Вредина', 'Попугай', 1, 'Тихоня, танцующая под музыку, от осколка аметиста создаёт свою копию, а потом 5 минут отдыхает.', 103, true),
  ('iron-golem-hits-hard-if-provoked', 'Сколько железных блоков нужно, чтобы построить железного голема?', '6', '3', '5', '4', 3, 'Поставь 4 железных блока буквой Т и вырезанную тыкву сверху — появится голем.', 104, true),
  ('evoker-summons-vexes', 'Какой иллагер колдует и призывает летающих вредин?', 'Ведьма', 'Заклинатель', 'Разбойник', 'Поборник', 1, 'Заклинатели призывают вредин и клыки из земли, а после победы оставляют тотем бессмертия.', 105, true),
  ('guardian-fires-laser-beam', 'Какой моб океанского монумента атакует лазерным лучом?', 'Утопленник', 'Страж', 'Спрут', 'Иглобрюх', 1, 'Стражи наводят луч, который заряжается, а затем наносит урон даже под водой.', 106, true),
  ('endermite-can-spawn-from-pearl', 'Какой крошечный враждебный моб может появиться при падении брошенного эндер-жемчуга?', 'Чешуйница', 'Пещерный паук', 'Вредина', 'Эндермит', 3, 'Каждый брошенный эндер-жемчуг с шансом 5% порождает эндермита.', 107, true),
  ('bane-of-arthropods-vs-spiders', 'Какое зачарование наносит больше урона паукам, пчёлам и чешуйницам?', 'Бич членистоногих', 'Заговор огня', 'Острота', 'Небесная кара', 0, 'Бич членистоногих сильнее бьёт насекомоподобных мобов и ещё замедляет их.', 108, true),
  ('totem-works-from-hand-slot', 'Какое оружие бьёт сильнее, чем с большей высоты ты падаешь перед ударом?', 'Топор', 'Трезубец', 'Булава', 'Арбалет', 2, 'Булава добавляет урон в зависимости от высоты падения, поэтому ею бьют после большого прыжка.', 109, true),
  ('strength-potion-boosts-melee', 'Какое зелье делает твои удары в ближнем бою сильнее?', 'Зелье невидимости', 'Зелье прыгучести', 'Зелье плавного падения', 'Зелье силы', 3, 'Сила добавляет урон каждому удару вблизи, что очень помогает в битвах с боссами.', 110, true),
  ('twelve-eyes-activate-portal', 'Про-режим: ти проходиш прогресію між вимірами або збираєш механізм, де важить точна умова сигналу, предмета чи структури; якщо в кімнаті порталу всі рамки порожні, треба мати повний комплект очей для активації. Скільки? На основі механіки Minecraft обери компонент, ресурс або правило прогресії, яке спрацює.', 'Вісім', 'Дванадцять', 'Шістнадцять', 'Десять', 1, 'Щоб активувати портал Енду, потрібно заповнити дванадцять рамок очима Ендера. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 111, false),
  ('chorus-fruit-teleports-randomly', 'Про-режим: ти проходиш прогресію між вимірами або збираєш механізм, де важить точна умова сигналу, предмета чи структури; у Краї є їжа, що може врятувати або зіпсувати позицію випадковою телепортацією. Що це? На основі механіки Minecraft обери компонент, ресурс або правило прогресії, яке спрацює.', 'Фрукт хорусу', 'Золота морква', 'Сяйні ягоди', 'Печиво', 0, 'У прогресії між вимірами або редстоун-механіці ця умова є вирішальною. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 112, false),
  ('dragon-breath-caught-in-bottle', 'Про-режим: ти проходиш прогресію між вимірами або збираєш механізм, де важить точна умова сигналу, предмета чи структури; для осідаючих зіль треба зібрати ресурс прямо з хмари атаки дракона скляною пляшкою. Що збирають? На основі механіки Minecraft обери компонент, ресурс або правило прогресії, яке спрацює.', 'Зілля зцілення', 'Пляшка меду', 'Дихання дракона', 'Пляшка чарів', 2, 'Дихання дракона збирають у скляну пляшку з його фіолетової хмари атаки. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 113, false),
  ('elytra-found-in-end-ship', 'Про-режим: ти проходиш прогресію між вимірами або збираєш механізм, де важить точна умова сигналу, предмета чи структури; після пошуку міст Енду головна нагорода лежить на кораблі й відкриває планерування. Що це? На основі механіки Minecraft обери компонент, ресурс або правило прогресії, яке спрацює.', 'Щит', 'Тризубець', 'Тотем безсмертя', 'Елітри', 3, 'Елітри найкраще відповідає описаній механіці редстоуну або вимірів. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 114, false),
  ('crying-obsidian-crafts-anchor', 'Про-режим: ти проходиш прогресію між вимірами або збираєш механізм, де важить точна умова сигналу, предмета чи структури; для якоря відродження потрібен фіолетовий варіант міцного портального блока. Який? На основі механіки Minecraft обери компонент, ресурс або правило прогресії, яке спрацює.', 'Плакучий обсидіан', 'Незерак', 'Гладкий камінь', 'Камінь Енду', 0, 'Плакучий обсидіан найкраще відповідає описаній механіці редстоуну або вимірів. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 115, false),
  ('warped-fungus-scares-hoglins', 'Про-режим: ти проходиш прогресію між вимірами або збираєш механізм, де важить точна умова сигналу, предмета чи структури; щоб зробити табір у Незері безпечнішим від гоглінів, використовують гриб, якого вони уникають. Який? На основі механіки Minecraft обери компонент, ресурс або правило прогресії, яке спрацює.', 'Багряний гриб', 'Світлолишайник', 'Червоний гриб', 'Химерний гриб', 3, 'У прогресії між вимірами або редстоун-механіці ця умова є вирішальною. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 116, false),
  ('blue-ice-makes-fast-boat-road', 'Про-режим: ти проходиш прогресію між вимірами або збираєш механізм, де важить точна умова сигналу, предмета чи структури; для швидкісних човнових тунелів у Незері використовують найслизькіший льодовий блок. Який? На основі механіки Minecraft обери компонент, ресурс або правило прогресії, яке спрацює.', 'Кругляк', 'Пісок', 'Синій лід', 'Вовна', 2, 'У прогресії між вимірами або редстоун-механіці ця умова є вирішальною. У про-режимі схожі варіанти можуть звучати правдоподібно, але не виконують точну умову механіки.', 117, false),
  ('repeater-adds-redstone-delay', 'Про-режим: ти проходиш прогресію між вимірами або збираєш механізм, де важить точна умова сигналу, предмета чи структури; у схемі треба не просто провести сигнал, а додати контрольовану затримку імпульсу. Який компонент? На основі механіки Minecraft обери компонент, ресурс або правило прогресії, яке спрацює.', 'Дзвін', 'Повторювач', 'Кафедра', 'Компаратор', 1, 'Редстоуновий повторювач може не лише підсилювати сигнал, а й додавати затримку. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 118, false),
  ('target-block-rewards-accurate-hit', 'Про-режим: ти проходиш прогресію між вимірами або збираєш механізм, де важить точна умова сигналу, предмета чи структури; стрілецький механізм має видавати сильніший редстоун-сигнал за точніше влучання в центр. Який блок? На основі механіки Minecraft обери компонент, ресурс або правило прогресії, яке спрацює.', 'Поршень', 'Мішень', 'Кнопка', 'Натискна плита', 1, 'Мішень найкраще відповідає описаній механіці редстоуну або вимірів. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 119, false),
  ('daylight-sensor-reads-sky-light', 'Про-режим: ти проходиш прогресію між вимірами або збираєш механізм, де важить точна умова сигналу, предмета чи структури; автоматичне освітлення має реагувати на небо й час доби без ручного перемикача. Який сенсор? На основі механіки Minecraft обери компонент, ресурс або правило прогресії, яке спрацює.', 'Гак для розтяжки', 'Каменеріз', 'Спостерігач', 'Датчик денного світла', 3, 'Датчик денного світла зчитує рівень світла неба й може керувати денними або нічними схемами. У про-режимі це важливо, бо схожі варіанти часто виглядають логічно, але не виконують точну умову механіки.', 120, false)
) as v(content_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, sort_order, is_active)
where pack.slug = 'minecraft-ru-hard'
on conflict (pack_id, content_id) do update set
  prompt = excluded.prompt,
  option_a = excluded.option_a,
  option_b = excluded.option_b,
  option_c = excluded.option_c,
  option_d = excluded.option_d,
  correct_option = excluded.correct_option,
  explanation = excluded.explanation,
  sort_order = excluded.sort_order,
  is_active = excluded.is_active;
